/**
 * 웹스퀘어 $p.ajax 함수 확장 모듈, 헤더 값 등 추후 공통 사항을 추가 관리하기 위해 추가.
 * 옵션은 웹스퀘어5 api guide 문서에서 참고 할 것
 *
 * @param {String} - options.action - ajax 요청주소
 * @param {String} - options.mode - [default: asynchronous,synchronous]
 * @param {String} - options.mediatype - [default: application/xml, application/x-www-form-urlencoded, application/json, text/xml]
 * @param {String} - options.method - [default: POST, GET, PUT, DELETE]
 * @param {String} - options.requestData - 요청본문
 * @param {JSON} - options.requestHeader - request header에 지정 할 JOSN객체
 * @param {Number} - options.timeout - ajax요청후 timeout 시간. 이시간이 초과해도 응답이 오지 않는 경우 error callback함수를 실행
 * @param {String} - options.type - [xml, json] xml인 경우 success callback함수의 인자객체의 responseBody속성에 xml객체가 설정된고, json인 경우 자바스크립트 객체가 설정된다.나머지 경우는 text형식이 설정.
 * @param {Function} - options.beforeAjax - 요청전에 실행되는 함수로 이 함수내에서 false를 return하면 ajax요청을 하지 않는다
 * @param {Function} - options.success - 요청이 성공한 경우 실행되는 callback함수
 * @param {Function} - options.error - 요청이 실패한 경우 실행되는 callback함수
 * @param {Boolean} - options.passGlobalErrorHandler - 요청실패시 gcm._sbm_comErrorHandler 수행여부 [default: false(실행), true(실행안함)]
 *
 * History :
 * 2023.08.07 - 요청실패시 gcm._sbm_comErrorHandler 수행여부(options.passGlobalErrorHandler) 옵션 추가
 */
com.executeAjax = function(_cfg) {
	// Global Error Handler 수행여부 설정
    _cfg.passGlobalErrorHandler = _cfg.passGlobalErrorHandler || false;
    if (![true, false].includes(_cfg.passGlobalErrorHandler)) {
    	scutilo.showMsg(scglblo.MSG.ERROR, "Global Error Handler 수행 여부 설정 값은 boolean(true|false) 값만 가능합니다.");
    	return;
    }
    // Global Error Handler 수행여부가 true 이면 error callback 이 있는지 검증
    // 없으면 return 하여 개발자에게 error callback 등록 요청
    if (_cfg.passGlobalErrorHandler === true) {
    	if (!_cfg.hasOwnProperty("error") || !scutilo.isFunction(_cfg.error)) {
    		scutilo.showMsg(scglblo.MSG.ERROR, "Global Error Handler 수행을 하지 않도록 설정된 경우, error callback function 을 꼭 설정해주세요.");
        	return;
        }
    }

    // requestHeader에 공통 헤더값과 사용자 헤더값 머지후 추가
    _cfg.requestHeader = $.extend(true, _cfg.requestHeader, scscrno.$_h._getScRequestHeaders());
    // 기본옵션
    var options = {
        mode: gcm.DEFAULT_OPTIONS_MODE,
        mediatype: gcm.DEFAULT_OPTIONS_MEDIATYPE,
        method: 'POST',
        //timeout: 0,
    }

    options = $.extend(true, options, _cfg);
    delete options.passGlobalErrorHandler;

    options.success = function(resObj) {
        // 리프레쉬 토큰 갱신 함수 호출
    	scutilo.getSCMain().scglblo.refreshScToken(resObj.token);

        if(_cfg.success && scutilo.isFunction(_cfg.success)) {
            var argumentsArray = Array.from(arguments);
            _cfg.success.apply(options, argumentsArray);
        }
    };

    options.error = function(resObj) {
        var statusCode = resObj.responseStatusCode;

        // 리프레쉬 토큰 갱신 함수 호출
        scutilo.getSCMain().scglblo.refreshScToken(resObj.token);

        if (!_cfg.passGlobalErrorHandler) {
        	// submission/ajax중 에러가 발생한 경우 에러 처리 함수 호출
        	gcm._sbm_comErrorHandler(resObj);
    	}

        if(_cfg.error && scutilo.isFunction(_cfg.error)) {
            var argumentsArray = Array.from(arguments);
            _cfg.error.apply(options, argumentsArray);
        }
    };

    $p.ajax(options);
};

