/**
 * 유효성 검사 실패시 출력할 메시지를 반환한다.
 *
 * @date 2014.12.10
 * @private
 * @memberOf com
 * @author InswaveSystems
 * @returns {String} 유효성 검사 결과 메시지
 */
com.validateMsg = function() {
    var msg = "";
    var invalidType = this.getType(); // invalid 타입
    var invalidValue = this.getValue(); // invalid 타입별 설정값

    var callerObj = null;
    if (typeof this.getCaller === "function") {
        callerObj = this.getCaller();
    } else if (typeof this.userFunc !== "undefined") {
        callerObj = $p.getComponentById(this.userFunc.arguments[1]);
    } else {
        return;
    }

    var scopeCom = gcm._getScope(callerObj).com;
    var columnName = scopeCom.data.getColumnName(callerObj);

    switch (invalidType) {
    case "mandatory":
        msg = scopeCom.str.attachPostposition(columnName) + "필수 입력 항목 입니다.";
        break;
    case "minLength":
        msg = scopeCom.str.attachPostposition(columnName) + "최소 길이 " + invalidValue + "자리 이상으로 입력해야 합니다.";
        break;
    case "minByteLength":
        msg = scopeCom.str.attachPostposition(columnName) + "최소 길이 " + invalidValue + "바이트 이상으로 입력해야 합니다.";
        break;
    default:
        msg = scopeCom.str.attachPostposition(columnName) + "유효하지 않은 값이 입력 되었습니다.";
        break;
    }

    if (msg !== "") {
        gcm.valStatus.isValid = false;
    }

    gcm.valStatus.objectType = "group";
