/**
 * 문자(char)의 유형을 리턴한다.
 *
 * @date 2016 08.02
 * @param {String}
 *            str 어떤 유형인지 리턴받을 문자
 * @memberOf com
 * @author InswaveSystems
 * @return {Number} 유니코드 기준 <br>
 *         <br>
 *         한글음절[ 44032 ~ 55203 ] => 1 <br>
 *         한글자모[ 4352 ~ 4601 ] => 2 <br>
 *         숫자[ 48 ~ 57 ] => 4 <br>
 *         특수문자[ 32 ~ 47 || 58 ~ 64 || 91 ~ 96 || 123 ~ 126 ] => 8 <br>
 *         영문대[ 65 ~ 90 ] => 16 <br>
 *         영문소[ 97 ~ 122 ] => 32 <br>
 *         기타[그외 나머지] => 48
 * @example com.getLocale("가"); // return 예시)1 com.getLocale("ㅏ"); // return
 *          예시)2 com.getLocale("1"); // return 예시)4 com.getLocale("!"); //
 *          return 예시)8 com.getLocale("A"); // return 예시)16 com.getLocale("a"); //
 *          return 예시)32 com.getLocale("¿"); // return 예시)48
 */
com.getLocale = function(str) {
    var locale = 0;
    if (str.length > 0) {
        var charCode = str.charCodeAt(0);

        if (charCode >= 0XAC00 && charCode <= 0XD7A3) { // 한글음절.[ 44032 ~ 55203
                                                        // ]
            locale = 0X1; // 1
        } else if ((charCode >= 0X1100 && charCode <= 0X11F9) || (charCode >= 0X3131 && charCode <= 0X318E)) { // 한글자모.[
                                                                                                                // 4352
                                                                                                                // ~
                                                                                                                // 4601
                                                                                                                // ]
            locale = 0X2; // 2
        } else if (charCode >= 0X30 && charCode <= 0X39) { // 숫자.[ 48 ~ 57 ]
            locale = 0X4; // 4
        } else if ((charCode >= 0X20 && charCode <= 0X2F) || (charCode >= 0X3A && charCode <= 0X40)
                || (charCode >= 0X5B && charCode <= 0X60) || (charCode >= 0X7B && charCode <= 0X7E)) { // 특수문자
            locale = 0X8; // 8
        } else if (charCode >= 0X41 && charCode <= 0X5A) { // 영문 대.[ 65 ~ 90 ]
            locale = 0X10; // 16
        } else if (charCode >= 0X61 && charCode <= 0X7A) { // 영문 소.[ 97 ~ 122 ]
            locale = 0X20; // 32
        } else { // 기타
            locale = 0X30; // 48
        }
    }
    return locale;
};

/**
 * 사업자번호 유효성을 검사한다.
 *
 * @date 2014.12.10
