com.data.downloadGridViewExcel = function(grdObj, options, infoArr) {
    if (com.util.isEmpty(options)) {
        options = {};
    }

    if (typeof infoArr === "undefined") {
        infoArr = {};
    }

    gcm.data._downloadGridView(grdObj, options);

