/**
 * 검색 조건에 맞는 데이터를 반환한다.
 * @date 2021.02.16
 * @memberOf com.data
 * @author Inswave Systems
 * @param {Object} dataListObj : DataList Id 또는 DataList 객체
 * @param {Array|Object} condArr 비교 조건
 * @param {String} condArr.columnId 컬럼 아이디
 * @param {String} condArr.operator 비교 연산자 ( ==, !=, >, <, >=, <=, LIKE )
 * @param {String|Number|Boolean} condArr.value 비교 값
 * @param {String} condArr.logical 논리 연산자 ( &&, ||)
 * @returns {Object} DataList Id 또는 DataList 객체
 * @example
com.data.getMatchedJSON(dlt_memberList, { columnId : "POSITION_CD", operator : "==", value : "03"});

com.data.getMatchedJSON(dlt_memberList, [
    { columnId : "POSITION_CD", operator : "==", value : "03" },
    { columnId : "DUTY_CD", operator : "==", value : "02", logical : "&&" }
]);

com.data.getMatchedJSON(dlt_memberList, [
    { columnId : "POSITION_CD", operator : "==", value : "03" },
    { columnId : "DUTY_CD", operator : "==", value : "02" }
]);

com.data.getMatchedJSON(dlt_memberList, [
    { columnId : "POSITION_CD", operator : "==", value : "03"},
    { columnId : "DUTY_CD", operator : "lIKE", value : "0", logical : "||" }
]);
};
 */
com.data.getMatchedJSON = function(dataListObj, condArr) {
    if (typeof dataListObj === "string") {
        dataListObj = $p.getComponentById(dataListObj);
    }

    var returnData = [];
    var allData = dataListObj.getAllJSON();

    if (com.util.isArray(condArr) === false) {
        condArr = [ condArr ];
    }

    for (var idx = 0; idx < allData.length; idx++) {
        var result = true;

        for (var conIdx = 0; conIdx < condArr.length; conIdx++) {
            var colValue = allData[idx][condArr[conIdx].columnId.trim()];
            var value = condArr[conIdx].value;
            var operator = condArr[conIdx].operator.trim();
            var logical = (condArr[conIdx].logical || "&&").trim();

            if (operator === "==") {
                if (colValue == value) {
                    if (logical === "||") {
                        result = true;
                        break;
                    }
                } else {
                    if (logical === "&&"){
                        result = false;
                    }
                }
            } else if (operator === "!=") {
                if (colValue != value) {
                    if (logical === "||") {
                        result = true;
                        break;
                    }
                } else {
                    if (logical === "&&") {
                        result = false;
                    }
                }
            } else if (operator === ">") {
                if (colValue > value) {
                    if (logical === "||") {
                        result = true;
                        break;
                    }
                } else {
                    if (logical === "&&") {
                        result = false;
                    }
                }
            } else if (operator === "<") {
                if (colValue < value) {
                    if (logical === "||") {
                        result = true;
                        break;
                    }
                } else {
                    if (logical === "&&") {
                        result = false;
                    }
                }
            } else if (operator === ">=") {
                if (colValue >= value) {
                    if (logical === "||") {
                        result = true;
                        break;
                    }
                } else {
                    if (logical === "&&") {
                        result = false;
                    }
                }
            } else if (operator === "<=") {
                if (colValue <= value) {
                    if (logical === "||") {
                        result = true;
                        break;
                    }
                } else {
                    if (logical === "&&") {
                        result = false;
                    }
                }
            } else if (operator === "LIKE") {
                if (colValue.indexOf(value) > -1) {
                    if (logical === "||") {
                        result = true;
                        break;
                    }
                } else {
                    if (logical === "&&") {
                        result = false;
                    }
                }
            } else {
                result = false;
            }
        }

        if (result === true) {
            returnData.push(allData[idx]);
        }
    }

    return returnData;
};


com.str = {
        replaceAll : function( str, orgStr, repStr ){
            try {
                str = ""+str;
                return str.split(orgStr).join(repStr);
            } catch (ex) {
                console.error(ex);
                return str;
            }
        },
        trim : function(str) {
            try {
                if (typeof str == "undefined" || str == null) {
                    str ="";
                }
                if (typeof str !== "string") {
                    str = str + "";
                }
                return str.trim();
            } catch (ex) {
                console.error(ex);
            }
        },
        isFinalConsonant : function (str) {
            var code = str.charCodeAt(str.length - 1);
            if ((code < 44032) || (code > 55197)) {
                return false;
            }
            if ((code - 16) % 28 == 0) {
                return false;
            }
            return true;
        },
        attachPostposition : function (str) {
            if (com.str.isFinalConsonant(str)) {
                str = str + "은";
            } else {
                str = str + "는";
            }

            return str;
        },
};

com.storage = {
        /*
         * 웹브라우저의 localStorage 관련 모듈
         * section: 화면구분, key: 내부변수
         * ex)
         *  com.storage.get("SPM001M01", "topYn");
         *  com.storage.set("SPM001M01", "topYn", "Y");
         *  com.storage.reomve("SPM001M01", "topYn");
         *  com.storage.removeSection("SPM001M01");
         */
        _getRealKey : function(section, key) {
            return section + "_" + key;
        },
        /*
         * localStorage 자동 설정
         * 화면 pageload 시 호출하면 해당 key와 같은 id를 갖은 컴포넌트의 값을 자동 세팅
         * ex)
         * scwin.onpageload = function() {
         *  com.storage.initAutoLoad("SAM003M01");
         * };
         */
        initAutoLoad : function(section) {
            if( !com.util.isEmpty(section) ) {

                var obj = com.storage.getSection(section);
                obj.forEach( function(value, key) {
                    var comp = $p.getComponentById(key);
                    if( !com.util.isEmpty(comp) ) {
                        try{
                            comp.setValue(value);
                        } catch(e) {
                            // setValue가 없는 컴포넌트를 위해..
                            console.log(e);
                        }
                    }
                });
            }
        },
        /*
         * localStorage 저장
         */
        set : function(section, key, value) {
            var realKey = com.storage._getRealKey(section, key);
            WebSquare.localStorage.setItem(realKey, value);
        },
        /*
         * localStorage 조회
         */
        get : function(section, key) {
            var realKey = com.storage._getRealKey(section, key);
            return WebSquare.localStorage.getItem(realKey);
        },
        /*
         * localStorage 조회(By Section)
         */
        getSection : function(section) {
            var len = WebSquare.localStorage.length;
            var obj = new Map();

            for(var i=0; i<len; i++) {
                var keyString = WebSquare.localStorage.key(i);
                if (keyString.startsWith(section)) {
//                    console.log("==>", keyString.substring(section.length+1));
                    obj.set(keyString.substring(section.length+1), WebSquare.localStorage.getItem(keyString));
                }
            }
            return obj;
        },
        /*
         * localStorage 전체조회
         */
        getAll : function() {
            return WebSquare.localStorage.getAllItem();
        },
        /*
         * localStorage 삭제
         */
        remove : function(section, key) {
            var realKey = com.storage._getRealKey(section, key);
            WebSquare.localStorage.removeItem(realKey);
        },
        /*
         * localStorage 삭제(By Section)
         */
        removeSection : function(section) {
            var len = WebSquare.localStorage.length;
            for(var i=len; i>0; i--) {
                var keyString = WebSquare.localStorage.key(i-1);
                if (keyString.startsWith(section)) {
                    WebSquare.localStorage.removeItem(keyString);
                }
            }
        }

};

