// return 예시) true

com.str.isFinalConsonant("입니다")
// return 예시) false

com.str.isFinalConsonant("입니당")
// return 예시) true
 */
com.str.isFinalConsonant = function (str) {
    var code = str.charCodeAt(str.length - 1);
    if ((code < 44032) || (code > 55197)) {
        return false;
    }
    if ((code - 16) % 28 == 0) {
        return false;
    }
    return true;
};


