/**
 * caption 태그의 값(innerHTML)을 captionStr 으로 변경한다.
 *
 * @memberOf com.util
 * @date 2024.09.04
 * @author Inswave Systems
 * @param {String} compId group(tagname="table") 내부의 caption id 값이나 gridView 의 id
 * @param {String} captionStr 변경할 캡션 값
 * @returns
 * @example
 * com.util.setCaption(captionId, "캡션 변경했어요.");
 */
com.util.setCaption = function(compId, captionStr) {
	if(typeof compId === "string") {
		compId = com.util.getComponent(compId);
		if(compId === undefined) {
			return;
		}
	}

	if(typeof compId === 'object' && compId.render) {
		if(compId.getPluginName && compId.getPluginName() === 'gridView') {
			if(compId.render.getElementsByTagName('caption').length === 1) {
				compId.render.getElementsByTagName('caption')[0].innerHTML = captionStr;
			}
		} else if(compId.render.tagName.toLowerCase() === 'caption') {
			compId.render.innerHTML = captionStr;
		}
	}
};


/**
 * table 태그의 summary 값(innerHTML)을 summaryVal 으로 변경한다.
 *
 * @memberOf com.util
 * @date 2024.09.04
 * @author Inswave Systems
 * @param {String} compId group(tagname="table") 내부의 caption id 값이나 gridView 의 id
 * @param {String} summaryVal 변경할 요약 값
 * @returns
 * com.util.setSummary(grpTableId, "요약 변경했어요.");
 */
com.util.setSummary = function(compId, summaryVal) {
	if(typeof compId === "string") {
		compId = com.util.getComponent(compId);
		if(compId === undefined) {
			return;
		}
	}
	if(typeof compId === 'object' && compId.render){
		if(compId.getPluginName && compId.getPluginName() === 'gridView') {
			if(compId.render.getElementsByTagName('table').length > 0) {
				compId.render.getElementsByTagName('table')[0].setAttribute("summary", summaryVal);
			}
		} else if(compId.render.tagName.toLowerCase() === 'table') {
			compId.render.setAttribute("summary", summaryVal);
		}
	}
};


