com.win.setDisabled = function (componentId, disabled) {//debugger;
	  var disabledDiv = $p.getComponentById(componentId + "_disabled_div");
	  if (CKEDITOR.version.charAt(0) < "4") {
	        editor = $p.getComponentById("cke_contents_" + componentId + "_");
	  } else {
	        editor = $p.getComponentById(CKEDITOR.instances[componentId + "_"].id + "_contents");
	  }

	  var iframe = editor.getElementsByTagName("iframe")[0];
	  var editorFrame = iframe ? iframe.contentWindow : "";

	  if (disabled == true && disabledDiv) {
		  	disabledDiv.style.visibility = "visible";
	  		disabledDiv.style.display = "block";
	        disabledDiv.hidden = false;

	      if (editorFrame) {
	        editorFrame.document.documentElement.contentEditable = false;//플래그 오류 수정
	        editorFrame.document.body.contentEditable = false;//플리그 오류 수정
	      }
	      $p.getComponentById(componentId).setDisabled(true);
	  } else if(disabled == true && disabledDiv == null) {
		  $p.getComponentById(componentId).setDisabled(true);
	  } else {
		  $p.getComponentById(componentId).setDisabled(false);
	  }
};

