/**
 * InputCalendar setDisabled 사용시 캘린더 오픈 안되는 문제 수정 
 * WESE_958 ( 인스웨이브 등록번호 )
 * 5.0_4.5245B.20240927.114732_1.5 버전에서 생긴 문제로 이후 버전업 되어을 때 체크 후 삭제 필요
 */
WebSquare.uiplugin.inputCalendar.prototype.setDisabled = function(disabled) {
    try {
        disabled = WebSquare.util.getBoolean(disabled);
        if (disabled) {
            if (this.options.placeholder || this.options.original_placeholder) {
                var original_placeholder = this.options.placeholder || this.options.original_placeholder;
                this.setPlaceholder("");
                this.options.original_placeholder = original_placeholder;
            }
        }
        if (WebSquare.dataPrefix !== true) {
            WebSquare.xfControl.prototype.setDisabled.call(this, disabled);
        }
        var button = (this.options.useAnchor) ? document.getElementById(this.id + "_a") : document.getElementById(this.id + "_img");
        if (disabled) {
            this.options.disabled = disabled;
            this.dom.input.setAttribute('disabled', 'disabled');
            if (WebSquare.dataPrefix !== true) {
            }
            this.addClass(this.dom.input, 'w2input_disabled');
            this.addClass(this.dom.img, 'w2button_disabled');
        } else {
            this.options.disabled = disabled;
            this.dom.input.removeAttribute('disabled');
            if (WebSquare.dataPrefix !== true) {
            }
            this.removeClass(this.dom.input, 'w2input_disabled');
            this.removeClass(this.dom.img, 'w2button_disabled');
            if (this.options.placeholder || this.options.original_placeholder) {
                this.setPlaceholder(this.options.original_placeholder)
            }
        }
    } catch (e) {
        WebSquare.exception.printStackTrace(e);
    }
    return disabled;
};
/**
 * 5.0_4.5245B.20240927.114732_1.5 버전에서 생긴 문제로 이후 버전업 되어을 때 체크 후 삭제 필요
 * role="tablist" 삭제 버전 엔진패치 전까지 유지할 것 2024-10-07
 */
WebSquare.uiplugin.tabControl.prototype.makeAllTabHTML = function() {
    try {
        var t = "";
        switch (this.options.tabPosition) {
        case "top":
            t = "w2tabcontrol_tabhost_top";
            break;
        case "bottom":
            t = "w2tabcontrol_tabhost_bottom";
            break;
        case "left":
            t = "w2tabcontrol_tabhost_left";
            break;
        case "right":
            t = "w2tabcontrol_tabhost_right"
        }
        var e = [];
        e.push("<ul id='" + this.id + "_tabhost' class='" + this.options.hostClass + " " + t + "' >");
        for (var i = 0; i < this.tabArr.length; i++) {
            var s = this.tabArr[i];
            this.tabArr[i].hiddenTab && (s.tabStyle = s.tabStyle + "; display:none; visibility:hidden;");
            var a = "make" + s.tabType.capitalize() + "TabHTML";
            e.push(this[a](s, i + 1))
        }
        return e.push("</ul>"),
        e.join("")
    } catch (t) {
    	WebSquare.exception.printStackTrace(t, null, this)
    }
}
/**
 * 5.0_4.5245B.20240927.114732_1.5 버전에서 생긴 문제로 이후 버전업 되어을 때 체크 후 삭제 필요
 * content div 영역 태그내의 tabindex='0' 삭제 (WESD-1755)
 */
WebSquare.uiplugin.tabControl.prototype.defaultOptions.removeContentsTabIndex = false;
WebSquare.uiplugin.tabControl.prototype.makeContentsHTML = function(contents, label, reuseFrame, tabIndex, labelledbyId) {
    try {
        var htmlContents = ["<div id='", null, "' class='", null, "' role='tabpanel", null, null, null, "</div>"];
        var comp = this.getChild(contents.contentsID + "_body");
        var styleStr = "";
        var contentStyleStr = contents.style ? contents.style : "";
        if (this.contentsArr[this.options.selectedIndex] !== contents) {
            styleStr = "' aria-hidden='true' style='display:none;" + contents.style + "'>";
        } else {
            styleStr = "' aria-hidden='false' style='" + contents.style + "'>";
        }
        var bridgeHtmlStr = "";
        var backbridgeHtmlStr = "";
        var tabIndexStr = "";
        if (this.options.useBridge) {
            var contentsTitle = contents.title || label;
            if (this.options.useH3Bridge) {
                bridgeHtmlStr = "<h3 id='" + contents.contentsID + "_bridge' style='' class='w2tabcontrol_contents_bridge_h3'>" + contentsTitle + "</h3>";
                if (tabIndex >= 0) {
                    this.bridgeIdArr.splice(tabIndex, 0, contents.contentsID + "_bridge");
                } else {
                    this.bridgeIdArr.push(contents.contentsID + "_bridge");
                }
            } else {
                var bridgeHelper;
                if (this.options.removeBridge === true) {
                    bridgeHelper = this.options.useBridgeHelper ? "<h3 id='" + contents.contentsID + "_bridge_helper' style='position:absolute;text-indent : -10000px;height:0px;' class='w2tabcontrol_contents_bridge_helper'>" + contentsTitle + "</h3>" : "";
                    tabIndexStr = "' tabIndex='0";
                    bridgeHtmlStr = bridgeHelper;
                } else {
                    if (typeof contentsTitle === "string") {
                        contentsTitle = contentsTitle.wq_replaceAll("<br/>", " ").wq_replaceAll("<br>", " ");
                    }
                    bridgeHelper = this.options.useBridgeHelper ? "<h3 id='" + contents.contentsID + "_bridge_helper' style='position:absolute;text-indent : -10000px;background:none;height:0px;' class='w2tabcontrol_contents_bridge_helper'>" + contentsTitle + "</h3>" : "";
                    bridgeHtmlStr = "<a id='" + contents.contentsID + "_bridge' class='w2tabcontrol_bridge' href='javascript:void(null);'>" + bridgeHelper + "</a>";
                }
                if (tabIndex >= 0) {
                    this.bridgeIdArr.splice(tabIndex, 0, contents.contentsID + "_bridge");
                } else {
                    this.bridgeIdArr.push(contents.contentsID + "_bridge");
                }
            }
        }
        if (this.options.useBackbridge) {
            backbridgeHtmlStr = "<a id='" + contents.contentsID + "_backbridge' tabindex='0' title='go back' class='w2tabcontrol_bridge'></a>";
            if (tabIndex >= 0) {
                this.backbridgeIdArr.splice(tabIndex, 0, contents.contentsID + "_backbridge");
            } else {
                this.backbridgeIdArr.push(contents.contentsID + "_backbridge");
            }
        }
        if (this.options.removeContentsTabIndex == true) {
            tabIndexStr = "";
        }
        htmlContents[1] = contents.contentsID;
        htmlContents[3] = contents.contentsClass;
        htmlContents[5] = WebSquare.util.getBoolean(this.options.removeAriaLabelledby) ? "" : "' aria-labelledby='" + labelledbyId;
        htmlContents[5] += tabIndexStr;
        htmlContents[6] = styleStr;
        htmlContents[7] = bridgeHtmlStr;
        htmlContents[7] += (contents.alwaysDraw && !reuseFrame) ? comp.toHTML() : "";
        htmlContents[7] += backbridgeHtmlStr;
        return htmlContents.join("");
    } catch (e) {
        WebSquare.exception.printStackTrace(e, null, this);
    }
};
/**
 * 5.0_4.5245B.20240927.114732_1.5 버전에서 생긴 문제로 이후 버전업 되어을 때 체크 후 삭제 필요
 * 그리드 셀타입 custom일때 ( WESD-1756 처리완료)
 * 팝업을 띄우면 팝업으로 포커스가 가지 않음
 * 팝업을 닫으면 원래 호출 셀로 돌아오지 않음
 */
WebSquare.uiplugin.gridView.prototype.defaultOptions.readOnlyButtonFocusAllow = false;
WebSquare.uiplugin.gridView.prototype.bodyClick = function(e, srcElem, options) {
    try {
        var oldFocusedTd = this.getLastFocusedCell().focusedTd;

        if (this.options.rowMouseOver) {
            this.removeRowOverStyle(this.lastOverSrc, "grid_body_row_over", "grid_body_row");
        }

        var dataTdIndex = WebSquare.util.getDataPrefix("tdIndex");
        var dataCol_id = WebSquare.util.getDataPrefix("col_id");
        var dataColIndex = WebSquare.util.getDataPrefix("colIndex");

        var originalRowIndex = this.rowIndex;
        var tdIndex = parseInt(srcElem.getAttribute(dataTdIndex));
        var trIndex = parseInt(tdIndex / this.realRowDataLength);
        var displayRowIndex = trIndex + this.rowIndex;
        var colIndex = srcElem.getAttribute(dataCol_id);
        var oldRowIndex = this._dataList.getRowPosition();
        var oldColIndex = this.getColumnIndex(this._dataList.getColumnPosition());
        var newRowIndex = trIndex + originalRowIndex;
        var newColIndex = tdIndex % this.realRowDataLength - (this.realRowDataLength - this.oneRowDataLength);


        var cellInfo;
        if (colIndex) {
            cellInfo = this.getCellInfo(colIndex);
        }

        var realRowIndex = this.dataList.getRealRowIndex(displayRowIndex);
        if (typeof realRowIndex != "number") {
            if (realRowIndex && realRowIndex.type == "header") {
                this.toggleGroup(realRowIndex.groupId);
            }
            return;
        }
        if (this.options.focusDefaultColumn) {
            var attrID = srcElem.getAttribute("id") || "";
            var isRowNum = attrID.slice(0, "_headerRowNumber".length) === "_headerRowNumber";
            var isRowStatus = attrID.slice(0, "_headerRowStatus".length) === "_headerRowStatus";
            if (isRowNum || isRowStatus) {
                this.__setFocusedCell(e, srcElem, {
                    editMode: false
                });

                if(isRowStatus) {
                    WebSquare.event.fireEvent(this, "onrowstatusclick", newRowIndex );
                } else {
                    WebSquare.event.fireEvent(this, "onrownumclick", newRowIndex );
                }
                return;
            }
        }

        if (colIndex == null) {
            return;
        }

        this.moveDirection = null;
        var colDiff = oldColIndex - newColIndex;
        var rowDiff = oldRowIndex - newRowIndex;
        if (colDiff == 0 && rowDiff == 0) {
            this.moveDirection = "none";
        } else if ((colDiff > 0 || colDiff < 0) && (rowDiff > 0 || rowDiff < 0)) {
            this.moveDirection = "both";
        } else if (colDiff > 0 || colDiff < 0) {
            this.moveDirection = "column";
        } else if (rowDiff > 0 || rowDiff < 0) {
            this.moveDirection = "row";
        }

        var dataEditModeEvent = WebSquare.util.getDataPrefix("editModeEvent");
        var editModeEvent = srcElem.getAttribute(dataEditModeEvent) || "";
        var useSecondClick = false;
        if ((editModeEvent != "" && editModeEvent.toLowerCase() == "onsecondclick") || (editModeEvent == "" && this.options.editModeEvent.toLowerCase() == "onsecondclick")) {
            for (var i = 0; i < this.focusedCell.length; i++) {
                if (this.focusedCell[i].focusedRowIndex == newRowIndex && this.focusedCell[i].focusedColIndex == newColIndex) {
                    useSecondClick = true;
                }
            }
        }

        cellInfo = this.getCellInfo(srcElem);
        var customInputType = "";
        var cellInfo2;
        if (cellInfo.options.inputType === "custom") {
            cellInfo2 = cellInfo.cellManagerHashByRowIndex[this.getRealRowIndex(newRowIndex)] ? cellInfo.cellManagerHashByRowIndex[this.getRealRowIndex(newRowIndex)] : cellInfo;
            customInputType = cellInfo2.options.inputType;
        }
        var focusValid = true;
        var target = WebSquare.event.getTarget(e);
        if (!cellInfo.options.blockSelect &&
            //(cellInfo.options.inputType !== "button" || (cellInfo.options.inputType === "button" && target && target.tagName === "TD"))) {
            ((cellInfo.options.inputType !== "button" && customInputType !== "button") || ((cellInfo.options.inputType === "button" || customInputType === "button") && target && target.tagName === "TD"))) {

            var focusedCell = true;
            if (this.options.preventDuplicateFocusedCell && this.options.focusFlow === "linear") {
                if (cellInfo.options.inputType !== "link") {
                    focusedCell = false;
                }
            }
            if (this.options.preventMultipleClick) {
                if (cellInfo.options.inputType === "checkbox" && target && target.tagName === "LABEL") {
                    focusedCell = false;
                }
            }
            var tempFocusValid;
            if (focusedCell) {
                if (this.options.drilldownToggle === "enter" && this.isMobile && this.isHammerEnabled()) {
                    if (this.focusedCell.length == 1) {
                        var cellInfo = this.getCellInfo(this.focusedCell[0].focusedColIndex);
                        if (cellInfo && cellInfo.options.inputType == "drilldown") {
                            var tdIndex = parseInt(srcElem.getAttribute(dataTdIndex));
                            var trIndex = parseInt(tdIndex / this.realRowDataLength);
                            var colIndex = parseInt(srcElem.getAttribute(dataColIndex));

                            var newRowIndex = this._getGroupbyDisplayRowIndex(trIndex + originalRowIndex);
                            var newColIndex = tdIndex % this.realRowDataLength - (this.realRowDataLength - this.oneRowDataLength);

                            var focusedColIndex = this.focusedCell[0].focusedColIndex;
                            var focusedRowIndex = this.focusedCell[0].focusedRowIndex;
                            if (newRowIndex === focusedRowIndex && newColIndex === focusedColIndex) {
                                var realRowIndex = this.dataList.getRealRowIndex(focusedRowIndex);
                                this.toggle(realRowIndex);
                            }
                        }
                    }
                }
                var tempOptions = {
                    editMode: cellInfo.options.focusMode == "none",
                    dont_fixScroll: this.options.CellClickFixScrollX
                };
                WebSquare.extend(tempOptions, options);
                tempFocusValid = this.__setFocusedCell(e, srcElem, tempOptions);
            }

            if (tempFocusValid === "multiCell") {
               focusValid = false;
            }
            if (cellInfo.options.embeddedInput) {
                this.focusedByApi = false;
            }
        }

        if (e.altKey) {
            if (this.options.contextMenuAltClick === true) {
                this.clickRightButtonCell(e);
                return;
            }
        }

        var startPoint;
        var doClick = true;
        if (WebSquare.util.isIE()) {
            startPoint = e.srcElement;
        } else {
            startPoint = e.target;
        }
        switch (cellInfo.options.inputType) {
            case "radio":
            case "checkbox":
                if (startPoint.tagName != "INPUT") {
                    if (this.options.checkOnCellClick && startPoint.tagName != "LABEL") {
                        var targetCheckbox = srcElem.getElementsByTagName("input")[0];
                        if (targetCheckbox) {
                            targetCheckbox.checked = !targetCheckbox.checked;
                        }
                    } else {
                        doClick = false;
                    }
                }
                break;
            case "drilldown":
                if (this.options.ignoreToggleOnDisabled && this._getEditDisabled(displayRowIndex, colIndex)) {
                    doClick = false;
                }
        }

        var fireCellClick = false;
        var clickFlag;
        var useHammer = this.isHammerEnabled();
        if (doClick) {
            clickFlag = this.setCellClickEdit(srcElem);
            if (!clickFlag) {
                var editModeEvent = srcElem.getAttribute(dataEditModeEvent) || cellInfo.options.editModeEvent || "";
                var isFocusUnchanged = (oldFocusedTd != undefined && oldFocusedTd === srcElem);
                var isEditOnClick = (editModeEvent != "" && editModeEvent.toLowerCase() == "onclick") || (editModeEvent == "" && this.options.editModeEvent.toLowerCase() == "onclick") || useSecondClick;
                if ((!useHammer || isFocusUnchanged) && isEditOnClick) {
                    if (!this._getEditDisabled(displayRowIndex, colIndex)) {
                        var tdIndex = parseInt(srcElem.getAttribute(dataTdIndex));
                        var trIndex = parseInt(tdIndex / this.realRowDataLength);
                        var colIndex = parseInt(srcElem.getAttribute(dataColIndex));
                        var colID = srcElem.getAttribute(dataCol_id);

                        var newRowIndex = this._getGroupbyDisplayRowIndex(trIndex + originalRowIndex);
                        var newColIndex = tdIndex % this.realRowDataLength - (this.realRowDataLength - this.oneRowDataLength);
                        this.hideTooltip();
                        var cellInfo = this.getCellInfo(newColIndex);
                        var flag1 = cellInfo.options.inputType === "button" || (!cellInfo.options.embeddedInput && (cellInfo.options.inputType === "checkbox" || cellInfo.options.inputType === "radio") && this.options.preventMultipleClick);
                        if (!flag1) {
                            var isBtn = false;
                            if (cellInfo.internal == false && cellInfo.options.inputType == "custom") {
                                var flag2 = cellInfo2.options.inputType === "button" || (!cellInfo2.options.embeddedInput && (cellInfo2.options.inputType === "checkbox"  || cellInfo2.options.inputType === "radio") && this.options.preventMultipleClick);
                                if (flag2) {
                                    isBtn = true;
                                }
                            }
                            if (!isBtn) {
                                if (cellInfo.options.inputType == "drilldown" && this.options.ignoreCellClick) {
                                    if (!clickFlag) {
                                        WebSquare.event.fireEvent(this, "oncellclick", newRowIndex, newColIndex, colID);
                                    }
                                } else {
                                    WebSquare.event.fireEvent(this, "oncellclick", newRowIndex, newColIndex, colID);
                                }
                            }
                        }
                        fireCellClick = true;
                    }
                    if (focusValid) {
                        this.setEditMode(srcElem);
                    }
                }
            }
        }

        if (!fireCellClick && !this._getEditDisabled(displayRowIndex, colIndex)) {
            var tdIndex = parseInt(srcElem.getAttribute(dataTdIndex));
            var trIndex = parseInt(tdIndex / this.realRowDataLength);
            var colIndex = parseInt(srcElem.getAttribute(dataColIndex));
            var colID = srcElem.getAttribute(dataCol_id);

            var newRowIndex = trIndex + originalRowIndex;
            var newColIndex = tdIndex % this.realRowDataLength - (this.realRowDataLength - this.oneRowDataLength);

            if (useHammer || (this.options.tooltipDisplay && this.isMobile)) {
                this.bodyOver(e, srcElem);
            } else {
                this.hideTooltip();
            }

            var cellInfo = this.getCellInfo(newColIndex);
            var flag1 = cellInfo.options.inputType === "button" 
                || (!cellInfo.options.embeddedInput && (cellInfo.options.inputType === "checkbox" || (cellInfo.options.inputType === "radio" && this.options.preventDuplicateFocusedCell)) 
                    && this.options.preventMultipleClick && !(this.options.checkOnCellClick && startPoint.tagName != "LABEL"));
            if (!flag1) {
                if (cellInfo.internal == false && cellInfo.options.inputType == "custom") {
                    var flag2 = cellInfo2.options.inputType === "button" || (!cellInfo2.options.embeddedInput && cellInfo2.options.inputType === "checkbox" && this.options.preventMultipleClick);
                    if (flag2) {
                        return;
                    }
                }
                newRowIndex = this._getGroupbyDisplayRowIndex(newRowIndex);
                if (cellInfo.options.inputType == "drilldown" && this.options.ignoreCellClick) {
                    if (!clickFlag) {
                        WebSquare.event.fireEvent(this, "oncellclick", newRowIndex, newColIndex, colID);
                    }
                } else {
                    if (((cellInfo.options.inputType === "radio" || cellInfo.options.inputType === "checkbox") && (startPoint.tagName === "LABEL" || startPoint.tagName === "TD"))
                        || (cellInfo.options.inputType === "link" && this.options.contentCellClick && startPoint.tagName !== "A")
                        || (cellInfo.options.inputType === "image" && this.options.contentCellClick && startPoint.tagName !== "IMG")) {
                    } else {
                        WebSquare.event.fireEvent(this, "oncellclick", newRowIndex, newColIndex, colID);
                    }
                }
            }
        }

    } catch (e) {
        WebSquare.exception.printStackTrace(e, null, this);
    }
};
/**
 * 5.0_4.5245B.20240927.114732_1.5 버전에서 생긴 문제로 이후 버전업 되어을 때 체크 후 삭제 필요
 * 그리드 셀타입 custom일때 ( WESD-1756 처리완료)
 * 팝업을 띄우면 팝업으로 포커스가 가지 않음
 * 팝업을 닫으면 원래 호출 셀로 돌아오지 않음
 */
WebSquare.uiplugin.cellInfo.button.prototype.setInnerHTML = function(td, data, rowIndex) {
    try {
        var dataCol_id = WebSquare.util.getDataPrefix("col_id");
        var disabled = this.mainGrid._getEditDisabled(rowIndex, td.getAttribute(dataCol_id));

        var disabledStr = "";
        if (disabled) {
        }

        var colIndex = this.mainGrid.getColumnIndex(td.getAttribute(dataCol_id));
        var tabIndexStr = " tabIndex='-1'";

        if (this.mainGrid.options.focusMode == "none") {
            tabIndexStr = " tabIndex='0'";
        } else if (this.mainGrid.options.keyMoveEditMode == true) {
            if (this.mainGrid.getColumnVisible(colIndex) == false) {//hidden컬럼의 경우 tab키 이동시 button에 포커스 가지않게처리함
                tabIndexStr = " tabIndex='-1'";
            } else {
                tabIndexStr = "";
            }
        }
        var titleStr;
        if (this.mainGrid.options.titleFormatter) {
            try {
                if (typeof this.mainGrid.options.titleFormatter != "function") {
                    var titleFormatter = WebSquare.util.getGlobalFunction(this.mainGrid.options.titleFormatter, this.scope_id);
                    if (titleFormatter != null) {
                        this.mainGrid.options.titleFormatter = titleFormatter;
                        titleStr = titleFormatter.call(this, rowIndex, colIndex, data);
                    }
                } else {
                    titleStr = this.mainGrid.options.titleFormatter.call(this, rowIndex, colIndex, data);
                }
            } catch (e) {
                WebSquare.exception.printStackTrace(e, null , this);
            }
        }
        var title = titleStr || this.options.title || "";
        if (!title) {
            if (this.mainGrid.options.titleAuto) {
                var headerTitle = this.mainGrid.getHeaderValue(this.mainGrid.bodyToHeaderRelation[this.colID]) || "";
                title = " title='" + headerTitle +  "'";
            }
        } else {
            title = " title='" + title + "'";
        }
        var isEscape = (this.options.escape !== "") ? this.options.escape : this.mainGrid.options.escape;
        isEscape = WebSquare.util.getBoolean(isEscape);
        if (isEscape) {
            data = WebSquare.xml._encode(data + "");
        }
        var buttonId = "id='" + this.mainGrid.id + '_button_' + rowIndex + '_' + colIndex + "'";
        td.innerHTML = "<button type='button' " + buttonId + " style='width:100%;height:100%' " + disabledStr + tabIndexStr + title + ">" + this.getDisplayData(data) + "</button>";
        if (this.internal == true) {
            var node = td.childNodes[0];
            if (node.clientHeight == 0) {
                var height = td.clientHeight - 2;
                WebSquare.style.setSize(node, "height", height);
            }
        }
        var listener = function(context, attr, func) {
            return function(e) {
                func.apply(context, [e || window.event].concat(attr));
            };
        };
        this._listener = listener(this, [rowIndex, colIndex, td], function(e, rowIndex, colIndex, tdElem) {
            if (this.mainGrid.editedCell != null) {
                this.mainGrid.editedCell.handleEndEdit();
            }
            var focusPossible  = (this.mainGrid.options.readOnlyButtonFocusAllow === true) ? !this.mainGrid._getEditDisabled(rowIndex, colIndex) : !this.mainGrid._getEditDisabled(rowIndex, colIndex) && !this.mainGrid.___getEditReadOnly(rowIndex, colIndex);
            //if (!this.mainGrid._getEditDisabled(rowIndex, colIndex) && !this.mainGrid.___getEditReadOnly(rowIndex, colIndex)) {
            if (focusPossible) {
                if (!this.options.blockSelect) {
                    this.mainGrid.__setFocusedCell(e, tdElem, {
                        editMode: this.options.focusMode == "none"
                    });
                }
            }
            if (!this.mainGrid._getEditDisabled(rowIndex, colIndex)) {
                WebSquare.event.fireEvent(this.mainGrid, "oncellclick", this.mainGrid._getGroupbyDisplayRowIndex(rowIndex), colIndex, this.options.id);
            }
        });
        WebSquare.event.addListener(td.getElementsByTagName("button")[0], "onclick", this._listener);
    } catch (e) {
        WebSquare.exception.printStackTrace(e, null, this);
    }
};
/**
 * 5.0_4.5245B.20240927.114732_1.5 버전 수정 인스웨이브에서 accessibility=true일때만 동작하도록 했으나 accessibility를 꺼도 동작하도록 수정함.
 * WESD-1760 gridView accessibility=true설정시 link 타입 셀 빈데이터 존재시 a태그 생성되지 않도록 수정
 */
WebSquare.uiplugin.cellInfo.link.prototype.setInnerHTML = function(td, data, rowIndex, colIndex, options) {
    var tabIndexStr = " tabIndex='-1' ";

    if (this.mainGrid.options.focusMode == "none") {
        tabIndexStr = " tabIndex='0' ";
    } else if (this.mainGrid.options.keyMoveEditMode == true) {
        tabIndexStr = "";
    }
    var isEscape = (this.options.escape !== "") ? this.options.escape : this.mainGrid.options.escape;
    isEscape = WebSquare.util.getBoolean(isEscape);
    if (isEscape) {
        data = WebSquare.xml._encode(data + "");
    }
    var customFormatter = WebSquare.util.getGlobalFunction(this.options.customFormatter, this.scope_id);
    var formattedData = this.getDisplayData(data);
    var resultData;
    if (typeof customFormatter == "function") {
        this.useCustomFormatter = true;
        resultData = customFormatter.call(this.mainGrid, data, formattedData, rowIndex, colIndex);
    } else {
        this.useCustomFormatter = false;
        resultData = formattedData;
    }

    var titleStr;
    if (this.mainGrid.options.titleFormatter) {
        try {
            if (typeof this.mainGrid.options.titleFormatter != "function") {
                var titleFormatter = WebSquare.util.getGlobalFunction(this.mainGrid.options.titleFormatter, this.scope_id);
                if (titleFormatter != null) {
                    this.mainGrid.options.titleFormatter = titleFormatter;
                    titleStr = titleFormatter.call(this, rowIndex, colIndex, data);
                }
            } else {
                titleStr = this.mainGrid.options.titleFormatter.call(this, rowIndex, colIndex, data);
            }
        } catch (e) {
            WebSquare.exception.printStackTrace(e, null , this);
        }
    }

    var title = "";
    if (titleStr) {
        title = " title='" + titleStr + "'";
    } else if (this.options.title) {
        title = " title='" + this.options.title + "'";
    }
    if (!title) {
        if(this.mainGrid.options.titleAuto) {
            var headerTitle = this.mainGrid.getHeaderValue(this.mainGrid.bodyToHeaderRelation[this.id]) || "";
            title = " title='" + headerTitle +  "'";
        }
    }
    var voidNull = this.options.voidNull ? "javascript:void(null);" : "";
    var anchorId = "";
    if (this.mainGrid.options.accessibility == true) {
        anchorId = "id='" + this.mainGrid.id+'_link_'+rowIndex+'_'+colIndex + "'";
    }
    if (this.mainGrid.options.accessibility == true && !resultData) {//accessbility설정시 빈 데이타는 a 태그 생성X
        td.innerHTML = this.mainGrid.dataTagOpen + this.mainGrid.dataTagClose;
    //} else if (resultData || title) { 2024.10.23 accessibility 상관없이 적용되도록 수정
    } else if (resultData) {
        td.innerHTML = this.mainGrid.dataTagOpen + "<a " + anchorId + " href='" + voidNull + "' onclick='event.returnValue=false; return false;'" + tabIndexStr + " " + title + ">" + resultData + "</a>" + this.mainGrid.dataTagClose;
    } else {
        td.innerHTML = this.mainGrid.dataTagOpen + this.mainGrid.dataTagClose;
    }
};
