 * 아코디언 onclick 이벤트에서 팝업 호출 시 팝업 창 위치 문제 ( WESD-1761 핫픽스 처리완료)
 */
WebSquare.uiplugin.accordion.prototype.openPanel = function(id) {
    try {
        var panel = this.getPanelById(this.id + "_panel_" + id);
        var content = panel.panelContent;
        var title = panel.panelTitle;

        if (!this.options.collapsible) {
            for (var i = 0; i < this.childControlList.length; i++) {
                if (this.panelArr[i].options.id != (this.id + "_panel_" + id) && this.childControlList[i].options.isOpen == true) {
                    if (this.options.independentPanel !== true) {
                        this._closePanel(this.childControlList[i].options.id);
                        this.childControlList[i].options.isOpen = false;
                    }
                }
            }
        }

        if (!panel.options.isOpen && panel.options.disabledPanels !== true) {
            if (WebSquare.util.isIE(6)) {
                content.render.style.display = "block";
                content.addClass("w2panels_content_open");
                panel.addClass(panel.dom.Img, "w2panels_title_image_open");
                panel.options.isOpen = true;
                title.render.parentNode.setAttribute("aria-expanded", "true");
            } else {
                $("#" + content.render.id).slideDown(this.options.panelMoveSpeed, function() {
                    content.addClass("w2panels_content_open");
                    panel.addClass(panel.dom.Img, "w2panels_title_image_open");
                    panel.options.isOpen = true;
                    title.render.parentNode.setAttribute("aria-expanded", "true");
                    WebSquare.event.fireEvent(panel.parentControl, "onpanelload",panel.id, panel.options.userID);
                });
            }
        }
    } catch (e) {
        WebSquare.exception.printStackTrace(e, null, this);
    }
};
