/**
 * 5.0_4.5245B.20240927.114732_1.5 버전에서 생긴 문제로 이후 버전업 되어을 때 체크 후 삭제 필요
 * 아코디언 onclick 이벤트에서 팝업 호출 시 팝업 창 위치 문제 ( WESD-1761 핫픽스 처리완료)
 */
WebSquare.uiplugin.accordion.prototype._closePanel = function(id) {
    try {
        var panel = this.getPanelById(id);
        if (panel) {
            var content = panel.panelContent;
            var title = panel.panelTitle;
            if (panel.options.isOpen && panel.options.disabledPanels !== true) {
                if (WebSquare.util.isIE(6)) {
                    content.render.style.display = "none";
                    content.removeClass("w2panels_content_open");
                    panel.removeClass(panel.dom.Img, "w2panels_title_image_open");
                    panel.options.isOpen = false;
                    title.render.parentNode.setAttribute("aria-expanded", "false");
                } else {
                    $("#" + content.render.id).slideUp(this.options.panelMoveSpeed, function() {
                        content.removeClass("w2panels_content_open");
                        panel.removeClass(panel.dom.Img, "w2panels_title_image_open");
                        panel.options.isOpen = false;
                        title.render.parentNode.setAttribute("aria-expanded", "false");
                        WebSquare.event.fireEvent(panel.parentControl, "onpanelunload",panel.id, panel.options.userID);
                    });
                }
            }
        } else {
            WebSquare.logger.printLog("error : cannot find panel with id[" + id + "] at " + "[" + this.id + "]");
        }

    } catch (e) {
        WebSquare.exception.printStackTrace(e, null, this);
    }
};
/**
 * 5.0_4.5245B.20240927.114732_1.5 버전에서 생긴 문제로 이후 버전업 되어을 때 체크 후 삭제 필요
 * aria-sort 오타 수정 WESD-1762
 */
WebSquare.uiplugin.gridView.prototype.setHeaderSortImage = function(headerId, order, sortOrd) {
    var td = this.getElementById(this.id + "_" + headerId);
    if (td == undefined) {
        WebSquare.logger.printLog("headerId : " + headerId + "를 찾을 수 없습니다.[" + this.id + "]");
        return;
    }
    var dataSort = WebSquare.util.getDataPrefix("sort");
    var order = parseInt(order, 10);
    var sortOrd = parseInt(sortOrd, 10);
    if (isNaN(sortOrd) || sortOrd <= 0 || this.headerSortStatusArr.length < 2) {
        sortOrd = "";
    } else {
        sortOrd += "";
    }

    this._clearHeaderSortImage(td, "table");
    this._clearHeaderSortImage(td, "div");

    var isSortableHeader = "";  //header가 sortable
    var showSortableImage = this.options.showSortableImage;
    var dataSortable = WebSquare.util.getDataPrefix("sortable");
    var dataInputType = WebSquare.util.getDataPrefix("inputType");
    if(this.options.showSortableImage) {
        var sortableAttr = td.getAttribute(dataSortable);
        if (sortableAttr) {
            isSortableHeader = WebSquare.util.getBoolean(sortableAttr)
        } else {
            isSortableHeader = this.options.sortable;
        }
        if(isSortableHeader) {
            showSortableImage = true;
        } else {
            showSortableImage = false;
        }
    }

    var inputType = td.getAttribute(dataInputType);
    var useFilterURI = "/WebSquare/" + this.options.pluginName + "/header/column[@inputType='" + inputType + "']/useFilter/@value";
    var useFilter = WebSquare.util.getBoolean(WebSquare.core.getConfiguration(useFilterURI));

    var dataUseFilter = WebSquare.util.getDataPrefix("useFilter");
    var xmlUseFilter = td.getAttribute(dataUseFilter);
    if (xmlUseFilter !== "" && typeof xmlUseFilter == "string") {
        xmlUseFilter = WebSquare.util.getBoolean(xmlUseFilter);
    } else {
        xmlUseFilter = true;
    }
    var useFilterExist = false;
    var hideFilterIcon = false;
    var hideSortIcon = false;
    if (this.getDataLength() === 0 && this.options.hideSortIconOnNoData) {
        hideSortIcon = true;
    }    
    if (this.getDataLength() === 0 && this.options.hideFilterIconOnNoData) {
        hideFilterIcon = true;
    }    

    if (xmlUseFilter && (useFilter || td.getAttribute(dataUseFilter) == "true")) {
        useFilterExist = true;
        var displayStr = (hideFilterIcon) ? "none" : "";
        var tempInputObj = td.getElementsByTagName("input")
        if (tempInputObj && tempInputObj[0]) {
            tempInputObj[0].style.display = displayStr;
        }        
    }
    if (this.options.showSortableImage !== true) {
        var headerObj;

        if (order !== 0) {
            headerObj = WebSquare.util.first(td);
            var nextHeaderObj = null;
            var tempHeaderObj = null;
            var tempHeaderObj2 = null;
            try {
                if (this._useCheckboxLabel(headerId)) {
                    tempHeaderObj = document.createElement("div");
                    nextHeaderObj = WebSquare.util.next(headerObj);
                    tempHeaderObj.appendChild(nextHeaderObj);
                }
            } catch (e) {
                WebSquare.exception.printStackTrace(e, null, this);
            }
            if (headerObj.nodeName.toLowerCase() == "nobr" || (headerObj.nodeName.toLowerCase() == "span" && headerObj.className.indexOf("w2grid_span") > -1)) {
                headerObj = td.innerHTML;
                td.innerHTML = "";
            } else {
                headerObj = td.removeChild(headerObj);
            }
            this.headerObjArr[headerId] = headerObj;
            var ord_css = (order == 1) ? "w2grid_head_sort_asc" : "w2grid_head_sort_desc";
            var tdIndex = 0;
            var table_css = "w2grid_head_sort_table_main";
            var td_css = "w2grid_head_sort_td";
            var tableHTMLStr = "<table " + dataSort + "='sort' class='" + table_css + "'><tr><td></td><td class='" + td_css + " "+ ord_css + "'>" + sortOrd + "</td></tr></table>";
            if (this.options.sortedIconPosition === 'left') {
                tdIndex = 1;
                tableHTMLStr = "<table " + dataSort + "='sort' class='" + table_css + "'><tr><td class='" + td_css + " "+ ord_css + "'>" + sortOrd + "</td><td></td></tr></table>";
            } 
            td.innerHTML = tableHTMLStr;
            var tds = td.getElementsByTagName("td");
            if (typeof headerObj == "string") {
                tds[tdIndex].innerHTML = headerObj;
            } else {
                tds[tdIndex].appendChild(headerObj);
                if (nextHeaderObj && tempHeaderObj) {
                    tds[tdIndex].appendChild(tempHeaderObj.removeChild(nextHeaderObj));
                    tempHeaderObj = null;
                }
            }
        }
    } else {
        var _headerObj = this.headerObj[headerId];
        if (!_headerObj) {
            var tmpHeader = td.getElementsByTagName(this.options.dataTag)[0];
            if (tmpHeader && tmpHeader.tagName == "NOBR" || (tmpHeader.tagName == "SPAN" && tmpHeader.className.indexOf("w2grid_span") > -1)) {
                _headerObj = tmpHeader;
            }
        } else if (_headerObj.render) {
            _headerObj = _headerObj.render;
        }
        var nextHeaderObj = null;
        var checkboxLabelPosition = null;
        try {
            if (this._useCheckboxLabel(headerId)) {
                if (this.headerInfoHash2[headerId].getAttribute("checkboxLabelPosition") === "left") {
                    checkboxLabelPosition = "left";
                    tempHeaderObj = document.createElement("div");
                    nextHeaderObj = WebSquare.util.prev(_headerObj);
                    tempHeaderObj.appendChild(nextHeaderObj);
                } else {
                    tempHeaderObj = document.createElement("div");
                    nextHeaderObj = WebSquare.util.next(_headerObj);
                    tempHeaderObj.appendChild(nextHeaderObj);
                }
            }
        } catch (e) {
            WebSquare.exception.printStackTrace(e, null, this);
        }
        try {
            if (useFilterExist && this.options.showSortableUseFilter) {
                tempHeaderObj2 = this.getElementById(this.id + "_" + headerId + "_filter");
            }
        } catch (e) {
            WebSquare.exception.printStackTrace(e, null, this);
        }
        _headerObj.parentNode.removeChild(_headerObj);

        var ord_css = "";
        var ord_text = "";
        switch (order) {
            case 0:
                if (showSortableImage === false && !isSortableHeader) {
                    ord_css = "w2grid_head_sort_image_none";
                    ord_text = "";
                } else {
                    ord_css = "w2grid_head_sort_none";
                    ord_text = WebSquare.language.getMessage("Grid_sort_asc");
                }
                break;
            case 1:
                ord_css = "w2grid_head_sort_asc";
                ord_text = WebSquare.language.getMessage("Grid_sort_desc");
                break;
            case -1:
                ord_css = "w2grid_head_sort_desc";
                ord_text = WebSquare.language.getMessage("Grid_sort_none");
                break;
            default:
                ord_css = "w2grid_head_sort_none";
                ord_text = WebSquare.language.getMessage("Grid_sort_asc");
                break;
        }

        if (!this.options.sortHeaderDiv) {
            var div_css = "w2grid_head_sort_div_main";
            var sort_div_sub_css = "w2grid_head_sort_div_sub";
            if (this.options.sortedIconPosition === 'left') {
                div_css = "w2grid_head_sort_div_main_left";
            }
            if (this.options.showSortableImage === true) {                
                if (this.options.sortedIconPosition === 'left') {
                    sort_div_sub_css = "w2grid_head_sort_div_sub_sortable_image_left";
                } else {
                    sort_div_sub_css = "w2grid_head_sort_div_sub_sortable_image";
                }
            }
            if (hideSortIcon) {
                ord_css = "";
            }              
            td.innerHTML = "<div " + dataSort + "='sort' class = '" + div_css + " " + ord_css + "'>"
                + "<div class = '" + sort_div_sub_css + "'>"
                + sortOrd
                + "</div>"
                + "</div>";
            var tds = td.getElementsByTagName("div");
            tds[0].appendChild(_headerObj);
            if (nextHeaderObj && tempHeaderObj) {
                if (checkboxLabelPosition === "left") {
                    tds[0].insertBefore(tempHeaderObj.removeChild(nextHeaderObj), _headerObj);
                } else {
                    tds[0].appendChild(tempHeaderObj.removeChild(nextHeaderObj));
                }
                tempHeaderObj = null;
            } else {
                if (useFilterExist && this.options.showSortableUseFilter) {
                    var parentElement = tds[0].parentElement;
                    var wrapper = document.createElement('div');
                    wrapper.appendChild(tds[0]);
                    wrapper.appendChild(tempHeaderObj2);
                    this.addClass(wrapper, "w2grid_head_sort_div_main_outer_box");
                    parentElement.appendChild(wrapper);
                    this.addClass(tempHeaderObj2, "w2grid_customFilter_sortable_open");
                    if (WebSquare.util.isIE() && parseInt(WebSquare.core.browserVersion(), 10) < 8) {
                        this.addClass(tds[1], "w2grid_head_sort_usefilter_div_main_ie");
                    } else {
                        this.addClass(tds[1], "w2grid_head_sort_usefilter_div_main");
                    }
                }
            }
        } else if (this.options.accessibility === true) {
            ord_css += "_btn";
            var astr = "_accessibility";
            var headSortDivClass = "w2grid_head_sort_div_main_btn";
            if (this.options.sortedIconPosition === 'left') {
                ord_css += "_left";
            }
            headSortDivClass += astr;
            ord_css += astr;
            var sortBtndisplayStyleStr = (hideSortIcon) ? "style = 'display:none'" : "";
            var btnElem;
            if (isSortableHeader) {
                td.innerHTML = "<button " + dataSort + "='sort' class='" + headSortDivClass + " " + ord_css + "' " + sortBtndisplayStyleStr + "></button>";
                btnElem = td.getElementsByTagName("button")[0];
            } else {
                td.innerHTML = "";
                btnElem = td;
            }
            btnElem.appendChild(_headerObj);
            if (nextHeaderObj && tempHeaderObj) {
                if (this._useCheckboxLabel(headerId) && this.headerInfoHash2[headerId].getAttribute("checkboxLabelPosition") !== "left") {
                    btnElem.appendChild(tempHeaderObj.removeChild(nextHeaderObj));
                } else {
                    btnElem.insertBefore(tempHeaderObj.removeChild(nextHeaderObj), _headerObj);
                }
                tempHeaderObj = null;
            } else {
                if (useFilterExist && this.options.showSortableUseFilter) {
                    var targetElem = isSortableHeader ? btnElem : _headerObj;
                    var parentElement = targetElem.parentElement;
                    var wrapper = document.createElement('div');
                    wrapper.appendChild(targetElem);
                    wrapper.appendChild(tempHeaderObj2);
                    this.addClass(wrapper, "w2grid_head_sort_div_main_outer_box")
                    parentElement.appendChild(wrapper);
                    this.addClass(tempHeaderObj2, "w2grid_customFilter_sortable_open");
                    if (WebSquare.util.isIE() && parseInt(WebSquare.core.browserVersion(), 10) < 8) {
                        this.addClass(targetElem, "w2grid_head_sort_usefilter_div_main_ie");
                    } else {
                        this.addClass(targetElem, "w2grid_head_sort_usefilter_div_main");
                    }
                }
            }
        } else {
            ord_css += "_btn";

            var headSortDivClass = "w2grid_head_sort_div_main_btn";
            var sortBtndisplayStyleStr = (hideSortIcon) ? "style = 'display:none'" : "";

            td.innerHTML = "<div " + dataSort + "='sort' class='w2grid_head_sort_div_main_outer'>"
                + "<button class='" + headSortDivClass + " " + ord_css + "'"+sortBtndisplayStyleStr+" >" + ord_text + "</button>"
                + "</div>";

            var tds = td.getElementsByTagName("div");
            var btn = td.getElementsByTagName("button")[0];
            tds[0].insertBefore(_headerObj, btn);
            if (nextHeaderObj && tempHeaderObj) {
                if (this._useCheckboxLabel(headerId) && this.headerInfoHash2[headerId].getAttribute("checkboxLabelPosition") !== "left") {
                    tds[0].insertBefore(tempHeaderObj.removeChild(nextHeaderObj), btn);
                } else {
                    tds[0].insertBefore(tempHeaderObj.removeChild(nextHeaderObj), _headerObj);
                }
                tempHeaderObj = null;
            } else {
                if (useFilterExist && this.options.showSortableUseFilter) {
                    var parentElement = tds[0].parentElement;
                    var wrapper = document.createElement('div');
                    wrapper.appendChild(tds[0]);
                    wrapper.appendChild(tempHeaderObj2);
                    this.addClass(wrapper, "w2grid_head_sort_div_main_outer_box")
                    parentElement.appendChild(wrapper);
                    this.addClass(tempHeaderObj2, "w2grid_customFilter_sortable_open");
                    if (WebSquare.util.isIE() && parseInt(WebSquare.core.browserVersion(), 10) < 8) {
                        this.addClass(tds[1], "w2grid_head_sort_usefilter_div_main_ie");
                    } else {
                        this.addClass(tds[1], "w2grid_head_sort_usefilter_div_main");
                    }
                }
            }
        }
    }
    if (isSortableHeader) {
        var orderAttrStr = "none";
        switch (order) {
            case 0:
                orderAttrStr = "none";
                break;
            case 1:
                orderAttrStr = "ascending";
                break;
            case -1:
                orderAttrStr = "descending";
                break;
            default:
                orderAttrStr = "none";
                break;
        }
        td.setAttribute("aria-sort", orderAttrStr);
    }
};
/**
 * accessibility 설정 팝업 닫기버튼 요소 없을 경우 타이틀로 포커스 이동 WESD-1765
 * titleObj.role = "h2"; 추가 커스터마이징
 */
requires("uiplugin.popup");
WebSquare.uiplugin.popupWindow.prototype.open = function(url, target) {
    try {
        var useWindowPopup = this.useWindowPopup();

        this._compModal = false;
        var isBodyModal = false;
        var _targetFrameObj;
        var parentFrameObj = WebSquare.idCache[this.options.scope_uuid];
        var popupParentFrameObj = parentFrameObj;
        var frameModal = this.options.frameModal;
        var strictModeFrameId = WebSquare.strictModeFrame ? WebSquare.strictModeFrame.uuid : '';

        var topModalFrameObj; //상위 frame에 modal이 있는지 체크
        var bodyComp = WebSquare.getBody();

        if (bodyComp.modal && bodyComp.modal.style.display === "block") {
            isBodyModal = true;
            this._alreadyDisplayedModal = true;
        }

        var w2xPathName = "w2xPath";
        if (WebSquare.util.getEncodeParameterOption("pathName")) {
            w2xPathName = WebSquare.util.getEncodeParameterOption("pathName");
        } else if (WebSquare.util.isEncodeParameter()) {
            w2xPathName = WebSquare.util.encodeParameter("w2xPath");
        }

        var popupURI = this.options.popupUrl;
        if (this.options.xml && typeof this.options.xml != 'string') {
            this.options.xml = WebSquare.xml.serialize(this.options.xml);
        }

        // xml 속성 deprecated
        // param 속성과 paramType 속성을 지정하도록 유도
        var temp_idx = "";
        if (this.options.frameMode === "wframe" && !useWindowPopup) {
            if (url) {
                popupURI = url;
            }
        } else if(this.options.useQueryString == false) {
            WebSquare._popupInfo = "";
            var popupInfo = {};
            if (url) {
                // WebSquare.core.getURL -> this.getURL 과 비슷한 것으로 수정 필
                popupURI = WebSquare.baseURI + popupURI + (popupURI.indexOf("?") > -1 ? "&" : "?");
                if (WebSquare.util.isEncodeParameter()) {
                    if (WebSquare.util.getEncodeParameterOption("onlyParam")) {
                        var paramList = url.split(/[\&\?]/);
                        var sep;
                        for (var i = 0; i < paramList.length; i++) {
                            if ((sep = paramList[i].indexOf("=")) >= 0) {
                                paramList[i] = WebSquare.util.encodeParameter(paramList[i].substring(0, sep)) + paramList[i].substring(sep);
                            }
                        }
                        url = paramList.join('&');
                        popupURI = popupURI + w2xPathName + "=" + WebSquare.core.getURL(url);
                    } else {
                        popupURI = popupURI + w2xPathName + "=" + WebSquare.util.encodeParameter(WebSquare.core.getURL(url));
                    }
                } else {
                    popupURI = popupURI + w2xPathName + "=" + WebSquare.core.getURL(url);
                }
            }

            if (this.options.xml) {
                temp_idx = "idx10_" + (new Date()).getTime() + Math.random() * 10000;
                WebSquare.uiplugin.popup.popupParams[temp_idx] = this.options.xml;
                popupInfo.idx = this.idx;
            }

            popupInfo.popupID = this.id;
            popupInfo.w2xHome = WebSquare.w2xHome;
            popupInfo.w2xDocumentRoot = WebSquare.w2xDocumentRoot + this._getW2Config();
            WebSquare._popupInfo = JSON.stringify(popupInfo);
        } else {
            if ((useWindowPopup == true || this.options.frameMode == "iframe") && (this.options.resourceParam == true || this.options.resourceParam == "true")) {//browerPopup,iframe
                //console.log('url:',url);
                var urlParamList = url.split(/[\&\?\#]/);
                //console.log('urlParamList:',urlParamList);
                if (urlParamList.length > 1) {
                    //console.log('urlParamList[0]',urlParamList[0]);
                    var tempUrlParam = url.substring(urlParamList[0].length,url.length);
                    //console.log('tempUrlParam',tempUrlParam);
                    if (tempUrlParam.startsWith("?")) {
                        url = urlParamList[0] + tempUrlParam.replace('?','&');
                    }
                    //console.log('url',url);
                }

                url = url + "&w2xGetParamKey=true";
            }
            if (url) {
                // WebSquare.core.getURL -> this.getURL 과 비슷한 것으로 수정 필
                popupURI = WebSquare.baseURI + popupURI + (popupURI.indexOf("?") > -1 ? "&" : "?");
                if (WebSquare.util.getEncodeParameterOption("onlyParam")) {
                    var paramList = url.split(/[\&\?]/);
                    var sep;
                    for (var i = 0; i < paramList.length; i++) {
                        if ((sep = paramList[i].indexOf("=")) >= 0) {
                            paramList[i] = WebSquare.util.encodeParameter(paramList[i].substring(0, sep)) + paramList[i].substring(sep);
                        }
                    }
                    url = paramList.join('&');
                }
                if (WebSquare.util.isEncodeParameter()) {
                    if (WebSquare.util.getEncodeParameterOption("onlyParam")) {
                        popupURI = popupURI + w2xPathName + "=" + WebSquare.core.getURL(url) + "&";
                    } else {
                        popupURI = popupURI + w2xPathName + "=" + WebSquare.util.encodeParameter(WebSquare.core.getURL(url) + "&");
                    }
                } else {
                    popupURI = popupURI + w2xPathName + "=" + WebSquare.core.getURL(url) + "&";
                }
            } else {
                // 입력받은 경로를 그대로 넣는다
                popupURI = popupURI + (popupURI.indexOf("?") > -1 ? "&" : "?");
            }

            if (this.options.xml) {
                temp_idx = "idx10_" + (new Date()).getTime() + Math.random() * 10000;
                WebSquare.uiplugin.popup.popupParams[temp_idx] = this.options.xml;
                if (WebSquare.util.isEncodeParameter()) {
                    if (WebSquare.util.getEncodeParameterOption("onlyParam")) {
                        popupURI = popupURI + WebSquare.util.encodeParameter("popupID=") + this.id;
                        popupURI += WebSquare.util.encodeParameter("&idx=") + temp_idx;
                        popupURI += WebSquare.util.encodeParameter("&w2xHome=") + WebSquare.w2xHome;
                        popupURI += WebSquare.util.encodeParameter("&w2xDocumentRoot=") + WebSquare.w2xDocumentRoot + this._getW2Config();
                    } else {
                        popupURI = popupURI + WebSquare.util.encodeParameter("popupID=" + this.id + "&idx=" + temp_idx + "&w2xHome=" + WebSquare.w2xHome + "&w2xDocumentRoot=" + WebSquare.w2xDocumentRoot + this._getW2Config());
                    }
                } else {
                    popupURI = popupURI + "popupID=" + this.id + "&idx=" + temp_idx + "&w2xHome=" + WebSquare.w2xHome + "&w2xDocumentRoot=" + WebSquare.w2xDocumentRoot + this._getW2Config();
                }

            } else {
                if (WebSquare.util.isEncodeParameter()) {
                    if (WebSquare.util.isEncodeParameter()) {
                        popupURI = popupURI + WebSquare.util.encodeParameter("popupID=") + this.id;
                        popupURI += WebSquare.util.encodeParameter("&w2xHome=") + WebSquare.w2xHome;
                        popupURI += WebSquare.util.encodeParameter("&w2xDocumentRoot=") + WebSquare.w2xDocumentRoot + this._getW2Config();
                    } else {
                        popupURI = popupURI + WebSquare.util.encodeParameter("popupID=" + this.id + "&w2xHome=" + WebSquare.w2xHome + "&w2xDocumentRoot=" + WebSquare.w2xDocumentRoot + this._getW2Config());
                    }
                } else {
                    popupURI = popupURI + "popupID=" + this.id + "&w2xHome=" + WebSquare.w2xHome + "&w2xDocumentRoot=" + WebSquare.w2xDocumentRoot + this._getW2Config();
                }
            }
        }

        if (useWindowPopup == true) {
            // make url
            //			var popupURI = url;
            //			if(url.match(/\.xml$/)){
            //				popupURI = this.getWebsquareUrl(url, this.params, target);
            //			} else if(url.match(/\.html$/)){
            //				popupURI = this.getHTMLUrl(url, this.params, target);
            //			}

            // make popupOption
            var popupOption = this.makePopupString(this.options);

            this.popupWin = window.open(popupURI, this.options.id, popupOption);
            if (!this.popupWin) {
                return;
            }
            WebSquare.uiplugin.popup._status = "busy";
            WebSquare.core.setTimer(function() {
                WebSquare.uiplugin.popup._status = "idle";
            }, {
                key: _tempId + "_preventPopupClickTimer",
                delay: 1
            });

        } else {
            requires("uiplugin.window");
            var useMaximize = this.options.useMaximize === false ? false : true;
            var className = (this.options.className && this.options.className != "") ? " " + this.options.className : "";
            var buttonInfo = this.options.buttonInfo;

            var parentWindowOverflowStyle;
            if (strictModeFrameId !== this.options.scope_uuid 
                && this.options.frameModal === true && this.options.type !== "browser") {
                var parentFrame = WebSquare.idCache[this.options.scope_uuid];
                parentWindowOverflowStyle = WebSquare.util.getStyleProperty(parentFrame.render, "overflow");
            } else {
                parentWindowOverflowStyle = WebSquare.util.getStyleProperty(document.documentElement, "overflow");
            }

            //[WPF-1985] minimize 기능을 사용할 경우 foldOnMinimized는 무조건 true 설정
