                    }
                    if (link.length != 0) {
                        isNonEditable = false;
                    } else {
                        isNonEditable = true;
                    }
                }
            }
        }

        if (this.isColMerge && this.cellInfoHash[this.tdIdList[i]].options.colMerge) {
            var beforeValue = this._dataList.getCellData(rowIndex - 1, i);
            var upperCheck = this.upperGroupingTest(rowIndex, i);
            var nowValue = this._dataList.getCellData(rowIndex, i);
