                isNonEditable = true;
            }
        }

        if (this.hiddenRowObj.length > 0 && !this._getRowVisible(rowIndex)) {
            isNonEditable = true;
        }

        if (this.getMerged(rowIndex, i) && !this.cellMergeInfo[rowIndex + "_" + i]) {
            isNonEditable = true;
