/**
 * 5.0_4.5245B.20240927.114732_1.5 버전에서 생긴 문제로 이후 버전업 되어을 때 체크 후 삭제 필요
 * 그리드뷰 포커스 이동 문제 수정 WESD-1767
 */
WebSquare.uiplugin.gridView.prototype.moveHorizontal = function(e, direct, editMode, keyCode) {
    if (this.options.focusMove == "false" || this.options.focusMove == "vertical") {
        var keyCode = (e.charCode) ? e.charCode : e.keyCode;
        if (!this.options.senseReader) {
            return false;
        } else if (keyCode != 9) {
            return false;
        }
    }

    var focusedCell = this.getLastFocusedCell();
    var row = focusedCell.focusedRowIndex;
    var col = focusedCell.focusedColIndex;
    var colIndexArr = this.colIndexInfo.body.colInfo.colIndexArr;
    var colIndex = this._getRealColIndex("body", this.tdIdList[col]) + this.defaultColCnt;
    var colIndexMatch = this.colIndexInfo.body.colInfo.colIndexMatch;
    var columnOrder = this.columnOrder;
    var trIndexArr = this.colIndexes.bodyColInfo.trIndexArr;
    var trIndex = trIndexArr[col + this.defaultColCnt];
    var isTabKey = e ? e.keyCode == 9 : false;
    var isTabOrEnter = e ? (e.keyCode == 9 || e.keyCode == 13) : false;
    var isMoveKey;
    var isShiftKey = e ? e.shiftKey : false;
    var direct = direct || "right";
    if (this.options.moveKeyEditModeAll == true && e == false) {
        isMoveKey = keyCode ? (keyCode == 37 || keyCode == 39) : false;
    } else {
        isMoveKey = e ? (37 <= e.keyCode && e.keyCode <= 40) : false;
    }
    if (focusedCell.bTrIndex) {
        trIndex = focusedCell.bTrIndex;
    }
    var targetCol = null;
    var targetRow = row;
    if (this.options.focusMultiRow) {
        if (direct == "left") {
            var start = colIndex - 1;
            var end = this.defaultColCnt - 1;
            var inc = -1;
        } else if (direct == "right") {
            var start = colIndex + 1;
            var end = colIndexMatch.length;
            var inc = +1;
        } else if (direct == "home") {
            var start = this.defaultColCnt;
            var end = colIndexMatch.length;
            var inc = +1;
        } else { // if(direct == "end")
            var start = colIndexMatch.length - 1;
            var end = this.defaultColCnt - 1;
            var inc = -1;
        }
        for (var i = start; i != end; i += inc) {
            var column = colIndexMatch[i];
            if (this.hiddenList[i]) {
                continue;
            }
            for (var j = column.length - 1; j >= 0; j--) {
                var newCol = column[j] - this.defaultColCnt;
                if (this.hiddenRowObj.length > 0 && !this._getRowVisible(row)) {
                    continue;
                }
                if (this.getMerged(row, newCol) && !this.cellMergeInfo[row + "_" + newCol]) {
                    continue;
                }
                var newTrIndex = trIndexArr[column[j]];

                if (newTrIndex <= trIndex && ((direct == "left" || direct == "right") ? newCol != col : true)) {

                    if ((this.options.readOnlyTabIgnore || this.options.senseReader) && this.___getEditReadOnly(row, newCol)) {
                        break;
                    }
                    if (isTabOrEnter && (this.options.ignoreNonEditableCell || this.options.senseReader) && (this.___getEditReadOnly(row, newCol) || this._getEditDisabled(row, newCol))) {
                        break;
                    }
                    if (this.isColMerge && this.cellInfoHash[this.tdIdList[newCol]].options.colMerge) {
                        var beforeValue = this.dataList.getCellData(row - 1, newCol);
                        var upperCheck = this.upperGroupingTest(row, newCol);
                        var nowValue = this.dataList.getCellData(row, newCol);
                        if (beforeValue == nowValue && upperCheck) {
                            break;
                        }
                    }

                    targetCol = newCol;
                    break;
                }
            }
            if (targetCol !== null) {
                break;
            }
        }
    } else {
        var cellInfo = this.getCellInfo(col);
        var isMultiLink = false;
        if (this.options.senseReader && cellInfo.options.inputType == "user" && this.___getEditReadOnly(row, col)) {
            isMultiLink = true;
        } else {
            this.focusedCellLinkIndex = -1;
            this.focusedCellLinkLength = 0;
        }
        var movedInfo = this.getLocationRowCol(row, col);
        var movedRow = movedInfo.rowIndex;
        var movedCol = movedInfo.colIndex;
        var multiRowNum = this.htmlInfo.body.rowAttrArr.length;

        if (focusedCell.bMovedRow) {
            movedRow = focusedCell.bMovedRow;
        }
        var rowAttrNum = movedRow % multiRowNum;   

        if (direct == "left") {
            if (isMultiLink && this.focusedCellLinkIndex > 0) {
                var start = movedCol;
                var end = columnOrder.length;
                var inc = +1;
            } else {
                var start = movedCol - 1;
                var end = -1;
                var inc = -1;
            }
        } else if (direct == "right") {
            if (isMultiLink && this.focusedCellLinkIndex + 1 < this.focusedCellLinkLength) {
                var start = movedCol;
                var end = columnOrder.length;
                var inc = +1;
            } else {
                this.focusedCellLinkIndex = -1;
                this.focusedCellLinkLength = 0;
                var start = movedCol + movedInfo.colSize;
                var end = columnOrder.length;
                var inc = +1;
            }

        } else if (direct == "home") {
            var start = 0;
            var end = columnOrder.length;
            var inc = +1;
            movedRow = movedRow - rowAttrNum;
        } else { // if(direct == "end")
            var start = columnOrder.length - 1;
            var end = 0;
            var inc = -1;
            movedRow = movedRow + multiRowNum - rowAttrNum - 1;
        }

        for (var i = start; ; i += inc) {
            if (i == end) {
                if (direct == "left" && rowAttrNum > 0) {
                    i = columnOrder.length - 1;
                    rowAttrNum--;
                    movedRow--;
                } else if (direct == "right" && rowAttrNum < multiRowNum - 1) {
                    i = 0;
                    rowAttrNum++;
                    movedRow++;
                } else {
                    break;
                }
            }

            var newInfo = this.getOriginalRowCol(movedRow, i);

            if(newInfo.noLeftTop) {
                continue;
            }

            if (inc > 0) {
                inc = newInfo.colSize;
            }
            var newCol = newInfo.colIndex;

            if (this.hiddenList[i + this.defaultColCnt]) {
                continue;
            }
            if (this.hiddenRowObj.length > 0 && !this._getRowVisible(row)) {
                continue;
            }
            if (this.getMerged(row, newCol) && !this.cellMergeInfo[row + "_" + newCol]) {
