WebSquare.uiplugin.autoComplete.prototype._setItemTableBody = function(direction, tdHeight) {
    try {
        var top = 0;
        if (direction == "up") {
            top = WebSquare.style.getAbsoluteTop(this.render) - this.itemTable.render.offsetHeight;
        } else {
            top = WebSquare.style.getAbsoluteTop(this.render) + this.render.offsetHeight;
