        }
        if (WebSquare.style.getComputedStyle(this.render, 'padding-top')) { 
            ptop = (WebSquare.style.getComputedStyle(this.render, 'padding-top')).replace('px','')*1;
        }
        if (WebSquare.style.getComputedStyle(this.render, 'border-bottom-width')) { 
            bbottom = (WebSquare.style.getComputedStyle(this.render, 'border-bottom-width')).replace('px','')*1;
