            pbottom = (WebSquare.style.getComputedStyle(this.render, 'padding-bottom')).replace('px','')*1;
        }        
        if (direction == "up") {
            top = - this.itemTable.render.offsetHeight - (btop + ptop);
        } else {
            top = this.render.offsetHeight - (bbottom + pbottom);
        }

        var left = this.render.offsetWidth - this.itemTable.render.offsetWidth;
        var bleft = 0;
        var pleft = 0;
        if (WebSquare.style.getComputedStyle(this.render, 'border-left-width')) { 
            bleft = (WebSquare.style.getComputedStyle(this.render, 'border-left-width')).replace('px','')*1;
