WebSquare.uiplugin.autoComplete.prototype.setAction = function() {
    try {
        if (this.options.renderType == "native" || this.options.renderType == "input") {
            this.setSetting();
        }

        if (this.options.nextTabID) {
            this.setNextTabID(this.options.nextTabID, this.scope_id);
        }

        this.event.addListener(this.dom.input, "onblur", this.event.bindAsEventListener(this, this.handleblurEventInput));
        if (WebSquare.util.isTouchDevice()) {
            this.event.addListener(this.render, "ontouchstart", this.event.bindAsEventListener(this, this.handleMousedownEvent));
            this.event.addListener(this.render, "ontouchmove", this.event.bindAsEventListener(this, function(e) {
                if (WebSquare.getBody().getLayerListener().existShow == true) {
                    WebSquare.getBody().getLayerListener().hideAll();
                }
            }));
        }
        this.event.addListener(this.render, "onmousedown", this.event.bindAsEventListener(this, this.handleMousedownEvent));
        this.event.addListener(this.render, "onclick", this.event.bindAsEventListener(this, this.handleClickEvent));
        this.event.addListener(this.dom.input, "onkeypress", this.event.bindAsEventListener(this, this.handleKeypressEvent));
        this.event.addListener(this.dom.input, "onkeyup", this.event.bindAsEventListener(this, this.handleInputKeyupEvent));
        this.event.addListener(this.render, "onkeyup", this.event.bindAsEventListener(this, this.handleKeyupEvent));
        if (this.options.validateOnInput) {
            this.event.addListener(this.dom.input, "oninput", this.event.bindAsEventListener(this, this.handleInputEvent));
        }
        this.event.addListener(this.render, "onmousewheel", this.event.bindAsEventListener(this, this.handleMousewheelEvent));
        this.event.addListener(this.render, "onfocus", this.event.bindAsEventListener(this, this.handleFocusEvent));
        this.event.addListener(this.render, "onblur", this.event.bindAsEventListener(this, this.handleBlurEvent));
        this.event.addListener(this.render, "onmouseover", this.event.bindAsEventListener(this, this.handleMouseoverEvent));
        this.event.addListener(this.render, "onmouseout", this.event.bindAsEventListener(this, this.handleMouseoutEvent));
        this.bind("onviewchange", function(e) {
            this.onchangeFlag = true;
        });
        if (this.options.closeonmouseleave == true) {
            this.event.addListener(this.render, "onmouseleave", this.event.bindAsEventListener(this, this.handleMouseleaveEvent));
        }

        if (this.options.renderType == "native") {
            this.event.addListener(this.dom.imgArrow, "onfocusin", this.event.bindAsEventListener(this, this.handleArrowFocusInEvent));
            this.event.addListener(this.render, "onkeydown", this.event.bindAsEventListener(this, this.handleKeydownEvent));
        } else if (this.options.renderType == "input") {
            this.event.addListener(this.dom.input, "onkeydown", this.event.bindAsEventListener(this, this.handleKeydownAccessibilityEvent));
        } else {
            this.event.addListener(this.render, "onkeydown", this.event.bindAsEventListener(this, this.handleKeydownEvent));
        }

        if (this.modelControl.isItemsetBinded()) {
            this.refreshItemArr();
            this.componentRedraw();

        }

        if (this.modelControl.isBinded()) {
            var value = this.modelControl.getData();
            this.setValueNM(value);
        }

        if (this.selectedIndex == -1 && (this.options.emptyIndex == 0 || !this.options.emptyIndex)) {
            this.setSelectedIndexNM(0);
            if (this.modelControl.isBinded()) {
                this.modelControl.setData(this.getValue());
            }
        } else if (this.options.emptyIndex && typeof this.options.emptyIndex === 'number') {

            this.setSelectedIndexNM(this.options.emptyIndex);

            if (this.modelControl.isBinded()) {
                this.modelControl.setData(this.getValue());
            }
        }

        if (this.options.readOnly) {
            this.onPropertyChange("readOnly", WebSquare.util.getBoolean(this.options.readOnly));
        }

        if (this.options.mandatory) {
            this.onPropertyChange("mandatory", WebSquare.util.getBoolean(this.options.mandatory));
        }

    } catch (e) {
        WebSquare.exception.printStackTrace(e, null, this);
    }
};
