WebSquare.uiplugin.calendar.prototype.refresh = function() {
    try {
        this.holidayXpath(); 
        if (this.options.dateMoveFixed && (this.fixedDateHelper.getYear() == this.selectedDateHelper.getYear() && this.fixedDateHelper.getMonth() == this.selectedDateHelper.getMonth())) {
            this.selectedDateHelper.setDate(this.fixedDateHelper.getDate());
        }
        this.updateCalendar();

        if (this.modelControl.isBinded()) {
            var oldValue = this.getValue();
            var value = this.modelControl.getData();
            if (value) {
                this.selectedDateHelper.setDateAllByString(value);
                this.setSelectedDay(this.selectedDateHelper.getDate());
                if (this.dom.currentDate) {
                    this.dom.currentDate.innerHTML = this.selectedDateHelper.getFormatDateAll(this.options.displayFormat);
                }
                if (oldValue != this.getValue()) {
                    WebSquare.event.fireEvent(this, "onchange");
                }
            }
        }

        if (this.options.calendarValueType != "yearMonth" && this.options.calendarValueType != "year") {

            if (this.options.keepFixedDate) {
                this.dom.currentDate.innerHTML = this.todayHelper.getFormatDateAll(this.options.displayFormat);
            } else if (this.options.dateMoveFixed == true) {
                this.dom.currentDate.innerHTML = this.fixedDateHelper.getFormatDateAll(this.options.displayFormat);
            } else {
                this.dom.currentDate.innerHTML = this.selectedDateHelper.getFormatDateAll(this.options.displayFormat);
            }

            if (!WebSquare.util.isMobile() && this.getStyle("display") != "none") { 
                for (var row = 0; row < this.options.visibleWeekNum; row++) {
                    for (var col = 0; col < 7; col++) {
                        var cell = this.getElementById(this.id + "_cell_" + row + "_" + col);
                        if (!cell) {
                            continue;
                        }
                        var renderCell = cell;
                        if (this.options.renderType == "native" && !WebSquare.util.isMobile()) {
                            renderCell = cell.getElementsByTagName("button")[0];
                            if (renderCell == undefined) {
                                renderCell = cell;
                            }
                        }

                        if (this.__hasClass(cell, "w2calendar_selected")) {
                            if (this.options.renderType == "native") {
                                if (this.options.keepFocusSelect == false) {
                                    try {
                                        if (this.options.focusOnStart) {
                                            cell.firstChild.focus();
                                        }
                                    } catch (e) {
                                        WebSquare.exception.printStackTrace(e, null, this);
                                    }
                                }
                            } else {
                                try {
                                    cell.setAttribute("tabIndex", "0");
                                    if (this.options.accessibility === true) {
                                    cell.setAttribute("aria-selected","true");
                                    }
                                    if (this.options.focusOnStart) {
                                        cell.focus();
                                    }
                                } catch (e) {
                                    WebSquare.exception.printStackTrace(e, null, this);
                                }
                            }
                            renderCell.setAttribute("title", WebSquare.language.getMessage("Calendar_select_title"));
                        } else {
                            cell.setAttribute("tabIndex", "-1");
                            if (this.options.accessibility === true) {
                            cell.setAttribute("aria-selected","false");
                            }
                            renderCell.removeAttribute("title");
                        }
                    }
                }
            }
        }
        this.broadcast({
            "linkedDataList": ["refresh"]
        });
    } catch (e) {
        WebSquare.exception.printStackTrace(e, null, this);
    }
};

WebSquare.uiplugin.calendar.prototype.updateCalendar = function() {
    try {
        var selectedYear = this.selectedDateHelper.getYear();
        var selectedMonth = this.selectedDateHelper.getMonth();
        var selectedDate = this.selectedDateHelper.getDate();
        var selectedHour = this.selectedDateHelper.getHour();
        var selectedMinute = this.selectedDateHelper.getMinute();
        var selectedSecond = this.selectedDateHelper.getSecond();

        var todayYear = this.todayHelper.getYear();
        var todayMonth = this.todayHelper.getMonth();
        var todayDate = this.todayHelper.getDate();

        var sameMonth = false;
        if (selectedYear === todayYear && selectedMonth === todayMonth) {
            sameMonth = true;
        }

        if (this.options.pickerType !== "dynamic") {
            if (this.options.renderType == "native") {
                if (this.options.useYearSelect) {
                    for (var i = 0; i < this.dom.selectboxYear.options.length; i++) {
                        if (this.dom.selectboxYear.options[i].value == selectedYear) {
                            this.dom.selectboxYear.options[i].selected = true;
                        }
                    }
                } else {
                    this.getChild(this.id + "_selectbox_year").setValue(selectedYear);
                }

                if (this.options.useMonthSelect) {
                    for (var i = 0; i < this.dom.selectboxMonth.options.length; i++) {
                        if (this.dom.selectboxMonth.options[i].value == selectedMonth) {
                            this.dom.selectboxMonth.options[i].selected = true;
                        }
                    }
                } else {
                    this.getChild(this.id + "_selectbox_month").setValue(selectedMonth);
                }
            } else {
                this.getChild(this.id + "_selectbox_year").setValue(selectedYear);
                this.getChild(this.id + "_selectbox_month").setValue(selectedMonth);
                if (this.options.calendarValueType == "yearMonthDateHour" && this.options.serverSync) {
                    this.getChild(this.id + "_selectbox_hour").setValue(selectedHour);
                } else if (this.options.calendarValueType == "yearMonthDateTime" && this.options.serverSync) {
                    this.getChild(this.id + "_selectbox_hour").setValue(selectedHour);
                    this.getChild(this.id + "_selectbox_minute").setValue(selectedMinute);
                } else if (this.options.calendarValueType == "yearMonthDateTimeSec" && this.options.serverSync) {
                    this.getChild(this.id + "_selectbox_hour").setValue(selectedHour);
                    this.getChild(this.id + "_selectbox_minute").setValue(selectedMinute);
                    this.getChild(this.id + "_selectbox_second").setValue(selectedSecond);
                }
            }
        }

        var monthCount = this.selectedDateHelper.getMonthCount();
        var firstDay = this.selectedDateHelper.getFirstDay();

        firstDay = firstDay + (this.shiftDay);

        if (firstDay <= 0) {
            firstDay += 7;
        }

        var rows = this.options.visibleWeekNum;
        var cols = 7;
        var count = 0;

        var tempDateHelper = new WebSquare.uiplugin.dateHelper();
        tempDateHelper.setDateAllByString(this.selectedDateHelper.getDateAll());
        tempDateHelper.setLastMonth();
        var lastMonthCount = tempDateHelper.getMonthCount();
        var lastYear = selectedMonth == 1 ? selectedYear - 1 : selectedYear;
        var lastMonth = selectedMonth == 1 ? 12 : selectedMonth - 1;
        var nextYear = selectedMonth == 12 ? selectedYear + 1 : selectedYear;
        var nextMonth = selectedMonth == 12 ? 1 : selectedMonth + 1;

        var nextMonthHelper = new WebSquare.uiplugin.dateHelper();
        nextMonthHelper.setDateAllByString(this.selectedDateHelper.getDateAll());
        nextMonthHelper.setNextMonth();
        var nextMonthCount = nextMonthHelper.getMonthCount();

        var disableAfterDate = this.options.disableAfterDate;
        var disableBeforeDate = this.options.disableBeforeDate
        var disabledDate = this.options.disabledDate;
        var enableDate = this.options.enableDate;
        if (this.options.ioFormat && this.options.ioFormat.length >= 8 && this.options.ioFormat !== "yyyyMMdd") {
            var ioFormat = this.options.ioFormat;
            if (disableAfterDate) {
                disableAfterDate = WebSquare.text.unformatDate(ioFormat.substr(0, 8), disableAfterDate);
            }

            if (disableBeforeDate) {
                disableBeforeDate = WebSquare.text.unformatDate(ioFormat.substr(0, 8), disableBeforeDate);
            }

            if (disabledDate) {
                var disableDateArr = disabledDate.split(' ');
                for (var i = 0; i < disableDateArr.length; i++) {
                    disableDateArr[i] = WebSquare.text.unformatDate(ioFormat.substr(0, 8), disableDateArr[i]);
                }
                disabledDate = disableDateArr.join(' ');
            }

        }

        for (var row = 0; row < rows; row++) {
            for (var col = 0; col < cols; col++) {
                count++;
                var date = count - firstDay;
                var day = (firstDay + date - 1) % 7;
                var label = "";

                var cell = this.getElementById(this.id + "_cell_" + row + "_" + col);
                if (!cell) {
                    continue;
                }

                if (disableBeforeDate) {
                    if (disableBeforeDate.length == 8) {
                        var yearNum = parseInt(disableBeforeDate.substr(0, 4), 10) || 0;
                        var monthNum = parseInt(disableBeforeDate.substr(4, 2), 10) || 0;
                        var dateNum = parseInt(disableBeforeDate.substr(6, 2), 10) || 0;
                    }
                    var disableBeforeToday = (yearNum > this.selectedDateHelper.getYear()
                        || yearNum == this.selectedDateHelper.getYear() && monthNum > this.selectedDateHelper.getMonth()
                        || yearNum == this.selectedDateHelper.getYear() && monthNum == this.selectedDateHelper.getMonth() && dateNum > date
                    );
                } else {
                    var disableBeforeToday = this.options.disableBeforeToday
                        && (this.todayHelper.getYear() > this.selectedDateHelper.getYear()
                            || this.todayHelper.getYear() == this.selectedDateHelper.getYear() && this.todayHelper.getMonth() > this.selectedDateHelper.getMonth()
                            || this.todayHelper.getYear() == this.selectedDateHelper.getYear() && this.todayHelper.getMonth() == this.selectedDateHelper.getMonth() && this.todayHelper.getDate() > date
                        );
                }
                if (disableAfterDate) {
                    if (disableAfterDate.length == 8) {
                        var yearNum = parseInt(disableAfterDate.substr(0, 4), 10) || 0;
                        var monthNum = parseInt(disableAfterDate.substr(4, 2), 10) || 0;
                        var dateNum = parseInt(disableAfterDate.substr(6, 2), 10) || 0;
                    }
                    var disableAfterToday = (yearNum < this.selectedDateHelper.getYear()
                        || yearNum == this.selectedDateHelper.getYear() && monthNum < this.selectedDateHelper.getMonth()
                        || yearNum == this.selectedDateHelper.getYear() && monthNum == this.selectedDateHelper.getMonth() && dateNum < date
                    );
                } else {
                    var disableAfterToday = this.options.disableAfterToday
                        && (this.todayHelper.getYear() < this.selectedDateHelper.getYear()
                            || this.todayHelper.getYear() == this.selectedDateHelper.getYear() && this.todayHelper.getMonth() < this.selectedDateHelper.getMonth()
                            || this.todayHelper.getYear() == this.selectedDateHelper.getYear() && this.todayHelper.getMonth() == this.selectedDateHelper.getMonth() && this.todayHelper.getDate() < date
                        );
                }
                var dataIndex = WebSquare.util.getDataPrefix("index");
                if (date < 1) {
                    label = lastMonthCount + date;
                    cell.innerHTML = label;
                    if (disableBeforeToday || disableAfterToday) {
                        cell.className = "w2calendar_col_date w2calendar_date w2calendar_date_off w2calendar_date_lastmonth w2calendar_date_disable";
                    } else {
                        cell.className = "w2calendar_col_date w2calendar_date w2calendar_date_off w2calendar_date_lastmonth";
                    }
                    cell.setAttribute(dataIndex, label);
                    cell.setAttribute("title", WebSquare.language.getMessage("Calendar_tooltip", lastYear, (lastMonth < 10 ? "0" + lastMonth : lastMonth), label));
                    cell.setAttribute("tabindex", "-1");
                    if (this.options.accessibility === true) {
                    cell.setAttribute("aria-selected","false");
                    }
                } else if (date > monthCount) {
                    label = date - monthCount;
                    if (label > nextMonthCount) {
                        label -= nextMonthCount;
                        monthCount += nextMonthCount;
                        nextMonthHelper.setNextMonth();
                        nextMonthCount = nextMonthHelper.getMonthCount();
                    }
                    cell.innerHTML = label;
                    if (disableAfterToday || disableBeforeToday) {
                        cell.className = "w2calendar_col_date w2calendar_date w2calendar_date_off w2calendar_date_nextmonth w2calendar_date_disable";
                    } else {
                        cell.className = "w2calendar_col_date w2calendar_date w2calendar_date_off w2calendar_date_nextmonth";
                    }
                    cell.setAttribute(dataIndex, label);
                    cell.setAttribute("title", WebSquare.language.getMessage("Calendar_tooltip", nextYear, (nextMonth < 10 ? "0" + nextMonth : nextMonth), label));
                    cell.setAttribute("tabindex", "-1");
                    if (this.options.accessibility === true) {
                    cell.setAttribute("aria-selected","false");
                    }
                    if (this.options.highlightSelectedWeek) {
                        if (col === 6 && (date - col <= selectedDate) && (selectedDate <= date)) {
                            for (var highlight = 0; highlight < 7; highlight++) {
                                var week = this.getElementById(this.id + "_cell_" + row + "_" + highlight);
                                this.addClass(week, "w2calendar_selected_week");
                            }
                        }
                    }
                } else {
                    label = date;
                    var holidaylabel;
                    if (date < 10) {
                        holidaylabel = "0" + label;
                    } else {
                        holidaylabel = label;
                    }
                    var holidayMonth;
                    if (selectedMonth < 10) {
                        holidayMonth = "0" + selectedMonth;
                    } else {
                        holidayMonth = selectedMonth;
                    }
                    var holidaycheck = selectedYear + "" + holidayMonth + "" + holidaylabel; // holidaycheck and label are almost same
                    var holidaycheckAll = "*" + "" + holidayMonth + "" + holidaylabel;

                    if (selectedDate === date) {
                        if (disabledDate.indexOf(holidaycheck) !== -1 && this.options.enabledDate.indexOf(holidaycheck) === -1) {
                            cell.className = "w2calendar_col_date w2calendar_date_" + date + " w2calendar_date_disable";
                        } else if (this.options.holiday.indexOf(holidaycheck) !== -1) {
                            cell.className = "w2calendar_col_date w2calendar_date_on w2calendar_date_" + date + " w2calendar_holiday" + " w2calendar_selected " + (this.objCellClass[holidaycheck] || "");
                        } else {
                            cell.className = "w2calendar_col_date w2calendar_date_on w2calendar_date_" + date + " w2calendar_day_" + this.dayIndexArray[day] + " w2calendar_selected " + (this.objCellClass[holidaycheck] || "");
                        }
                        cell.setAttribute("tabindex", "0");
                        if (this.options.accessibility === true) {
                        cell.setAttribute("aria-selected","true");
                        }
                    } else {
                        if ((disabledDate.indexOf(holidaycheck) !== -1 || disabledDate.indexOf('*') !== -1)
                            && this.options.enabledDate.indexOf(holidaycheck) === -1 ) {
                            cell.className = "w2calendar_col_date w2calendar_date_" + date + " w2calendar_date_disable";
                        } else if (this.options.holiday.indexOf(holidaycheck) !== -1 || this.options.holiday.indexOf(holidaycheckAll) !== -1) {
                            cell.className = "w2calendar_col_date w2calendar_date_on w2calendar_date_" + date + " w2calendar_holiday " + (this.objCellClass[holidaycheck] || "");
                        } else  { //other
                            //cell.className = "w2calendar_col_date w2calendar_date_on w2calendar_date_" + date + " w2calendar_day_" + day ; 
                            cell.className = "w2calendar_col_date w2calendar_date_on w2calendar_date_" + date + " w2calendar_day_" + this.dayIndexArray[day] + " " + (this.objCellClass[holidaycheck] || "");
                        }
                        cell.setAttribute("tabindex", "-1");
                        if (this.options.accessibility === true) {
                        cell.setAttribute("aria-selected","false");
                        }
                    }
                    if (sameMonth && todayDate === date) {
                        cell.className += " w2calendar_today";
                    }
                    if (disableBeforeToday || disableAfterToday) {
                        cell.className = "w2calendar_col_date w2calendar_date_" + date + " w2calendar_date_disable";
                    }
                    if (this.options.renderType == "native" && !WebSquare.util.isMobile() && this.options.accessibility !== true) { 
                        cell.innerHTML = "<button>" + label + "</button>";
                    } else {
                        cell.innerHTML = label;
                    }
                    if (this.options.highlightSelectedWeek) {
                        if (col === 6 && (date - col <= selectedDate) && (selectedDate <= date)) {
                            for (var highlight = 0; highlight < 7; highlight++) {
                                var week = this.getElementById(this.id + "_cell_" + row + "_" + highlight);
                                this.addClass(week, "w2calendar_selected_week");
                            }
                        }
                    }
                    cell.setAttribute("title", "");
                    var dataIndex = WebSquare.util.getDataPrefix("index");
                    cell.setAttribute(dataIndex, date);
                }
            }
        }
        if (this.options.pickerType === "dynamic") {
            if (this.options.calendarValueType === "year") {
                this._setDynamicHeaderHTML("year");
                this._drawDynamicTable("year");
            } else {
                this._setDynamicHeaderHTML("month");
            }
        }

        if (this.options.visibleWeekNum !== 6) {
            this.setSize(null, this.dom.content.parentNode.offsetHeight);
        }
    } catch (e) {
        WebSquare.exception.printStackTrace(e, null, this);
    }
};
WebSquare.uiplugin.calendar.prototype.setSelectedDay = function(date) {
    try {
        var dataIndex = WebSquare.util.getDataPrefix("index");
        if (this.options.pickerType === "selectbox") {
            for (var row = 0; row < this.options.visibleWeekNum; row++) {
                for (var col = 0; col < 7; col++) {
                    var cell = this.getElementById(this.id + "_cell_" + row + "_" + col);
                    if (!cell) {
                        continue;
                    }
                    if (!this.hasClass(cell, "w2calendar_date_on")) {
                        continue;
                    }
                    var renderCell = cell;
                    if (this.options.renderType == "native" && !WebSquare.util.isMobile()) {
                        renderCell = cell.getElementsByTagName("button")[0];
                        if (renderCell == undefined) {
                            renderCell = cell;
                        }
                    }

                    if (cell.getAttribute(dataIndex) == date) {
                        this.addClass(cell, "w2calendar_selected");
                        renderCell.setAttribute("title", WebSquare.language.getMessage("Calendar_select_title"));
                        if (this.options.accessibility === true) {
                        cell.setAttribute("aria-selected", "true");
                        }
                        cell.setAttribute("tabIndex", "0");
                    } else {
                        this.removeClass(cell, "w2calendar_selected");
                        renderCell.removeAttribute("title");
                        if (this.options.accessibility === true) {
                        cell.setAttribute("aria-selected", "false");
                        }
                        cell.setAttribute("tabIndex", "-1");
                    }
                }
            }

        } else if (this.options.pickerType === "dynamic") {
            if (this.options.calendarValueType == "year" || this.options.calendarValueType == "yearMonth") {
                for (var cell = 0; cell < 12; cell++) {
                    var cellDom = this.getElementById(this.id + "_picker_cell_" + cell);
                    if (!cellDom) {
                        continue;
                    }
                    var matchedDataIndex = cellDom.getAttribute(dataIndex);
                    if (this.options.calendarValueType == "year" && this.dynamicCalendarStatus === "year") {
                        matchedDataIndex = cellDom.firstChild.innerText;
                    }                    
                    if (matchedDataIndex == date) {
                        this.addClass(cellDom, "active");
                        cellDom.setAttribute("tabIndex", "0");
                        cellDom.setAttribute("aria-selected","true");
                        cellDom.setAttribute("title", WebSquare.language.getMessage("Calendar_select_title"));
                    } else {
                        this.removeClass(cellDom, "active");
                        cellDom.removeAttribute("title");
                        cellDom.setAttribute("aria-selected","false");
                        cellDom.setAttribute("tabIndex", "-1");
                    }
                }
            } else {
                for (var row = 0; row < this.options.visibleWeekNum; row++) {
                    for (var col = 0; col < 7; col++) {
                        var cell = this.getElementById(this.id + "_cell_" + row + "_" + col);
                        if (!cell) {
                            continue;
                        }
                        if (!this.hasClass(cell, "w2calendar_date_on")) {
                            continue;
                        }
                        var renderCell = cell;
                        if (this.options.renderType == "native" && !WebSquare.util.isMobile()) {
                            renderCell = cell.getElementsByTagName("button")[0];
                            if (renderCell == undefined) {
                                renderCell = cell;
                            }
                        }

                        if (cell.getAttribute(dataIndex) == date) {
                            this.addClass(cell, "w2calendar_selected");
                            renderCell.setAttribute("title", WebSquare.language.getMessage("Calendar_select_title"));
                            cell.setAttribute("tabIndex", "0");
