WebSquare.uiplugin.checkcombobox.prototype.itemTableHandleKeydownEvent = function(e) {
    try {
        var target = WebSquare.event.getTarget(e);
        var selectedIndex =  parseInt(this.itemTable.getSelectedIndex());
        var keyCode = (e.charCode) ? e.charCode : e.keyCode;
        var newIndex = selectedIndex;
        var cnt = this.itemTable.getItemCount();
        var itemTableUl = document.getElementById(this.itemTable.id + "_main");
        if (keyCode == 9 && e.shiftKey || keyCode === 38) {
            WebSquare.event.preventDefault(e);
            if (this.navBtnReached !== true) {
                if (newIndex > 0) {
                    while ((0 <= newIndex - 1) && this.itemTable._getCellDisabled(newIndex - 1) || this.itemTable._getCellHidden(newIndex - 1)) {
                        newIndex--;
                        if (newIndex === 0) {
                            this.itemTable.endReached = true;
                        }
                    }
                    if (newIndex > 0) {
                        this.itemTable.setSelectedIndex(newIndex - 1);
                        var checkbox = this.itemTable.selectedCell.querySelector('#' + this.itemTable.selectedCell.id + '_checkbox');
                        if (checkbox) {
                            checkbox.focus();
                            itemTableUl.setAttribute("aria-activedescendant", checkbox.id);
                        }
                    }
                } else {
                    this.itemTable.endReached = true;
                }
            } else {
                if (target === this.dom.confirmBtn) {
                    this.selectedCell = this.itemTableLastCell;
                    var dataIndex = WebSquare.util.getDataPrefix("index");
                    this.dom.confirmBtn.removeAttribute("tabIndex");
                    this.itemTable.setSelectedIndex(this.selectedCell.getAttribute(dataIndex));
                    var checkbox = this.itemTable.selectedCell.querySelector('#' + this.itemTable.selectedCell.id + '_checkbox');
                    if (checkbox) {
                        checkbox.focus();
                        itemTableUl.setAttribute("aria-activedescendant", checkbox.id);
                    }
                    this.navBtnReached = false;
                }
                if (target === this.dom.cancelBtn) {
                    if (this.dom.confirmBtn) {
                        this.dom.cancelBtn.removeAttribute("tabIndex");
                        this.dom.confirmBtn.setAttribute("tabIndex", 0);
                        this.dom.confirmBtn.focus();
                    }
                }
            }
        } else if (keyCode == 9 && !e.shiftKey || keyCode === 40) {
            WebSquare.event.preventDefault(e);
            if (newIndex + 1 < cnt) {
                newIndex++;
                while (newIndex + 1 <= cnt && this.itemTable._getCellDisabled(newIndex) || this.itemTable._getCellHidden(newIndex)) {
                    newIndex++;
                    if ((newIndex === cnt)) {
                        if (this.options.navBtn) {
                            this.navBtnReached = true;
                        } else {
                            this.itemTable.endReached = true;
                        }
                    } 
                }
                if (newIndex < cnt) {
                    this.itemTable.setSelectedIndex(newIndex);
                    var checkbox = this.itemTable.selectedCell.querySelector('#' + this.itemTable.selectedCell.id + '_checkbox');
                    if (checkbox) {
                        checkbox.focus();
                        itemTableUl.setAttribute("aria-activedescendant", checkbox.id);
                    }
                }
            } else {
                if (this.options.navBtn) {
                    this.navBtnReached = true;
                } else {
                    this.itemTable.endReached = true;
                }
            }
            if (this.navBtnReached === true) {
                if ((target !== this.dom.confirmBtn) && (target !== this.dom.cancelBtn)) {
                    this.itemTableLastCell = this.itemTable.selectedCell;
                    if (this.dom.confirmBtn) {
                        this.dom.confirmBtn.setAttribute("tabIndex", 0);
                        this.dom.confirmBtn.focus();
                    }
                    this.removeClass(this.itemTable.selectedCell, this.itemTable.options.w2table_col_over);
                }
                if (target === this.dom.confirmBtn) {
                    if (this.dom.cancelBtn) {
                        this.dom.confirmBtn.removeAttribute("tabIndex");
                        this.dom.cancelBtn.setAttribute("tabIndex", 0);
                        this.dom.cancelBtn.focus();
                    }
                }
                if (target === this.dom.cancelBtn) {
                    if (this.itemTable.selectedCell !== null) {
                        this.itemTable.selectedCell = null;
                    }
                    this.itemTable.endReached = true;
                    this.navBtnReached = false;
                    if (this.isOpen) {
                        this._closeSubLayer();
                    }
                    this.dom.button.focus();
                }
            }
        } else if (keyCode == 32) {
            WebSquare.event.preventDefault(e);
            if (target === this.dom.confirmBtn) {
                if (this.itemTable.selectedCell !== null) {
                    this.itemTable.selectedCell = null;
                }
                this.dom.confirmBtn.click();
                this.navBtnReached = false;
                this.dom.button.focus();
            } else if (target === this.dom.cancelBtn) {
                if (this.itemTable.selectedCell !== null) {
                    this.itemTable.selectedCell = null;
                }
                this.dom.cancelBtn.click();
            } else {
                if (this.itemTable.options.checkbox && !this.itemTable._getCellDisabled(newIndex) && selectedIndex >= 0) {
                    var checkbox = document.getElementById(this.itemTable.id + "_" + selectedIndex + "_checkbox");
                    checkbox.click();
                }
            }
        } else if (keyCode == 13) {
            if (target === this.itemTable.selectedCell) {
                WebSquare.event.preventDefault(e);
                this.itemTable.endReached = true;
            }
        }
        if (this.itemTable.endReached === true) {
            this.removeClass(this.itemTable.selectedCell, this.itemTable.options.w2table_col_over);
            this.itemTable.selectedCell = null;
            if (this.isOpen) {
                this._closeSubLayer();
            }
            this.itemTable.endReached = null;
            this.render.focus();
        }
    } catch (e) {
        WebSquare.exception.printStackTrace(e, null, this);
    }
};
