                col_id = colIndex;
            }
            var realRowIndex;
            if (this._linkedDataList) {
                realRowIndex = this._linkedDataList.filteredRowIndexArr[rowIndex];
            } else if (this.groupbyStatus.grouped) {
                var flag1 = true;
                for (var key in this._grid.customFilterStatusObj) {
                    if (this._grid.customFilterStatusObj[key]) {
                        realRowIndex = this._dataList.filteredRowIndexArr[rowIndex];
                        flag1 = false;
                        break;
                    }
                }
                if (flag1) {
                    realRowIndex = this.groupbyStatus.groupedRowIndexArr[rowIndex];
                }
            } else {
                realRowIndex = this._dataList.filteredRowIndexArr[rowIndex];
            }
            var cellInfo = this.cellInfoHash[col_id] || {
                "options": {}
            };
            if (cellInfo.options.inputType == "custom") {
                cellInfo = cellInfo.cellManagerHashByRowIndex[realRowIndex] ? cellInfo.cellManagerHashByRowIndex[realRowIndex] : cellInfo;
            }
            if (this.options.adaptive == "crosstab" && this.hasClass("w2grid_adaptive_crosstab") && cellInfo.options.hidden == "true") {
                return;
            }
            //===== end === 

            var initStyleObj = this.initStyleValueObj[col_index];
            if (initStyleObj != null) {
                styleArr.push(this.initStyleValueObj[col_index]["style"]);
            }

            if (cellInfo.options.textAlign != "") {
                styleArr.push("text-align:" + cellInfo.options.textAlign);
