            }

            var defaultStyleObj = this.defaultStyleValueObj[col_index];
            if (defaultStyleObj != null) {
                styleArr.push(this.defaultStyleValueObj[col_index]["style"]);
            }

            var rowStyleClassName = null;
            var rowStyleFixedClassName = null;
            var rowStyleDataClassName = null;
            var cellStyleClassName = null;
            var cellClassName = null;
            var isCellInFixed = false;
            if (rowIndex < this.options.fixedRow
                || col_index < this.options.fixedColumn
                || col_index >= this.tdIdList.length - this.options.fixedRightColumn) {

                isCellInFixed = true;
            }

            if (realRowIndex != null) {
                rowStyleClassName = (typeof realRowIndex == "number") ? this.rowStyleArr[realRowIndex] : this.rowStyleArr[realRowIndex.type + "_" + realRowIndex.groupId];
                rowStyleFixedClassName = (typeof realRowIndex == "number") ? this.rowStyleFixedArr[realRowIndex] : this.rowStyleFixedArr[realRowIndex.type + "_" + realRowIndex.groupId];
                rowStyleDataClassName = (typeof realRowIndex == "number") ? this.rowStyleDataArr[realRowIndex] : this.rowStyleDataArr[realRowIndex.type + "_" + realRowIndex.groupId];
                cellStyleClassName = (typeof realRowIndex == "number") ? this.cellStyleArr[realRowIndex * this.oneRowDataLength + col_index] : this.cellStyleArr[realRowIndex.type + "_" + realRowIndex.groupId + "_" + col_index];
                cellClassName = this.cellClassArr[realRowIndex * this.oneRowDataLength + col_index];
            } else {
                cellClassName = this.cellClassArr[rowIndex * this.oneRowDataLength + col_index];
            }

            if (rowStyleClassName != null) {
                styleArr.push(this.rowStyleValueObj[rowStyleClassName]["style"]);
            }
            if (rowStyleFixedClassName != null && isCellInFixed) {
                styleArr.push(this.rowStyleFixedValueObj[rowStyleFixedClassName]["style"]);
            }
            if (rowStyleDataClassName != null && !isCellInFixed) {
                styleArr.push(this.rowStyleDataValueObj[rowStyleDataClassName]["style"]);
            }

            var columnStyleObj = this.columnStyleValueObj[col_index];
            var columnStyleFixedObj = this.columnStyleFixedValueObj[col_index];
            var columnStyleDataObj = this.columnStyleDataValueObj[col_index];
            if (columnStyleObj != null) {
                styleArr.push(this.columnStyleValueObj[col_index]["style"]);
            }
            if (columnStyleFixedObj != null && isCellInFixed) {
                styleArr.push(this.columnStyleFixedValueObj[col_index]["style"]);
            }
            if (columnStyleDataObj != null && !isCellInFixed) {
                styleArr.push(this.columnStyleDataValueObj[col_index]["style"]);
            }
            var adaptiveColumnStyleObj = this.adaptiveColumnStyleValueObj[col_index];
            if (adaptiveColumnStyleObj != null && this.checkRefreshAdaptive() === true) {
                styleArr.push(this.adaptiveColumnStyleValueObj[col_index]["style"]);
