            var _readOnly = this.___getEditReadOnly(rowIndex, colIndex);
            if (this.options.readOnlyBackgroundColor != "" && typeof realRowIndex == "number") { // [WPF-1234] groupby header, footer 일 경우에는 readOnlyBackgroundColor를 무시한다.
