            if (this.options.readOnlyBackgroundImg != "" || this.options.readOnlyBackgroundImgCSS != "") {
                if (_readOnly == true) {
                    styleArr.push(this.readOnlyTdImg);
                    if (!this.options.readOnlyBackgroundImgCSS) {
                        if (WebSquare.util.isIE(8) || WebSquare.util.isIE(6) || WebSquare.util.isIE(7)) {
                            styleArr.push('filter: "progid:DXImageTransform.Microsoft.AlphaImageLoader(enabled=\'true\', src=\'' + this.options.readOnlyBackgroundImg + '\', sizingMethod=\'scale\')"');
                            styleArr.push('-ms-filter: "progid:DXImageTransform.Microsoft.AlphaImageLoader(enabled=\'true\', src=\'' + this.options.readOnlyBackgroundImg + '\', sizingMethod=\'scale\')"');
                        }
                    }
                    td.readOnly = true;
                    if (this.options.focusFlow === "linear" && this.options.readOnlyTabIgnore === true && !cellInfo.options.embeddedInput) {
                        td.setAttribute("tabIndex", -1);
                    }
                } else {
                    td.readOnly = false;
                    if (this.options.focusFlow === "linear" && this.options.readOnlyTabIgnore === true && !cellInfo.options.embeddedInput) {
                        td.setAttribute("tabIndex", 0);
                    }
