            }

            td.disabled = false;
            td.removeAttribute("disabled");

            var _isDisabled = this.cellDisabledArr[realRowIndex * this.oneRowDataLength + col_index];
            var cellDisabled = _isDisabled;
            if (_isDisabled !== true && _isDisabled !== false) {
                var columnDisabled = cellInfo.options.disabled;
                var rowDisabled = this.rowDisabledArr[realRowIndex];
                var disabledPriority = this.options.disabledPriority;
                if (rowDisabled !== true && rowDisabled !== false) {
                    rowDisabled = "";
                }

                if (disabledPriority === "column" && columnDisabled !== "") {
                    _isDisabled = columnDisabled;
                } else if (disabledPriority === "row" && rowDisabled !== "") {
                    _isDisabled = rowDisabled;
                } else if (columnDisabled + "" === "true" || rowDisabled + "" === "true") {
                    _isDisabled = true;
                } else if (columnDisabled + "" === "false" || rowDisabled + "" === "false") {
                    _isDisabled = false;
                } else if (this.options.disabled !== "") {
                    _isDisabled = this.options.disabled;
                } else {
                    _isDisabled = false;
                }
            }

            if (_isDisabled === true || _isDisabled === "true") {
                styleArr.push(this.disabledTdStyle);

                if (this.disabledCellStyleObj && this.disabledCellStyleObj[rowIndex + "_" + colIndex] && this.disabledCellStyleObj[rowIndex + "_" + colIndex]["style"]) {
                    styleArr.push(this.disabledCellStyleObj[rowIndex + "_" + colIndex]["style"]);
                }
            }

            var focusMode = this.options.focusMode;
            if (ignoreFocusMode) {
                focusMode = "cell";
            }
            if (!removedFocusedCell && this.options.selectedRowColor != "transparent") {
                if (focusMode == "row" || focusMode == "both") {
                    for (var j = 0; j < this.focusedCell.length; j++) {
                        if (rowIndex == this.focusedCell[j].focusedRowIndex) {
                            if (!(this.options.focusMode == "row" && this.options.fixedColumnNoBGColor == true && colIndex < this.options.fixedColumn)) {
                                styleArr.push("background-color:" + this.options.selectedRowColor);
                                isFocusedCell = true;
                                break;
                            }
                        }
                    }
                }
            }

            if (!removedFocusedCell && this.options.selectedCellColor != "transparent") {
                if (focusMode == "cell" || focusMode == "both") {
                    for (var j = 0; j < this.focusedCell.length; j++) {
                        if (rowIndex == this.focusedCell[j].focusedRowIndex && colIndex == this.focusedCell[j].focusedColIndex) {
                            styleArr.push("background-color:" + this.options.selectedCellColor);
                            isFocusedCell = true;
                            break;
                        }
                    }
                }
            }

            if ((td.style.display == "none" && !(this.hiddenCellObj.length > 0)) 
                || this.hiddenCellObj[rowIndex + "_" + colIndex] === true ) {
                styleArr.push("display:none");
            }

            var bVisibleChanged = false;
            if (this.hiddenCellObj.length > 0) { 
                if (this.hiddenCellObj[rowIndex + "_" + colIndex] === true && td.style.display !== "none") {
                    bVisibleChanged = true;
                } else if (this.hiddenCellObj[rowIndex + "_" + colIndex] !== true && td.style.display === "none") {
                    bVisibleChanged = true;
                }
            }

            var styleStr = styleArr.join(";");
            var dataStyle_bak = WebSquare.util.getDataPrefix("style_bak");
            var dataColMerged = WebSquare.util.getDataPrefix("colMerged");
            var dataOr_bgColor = WebSquare.util.getDataPrefix("or_bgColor");

            var borderBottom_bak = td.style.borderBottomWidth;
            if (styleStr != td.getAttribute(dataStyle_bak) || this.groupbyStatus.grouped || bVisibleChanged) {
                td.style.cssText = styleStr;
            }
            var cellStyleValueObj = this.cellStyleValueObj[cellStyleClassName];
            if (cellStyleValueObj && cellStyleValueObj["background-repeat"]) {
                td.style.backgroundRepeat = cellStyleValueObj["background-repeat"];
            } else if (cellStyleValueObj && cellStyleValueObj["background-size"]) {
                td.style.backgroundSize = cellStyleValueObj["background-size"];
            } else if (cellStyleValueObj && cellStyleValueObj["background-position"]) {
                td.style.backgroundPosition = cellStyleValueObj["background-position"];
            }

            if (this.isColMerge && cellInfo.options.colMerge && !this.groupbyStatus.grouped) {
                td.setAttribute(dataColMerged, "0");
                var mergeCellBkStatus = this.drawColMergeCellData(trIndex, rowIndex, colIndex);
                if (this.options.senseReader && borderBottom_bak && borderBottom_bak.indexOf("px") != -1) {
                    td.style.borderBottomWidth = borderBottom_bak;
                }
                if (mergeCellBkStatus === "mergeCellBackgroundColor" && !isFocusedCell) {
                    var oldBkColor = this.getCellStyleValue(rowIndex - 1, col_id, "background-color", true)
                        || this.getColumnStyleValue(colIndex, "background-color");
                    var newBkColor;
                    var applyNewBkColor = true;
                    if (td.readOnly || this.__getEditReadOnly(td, rowIndex)) {

                        newBkColor = oldBkColor;

                        if (this.options.readOnlyBackgroundColor) {
                            newBkColor = this.options.readOnlyBackgroundColor;
                        } else if (cellInfo.options.readOnlyClass || this.options.readOnlyClass) {
                            applyNewBkColor = false;
                        }

                    } else {
                        if (oldBkColor != "") {
                            newBkColor = oldBkColor;
                        } else {
                            if (rowIndex % 2) {
                                newBkColor = this.options.oddRowBackgroundColor;
                            } else {
                                newBkColor = this.options.evenRowBackgroundColor;
                            }
                        }
                        if (this.options.disabledClass && (_isDisabled === true || _isDisabled === "true")) {
                            applyNewBkColor = false;
