                            this.removeClass(td, cellInfo.options.readOnlyClass);
                        }
                    }
                    if (this.options.readOnlyClass != "") {
                        if (this.__getEditReadOnly(td, rowIndex)) {
                            this.addClass(td, this.options.readOnlyClass);
                        } else {
                            this.removeClass(td, this.options.readOnlyClass);
                        }
                    }
                }
            }

            td.setAttribute(dataStyle_bak, styleStr);
            td.setAttribute(dataOr_bgColor, td.style.backgroundColor);

            var dataReadonly = WebSquare.util.getDataPrefix("readonly");
            if (this.cellReadOnlyArr[realRowIndex * this.oneRowDataLength + colIndex] || _readOnly) {
                td.setAttribute(dataReadonly, "true");
                if (this.options.senseReader && !cellInfo.options.embeddedInput) {
                    if (this.options.focusFlow === "linear") {
                        if (cellInfo.options.inputType != "button") {
                        td.setAttribute("tabIndex", -1);
                        }
                    }
                } else {
                    if (this.options.focusFlow === "linear" && this.options.readOnlyTabIgnore === true && !cellInfo.options.embeddedInput) {
                        td.setAttribute("tabIndex", -1);
                    }
                }
            } else if (this.cellReadOnlyArr[realRowIndex * this.oneRowDataLength + colIndex] === false || _readOnly === false) {
                td.setAttribute(dataReadonly, "false");
                if (this.options.senseReader && !cellInfo.options.embeddedInput) {
                    if (this.options.focusFlow === "linear") {
                        td.setAttribute("tabIndex", 0);
                    }
                } else {
                    if (this.options.focusFlow === "linear" && this.options.readOnlyTabIgnore === true && !cellInfo.options.embeddedInput) {
                        td.setAttribute("tabIndex", 0);
                    }
                }
            } else {
                td.removeAttribute(dataReadonly);
            }

            if (cellClassName != null) {
                var index = trIndex * this.oneRowDataLength + colIndex;
                if (this.tdCellClassArr[index] && (this.tdCellClassArr[index] != cellClassName)) {
                    this.removeClass(td, this.tdCellClassArr[index]);
