                } else {
                    this.removeClass(td, cellInfo.options.disabledClass);
                }
            }
            if (cellDisabled === true || cellDisabled === "true") {
                if (this.options.disabledClass != "") {
                    this.addClass(td, this.options.disabledClass);
                } else {
                    this.removeClass(td, this.options.disabledClass);
                }
            }
            if (this.options.hiddenClass != "" || cellInfo.options.hiddenClass != "") {
                var hiddenClass = this.options.hiddenClass;
                if (cellInfo.options.hiddenClass != "") {
                    hiddenClass = cellInfo.options.hiddenClass;
                }
                var tdColIndex = this._getRealColIndex("body", cellInfo.options.col_id) + this.defaultColCnt;
