// WESD_1793 -gridView custom 캘린더 사용시 column에 붙은 class가 캘린더에도 적용되는 현상 수정
// 2021.11.22
WebSquare.uiplugin.gridView.prototype._setCellInputType = function(filteredRowIndex, colID, data, info) {
  try {
      if (data === null || data === undefined) {
          data = "";
      }
      if (this.editedCell != null && !this.getCellOption(filteredRowIndex, colID, "embeddedInput")) {
          this.editedCell.handleCancelEdit();
      }

      var maxRow = this._dataList.getTotalRow();
      if (this.groupbyStatus && this.groupbyStatus.grouped) {
          maxRow = this._dataList.filteredRowIndexArr.length;
      }
      var maxCol = this._dataList.getTotalCol();
      var realRowIndex;
      var isVisible = true;
      if ((this.options && this.options.pluginName === "grid" && this.isDrillDown && this.options.drilldownRealRowIndex)
          || (info && info.useRealRowIndex === true)
          ) {
          realRowIndex = filteredRowIndex;
      } else {
          realRowIndex = this.dataList.getRealRowIndex(filteredRowIndex);
      }

      var visibleRowIndex = this.getDisplayRowIndex(realRowIndex);
      if (isNaN(visibleRowIndex) || visibleRowIndex < 0) {
          isVisible = false;
      }

      var displayRowIndex = filteredRowIndex;
      var colID = this.getColumnID(colID);
      var colIndex = this.getColumnIndex(colID);
      var dColIndex = this._dataList.getColumnIndex(colID);

      if (filteredRowIndex >= 0 && filteredRowIndex < maxRow) {
          var cellInfo = this.cellInfoHash[this.tdIdList[colIndex]];
          var inputType = cellInfo.options.inputType;
          if (inputType == "custom" && !cellInfo.options.embeddedInput) {
              var trIndex;
              if (info.useRealRowIndex === true) {
                  trIndex = visibleRowIndex - (this.rowIndex > 0 ? this.rowIndex : 0);
              } else {
                  trIndex = filteredRowIndex - (this.rowIndex > 0 ? this.rowIndex : 0);
              }
              var td = this.data_td_list[colIndex + trIndex * this.oneRowDataLength];

              if (td && isVisible) {
                  var tempXMLArr = [];
                  var elem = null;
                  try {
                      var tempTd = td.cloneNode(true);
                      tempTd.setAttribute("xmlns:ev", "http://www.inswave.com/websquare"); 
                      tempTd.setAttribute("class", "");
                      WebSquare.xml._serialize(tempTd, tempXMLArr);
                      var tempElem = WebSquare.xml.parse(tempXMLArr.join("")).documentElement;
                      if (tempElem != undefined) {
                          tempElem.removeAttribute("xmlns:ev");
                          elem = tempElem;
                      } else {
                          elem = td;
                      }
                  } catch (e) {
                      elem = td;
                  }

                  var cellManager = cellInfo.getCellManager({
                      element: cellInfo.element,
                      rowIndex: displayRowIndex,
                      realRowIndex: realRowIndex,
                      options: info,
                      td: td,
                      dynamicInputType: true
                  });
                  if (cellManager === false) {
                      td.innerHTML = this.dataTagOpen + info.value + this.dataTagClose;
                  } else {
                      cellInfo.clearStyle(cellManager, td);

                      if (info.value == undefined || cellManager.existGridViewItemsetNode === true) { 
                          data = this.dataList._getCellData(displayRowIndex, colID);
                      } else {
                          data = info.value;
                          this.dataList.setCellData(displayRowIndex, colID, data, null, true, true);
                      }
                      if (this.isColMerge && cellInfo.options.colMerge && !this.groupbyStatus.grouped) {
                          this.setColMergeCellData(trIndex, displayRowIndex, colIndex);
                      } else {
                          if (cellManager.options.inputType === "calendar") {
                              if (info.options.className) {
                                  cellManager.element.setAttribute("class", info.options.className);
                              } else {
                                  cellManager.element.removeAttribute("class");
                              }
                          }
                          cellManager.setInnerHTML(td, data, displayRowIndex, colIndex);
                      }
                  }
              } else {
                  var cellManager = cellInfo.getCellManager({
                      element: cellInfo.element,
                      rowIndex: displayRowIndex,
                      realRowIndex: realRowIndex,
                      options: info,
                      dynamicInputType: true
                  });

                  if (cellManager) {
                      if (cellManager.customValue != undefined) {
                          data = cellManager.customValue;
                          this.dataList.setCellData(displayRowIndex, colID, data, null, true, true);
                      } else {
                          if (info.value == undefined || cellManager.existGridViewItemsetNode === true) {
                              data = this.dataList._getCellData(displayRowIndex, colID);
                          } else {
                              data = info.value;
                              this.dataList.setCellData(displayRowIndex, colID, data, null, true, true);
                          }
                      }
                  }
              }
          }
      }

  } catch (e) {
      WebSquare.exception.printStackTrace(e);
  }
};

/**
 * 
 * 11.25 일 핫픽스 오토컴플리트시 span 내용 동일 버그 발생
 */
/*
autoComplete span 태그가 보이는 현상 관련하여 textAlign 설정된 경우 재현
textAlign 속성 외에 emptyItem 속성 설정시, setDummyData함수 사용시에도 해당현상 발생되어 함께 처리되었습니다.

hotfix적용할 함수
WebSquare.uiplugin.autoComplete.prototype.setSelectedIndexNM
WebSquare.uiplugin.autoComplete.prototype.setDummyData
WebSquare.uiplugin.autoComplete.prototype.toHTML
WebSquare.uiplugin.autoComplete.prototype.setSubLayer
11.26
*/
WebSquare.uiplugin.autoComplete.prototype.setSelectedIndexNM = function(idx, allowInit) {
    try {
        this.dummyData = null;

        idx = parseInt(idx);
        if (isNaN(idx)) {
            return false;
        }
        if (this.options.emptyItem && (idx < 0 || idx >= this.getItemCount())) {
            this.selectedIndex = -1;
            this.dom.label.innerHTML = "";
            this.dom.input.value = "";
            if (this.itemTable) {
                this.itemTable.setSelectedIndex(0);
            }
            this.selectedItem = {
                text: "",
                value: "",
                orgLabel: ""
            };
            if (this.options.renderType != "input") {
                this.showEditMode(false);
            }
        } else {
            if (isNaN(idx) || idx >= this.getItemCount()) {
                return false;
            }

            if (idx < 0 && !allowInit) {
                return false;
            }

            this.selectedIndex = idx;

            if (idx > -1) {
                if (this.itemTableMode == "grid") {
                    if (this.gridOptions.dataComp) {
                        this.selectedGridRowObj = this.gridOptions.dataComp.getRowArray(idx);
                    } else {
                        this.selectedGridRowObj = this.gridRowItemArr[idx];
                    }
                } else if (this.itemTableMode == "gridView") {
                    if (this.gridViewOptions.dataComp) {
                        this.selectedGridViewRowObj = this.gridViewOptions.dataComp.getRowArray(idx);
                    }
                }

                var label = this.itemArr[idx].label;
                this._setLabel(idx);
                if (this.options.renderType != "input") {
                    this.dom.input.style.display = "none";
                    this.dom.input.style.visibility = "hidden";
                    this.dom.label.style.display = "block";
                    this.dom.label.style.visibility = "visible";
                    this.dom.input.value = label;
                }
                this.selectedItem = {
                    text: label,
                    value: this.itemArr[idx].value,
                    orgLabel: this.itemArr[idx].orgLabel
                };

                if (this.itemTable) {
                    if (this.options.renderType != "input") {
                        this.render.setAttribute("aria-activedescendant", this.itemTable.id + "_" + idx);
                    } else if (this.options.renderType == "input") {
                        this.dom.input.setAttribute("aria-activedescendant",this.itemTable.id + "_option" + ((idx*1)+1));
                    }
                }
            } else {
                if (idx == -1 && this.itemTableMode === "gridView" && this.options.selectedData === false && this.options.noResult === 'useData') {
                    if (this.itemTableMode == "gridView") {
                        if (this.gridViewOptions.dataComp) {
                            this.selectedGridViewRowObj = this.gridViewOptions.dataComp.getRowArray(idx);
                        }
                    }
                    this.dom.label.innerHTML = this._domInputValue;
                    this.dom.label.style.display = "block";
                    this.dom.label.style.visibility = "visible";

                    this.dom.input.value = this._domInputValue;

