WebSquare.util.getStringByByteSize = function(str, maxByteLength, ignoreChar, inputTextInfo) {
    if (!str) {
        return "";
    }
    var encoding = WebSquare.core.getConfiguration("/WebSquare/byteCheckEncoding/@value");
    if (!encoding) {
        encoding = "UTF-8";
    }
    encoding = encoding.toUpperCase();
    switch (encoding) {
        case "UTF-8":
            return WebSquare.util.getByteStringByLengthUtf8(str, maxByteLength, ignoreChar, inputTextInfo);
            break;
        default:
            return WebSquare.util.getByteStringByLength(str, maxByteLength, ignoreChar, inputTextInfo);
            break;
    }
