WebSquare.util.getByteStringByLength = function(str, maxByteLength, ignoreChar, inputTextInfo) {
    var byteLength = 0;
    var ignoreChar = ignoreChar || "";
    var ignoreCharArr = [];
    for (var s = 0; s < ignoreChar.length; s++) {
        ignoreCharArr.push(escape(ignoreChar.charAt(s)));
    }
    var lastValidIndex = 0;
    var lastValidByte = 0;
    for (var i = 0; i < str.length; i++) {
        var oneChar = escape(str.charAt(i));
        if (ignoreCharArr.length > 0) {
            var ignore = false;
            for (var j = 0; j < ignoreCharArr.length; j++) {
                if (oneChar === ignoreCharArr[j]) {
                    ignore = true;
                    break;
                }
            }
            if (ignore) {
                continue;
            }
        }
        var checkByteUnit = 0;
        if (oneChar.length == 1) {
            checkByteUnit = 1;
        } else if (oneChar.indexOf("%u") != -1) {
            checkByteUnit = 2;
        } else if (oneChar.indexOf("%") != -1) {
            checkByteUnit = oneChar.length / 3;
        }
        if (byteLength + checkByteUnit <= maxByteLength) {
            lastValidIndex = i;
            lastValidByte = byteLength;
        }
        byteLength += checkByteUnit;
        if (byteLength > maxByteLength) {
            if (inputTextInfo) {
                if (inputTextInfo.nowSelectionStart < str.length) {
                    return str.substring(0, inputTextInfo.prevSelectionStart) + 
                           str.substring(inputTextInfo.nowSelectionStart);
                }
                return str.substring(0, lastValidIndex + 1);
            }
            return str.substring(0, i);
        }
    }
    return str;
