        } else if (keyCode == 35) {
        } else if (keyCode == 36) {
        } else if (keyCode == 113) {
        } else if (keyCode == 9) {
            var ret = WebSquare.event.fireEvent(this, "oneditenter", e);
            this.tabOrderMoveStart = false;
            if (ret !== false) {
                if (e.shiftKey) {
                    if (WebSquare.tabOrder[this.id] != null && WebSquare.tabOrder[this.id]["preTabID"] != null) {
                        if (this.options.nextTabByKeyDown == "true") {
                            var tabObj = WebSquare.util.getPreTabbableComp(this.id);
                            if (tabObj) {
                                this.tabOrderMoveStart = false;
                                tabObj.focus(e);
