     * @param {String} cortCd - 조회하고자 하는 법원코드
     * 
     * @return {String} - 법원명
     * </pre>
     */
    var getCortNmExtnlJdbn = function(isInclude, cortCd) {
        var _self = this;
        if(scutilo.isEmpty(cortCd)) {
            return '';
        } else {
            if(isInclude || ! _self.isExtnlJdbn(cortCd)){ 
                return _self.getFullNm(cortCd);
            }

            return _self.getDscrtNm(cortCd);
        }
    };

    /*
