     * 
     * @memberOf sccorto
     * 
     * @example ex)
     * sccorto.getLowCortLstByStats('000510', true); --> 통계상급법원코드(stats) 기준 모든 산하 법원목록을 반환
     * sccorto.getLowCortLstByStats('000510', false); --> 통계상급법원코드(stats) 기준 바로 아래 산하 법원목록만 반환
     * 
     * @param {String} cortCd - 법원코드
     * @param {Boolean} isAllLow - 전체 하위법원 조회 여부 - true(하위의 하위 등 모든 하위까지 조회) / false(바로 아래 하위만 조회)
     * 
     * @return {Array} - 산하 법원 목록
     * </pre>
     */
    var getLowCortLstByStats = function(cortCd, isAllLow) {
        var _self = this;
        var result = null;
        com.executeAjax({
            action: scscrno.$_h._getSystmCtxtPathUrl('/scframe/lib/lowCorts/byStats.on'),
            requestData: JSON.stringify({
                cortCd: cortCd,
                isAllLow: isAllLow,
            }),
            mode: "synchronous",
            mediatype: gcm.DEFAULT_OPTIONS_MEDIATYPE,
            //target : 'data:json,[{"id":"dtl_cort","key":"data"}]',
            success: function(_data) {
                result = _data.responseJSON.data.list;
            },
        });
        return result;
    };

    /*
     * ============= ============ ==========================
     *  Date          Author       Description
     * ============= ============ ==========================
     *  2022.01.17.   백승우       [NELS]최초 생성
