     */
    /**
     * <pre>
     * 법원유형코드(cortTypCd)에 해당하는 법원 리스트를 웹스퀘어 컴포넌트에 바인딩한다.
     * 법원유형코드는 구분자없이 여러개 지정 가능하다.
     * 
     * @memberOf sccorto
     * 
     * @example ex)
     * sccorto.bindCortLstByTyp("sbx_cort20", "20");
     * sccorto.bindCortLstByTyp("sbx_cort50", "50");
     * sccorto.bindCortLstByTyp("sbx_cort50", "2050");   //20과 50
     * 
     * @param {String} compId - 웹스퀘어 컴포넌트ID
     * @param {String} cortTypCd - 검색할 법원유형코드
     * </pre>
     */
    var bindCortLstByTyp = function(compId, cortTypCd) {
        var aCortTypCds = [];
        for(var i=0; i<cortTypCd.length; i+=2) {
            aCortTypCds.push(cortTypCd.substr(i, 2));
        }
        var _self = this;
        var scopeId = $p.getFrameId();
        var dataLstId = scglblo.$_h._createDataLst.call(_self, {
            scopeId: scopeId,
            dataId: scglblo.$_h._getCortDataId() + "_" + compId,
            dataLstFieldInf: sccorto.$_h._getDataLst().cellIdList,
            getDataFunc: function() {
                return _self.getCortLst().filter(function(_o) {
                    return aCortTypCds.includes(_o.cortTypCd);
                });
            },
        });
        scglblo.$_h._bindComponentData({
            scopeId: scopeId,
            compId: compId,
            dataLstId: dataLstId,
            label: 'cortFullNm',
            value: 'cortCd',
        });
    };

    /*
     * ============= ============ ==========================
     *  Date          Author       Description
     * ============= ============ ==========================
     *  2022.01.17.   백승우       [NELS]최초 생성
     * ============= ============ ==========================
     */
    /**
