     * @param {String} cortAbrvtdNmYN - 법원약칭명 사용여부
     * @param {Boolean} isTest(Options) - 테스트 법원 포함여부
     * </pre>
     */
    var bindCortLst = function(compId, cortAbrvtdNmYN, isTest) {
        var _self = this;
        var scopeId = $p.getFrameId();
        var dataLstId = scglblo.$_h._createDataLst.call(_self, {
            scopeId: scopeId,
            dataId: scglblo.$_h._getCortDataId() + "_" + compId,
            dataLstFieldInf: sccorto.$_h._getDataLst().cellIdList,
            getDataFunc: _self.getCortLst.bind(_self, isTest),
        });
        var cortAbrvtdNmYN = scutilo.isNotEmpty(cortAbrvtdNmYN) ? cortAbrvtdNmYN : 'N';
        scglblo.$_h._bindComponentData({
            scopeId: scopeId,
            compId: compId,
            dataLstId: dataLstId,
            label: cortAbrvtdNmYN === 'Y' ? 'cortAbrvtdNm' : 'cortFullNm',
            value: 'cortCd',
        });
    };

    return {
        $_h: $_h,
        bindCortLst: bindCortLst,
        bindCortLstByTyp: bindCortLstByTyp,
        getBdcrtNm: getBdcrtNm,
        getCortAbrvtdNm: getCortAbrvtdNm,
