        getFullNm: getFullNm,
        getLowCortLstByStats: getLowCortLstByStats,
        getMccrtNm: getMccrtNm,
        isExtnlJdbn: isExtnlJdbn,
    };
} ();

/*
 * ============= ============ ==========================
