/**
 * <pre>
 * scjs scdateo - 날짜 공통 js
 * 
 * 휴일정보 관련 함수 사용 시 휴일정보 DataList를 생성 할 수 있도록 config.xml의 wframe > initScript 설정에 scscrno.init(); 를 작성해야한다.
 * </pre>
 * 
 * @constructor
 */
var scdateo = function() {
    /**
     * hidden 변수
     * 
     * @ignore
     */
    var $_h = {
        DELIMITER_DATE: ".",
        DELIMITER_TIME: ":",
        MINBUB161_DATE: "20080322",
        SC_MSG_W_204: "올바른 형식의 일자가 아닙니다.",

        _getHldyDayDataLst: function() {
            return scglblo.$_h._getMainDataClct(scglblo.$_h._getHldyDataId());
        },

        _getMainLodHldyDayLst: function() {
            var _self = scdateo;
            return _self.$_h._getHldyDayDataLst().getAllJSON();
        },

        /**
         * <pre>
         * 현재 wframe에 전역 휴일정보 데이터리스트를 복사한다.
         * </pre>
         */
        _copyHldyDataLst: function() {
            var _self = scdateo;

            _self.loadHldyLst();
            // 휴일 데이터 리스트가 없을때만 추가
            var hldyDataLst = $p.getComponentById(scglblo.$_h._getHldyDataId());
            if(! hldyDataLst) {
                // 탑 영역에 휴일 데이터리스트가 있을때만 실행
                if(scglblo.$_h._isExistsMainDataClct(scglblo.$_h._getHldyDataId())) {
                    scglblo.$_h._copySCMainDataList(_self.$_h._getHldyDayDataLst(), $p.getFrameId(), scglblo.$_h._getHldyDataId(), "Y");
                }
            }
        },

        /**
         * <pre>
         * 입력받은 일자를 YYYYMMDD 일자숫자로 변환한다.
         * 
         * @param {String} date - 날짜문자열 : YYMMDD, YYYYMMDD 혹은 YY.MM.DD, YYYY.MM.DD 포맷의 날짜
         * @param {boolean} isShowMsg - 메시지창출력여부 : true(메시지출력,default)/false(메시지미출력)
         * 
         * @return {String} - YYYYMMDD 일자
         * </pre>
         */
        _getDateNum: function(date, isShowMsg) {
            var _self = scdateo;

            var isShowMsgParam = (scutilo.isEmpty(isShowMsg)) ? true : isShowMsg;
            var date = scutilo.skipSpaces(date);
            var dateNum = "";
            for (var i=0; i<date.length;i++ ) {
                if ((date.charAt(i) >= "0") && (date.charAt(i) <= "9"))
                    dateNum = dateNum + date.charAt(i);
            }

            if (dateNum.length < 1) {
                if (isShowMsgParam) scutilo.showMsg(scglblo.MSG.WARN, scutilo.getHtmlBrTagStr(_self.$_h.SC_MSG_W_204));
                return "";
            }

            if ((dateNum.length != 6) && (dateNum.length != 8)) {
                if (isShowMsgParam) scutilo.showMsg(scglblo.MSG.WARN, scutilo.getHtmlBrTagStr(_self.$_h.SC_MSG_W_204, "<Sample> 2002.06.13"));
                return "";
            }

            if (dateNum.length == 6) {
                if (parseInt(dateNum.substr(0, 2), 10) >= 50 )
                    dateNum = "19" + dateNum;
                else
                    dateNum = "20" + dateNum;
            }
            return dateNum;
        },

        /**
         * <pre>
         * 해당 날짜에서 일수만큼 이후 공휴일이면 공휴일 지난 다음 날짜를 반환한다(토요일 제외).
         * 단, 결과일자가 토요일을 미포함하며, 공휴일인 경우 공휴일이 아닌 다음 날짜를 반환한다.
         * 
         * @param {String} date - 날짜문자열 : YYMMDD, YYYYMMDD 혹은 YY.MM.DD, YYYY.MM.DD 포맷의 날짜 
         * @param {Number} days - 며칠후 : 이후 날짜를 계산하기 위한 일수(> 0)
         * 
         * @return {String} - 결과 날짜
         * </pre>
         */
        _getNxtYmdSkipLastHldy: function(date, days) {
            var _self = scdateo;

            if (days == "0") return date;
            var dateStr = _self.getNxtYmd(date,days);
            if (dateStr == "") return "";
            while (_self.isHldy(dateStr) == true ){
              dateStr = _self.getNxtYmd(dateStr,1);
            }
            return dateStr;
        },

        /**
         * <pre>
         * 해당 날짜에서 일수만큼 공휴일이면 공휴일 이전 날짜를 반환한다(토요일 제외).
         * YYYYMMDD 포맷의 날짜를 반환한다.
         * 단, 결과일자가 토요일을 미포함하며, 공휴일인 경우 공휴일이 아닌 이전 날짜를 반환한다.
         * 
         * @param {String} date - 날짜문자열 : YYMMDD, YYYYMMDD 혹은 YY.MM.DD, YYYY.MM.DD 포맷의 날짜
         * @param {Number} days - 며칠전 : 이전 날짜를 계산하기 위한 일수(> 0)
         * 
         * @return {String} - 결과 날짜
         * </pre>
         */
        _getPrevYmdSkipLastHldy: function(date, days) {
            var _self = scdateo;

            if (days == "0") return date;
            var dateStr = _self.getPrevYmd(date,days);
            if (dateStr == "") return "";
            while (_self.isHldy(dateStr) == true ){
                dateStr = _self.getPrevYmd(dateStr,1);
            }
            return dateStr;
        },
    }

    /*
     * ============= ============ ==========================
     *  Date          Author       Description
     * ============= ============ ==========================
     *  2022.01.17.   백승우       [NELS]최초 생성
     * ============= ============ ==========================
     */
    /**
     * <pre>
     * 서버로부터 설정된 휴일 목록을 조회한다.
     * 
     * @memberOf scdateo
     * 
     * @example ex)
     * scdateo.loadHldyLst("000999");
     * scdateo.loadHldyLst();
