    /**
     * <pre>
     * 해당 날짜에서 월수만큼 이후의 날짜를 반환한다. YYYYMMDD 포맷의 날짜를 반환한다.
       단, 입력한 날짜의 일이 계산된 결과 월의 최대 일수를 넘는 경우는 결과 월의 최대 날짜로 변경하여 반환한다.
     * 
     * @memberOf scdateo
     * 
     * @example ex)
     * scdateo.getNxtMmYmd("20211023", 1);
     * scdateo.getNxtMmYmd("2021.10.23", 2);
     * scdateo.getNxtMmYmd("2021/10/23", 3);
     * scdateo.getNxtMmYmd("2021. 10. 23. ", 4);
     * 
     * @param {String} date - 날짜문자열 : YYMMDD, YYYYMMDD 혹은 YY.MM.DD, YYYY.MM.DD 포맷의 날짜
     * @param {Number} mms - 월수 : 이전(음수)/이후(양수) 달을 계산하기 위한 월수
     * 
     * @return {String} - 결과 날짜
     * </pre>
     */
    var getNxtMmYmd = function(date, mms) {
        var _self = this;

        var aMonDays = new Array("31","28","31","30","31","30","31","31","30","31","30","31");

        if ( mms == "0") return date;
        date = _self.$_h._getDateNum(date);
        if (date == "") return "";
        var dateObj = _self.getDateObj(date);

        var newYr = dateObj.getFullYear();
        var newMm = dateObj.getMonth() + 1 + parseInt(mms, 10);
        var newDay = dateObj.getDate();

        if (newMm > 12) {
          newYr = newYr + parseInt(newMm / 12, 10);
          newMm = parseInt(newMm % 12, 10);
        }

        if (newMm < 0) {
          newYr = newYr - ( 1 + parseInt( (newMm * -1) / 12, 10) );
          newMm = 12 -   parseInt( (newMm * -1) % 12, 10);
        }

        if ((newMm == 2) && ((((newYr % 4) == 0) && ((newYr % 100) != 0)) || ((newYr % 400) == 0))) {
          aMonDays[1] = "29";
        }

        if (newDay > aMonDays[newMm -1])
          newDay = parseInt(aMonDays[newMm -1], 10);

        dateObj.setFullYear(newYr, newMm-1, newDay);
        var dateStr = _self.getDateStr(dateObj);

        return dateStr;
    };

