    var getDateObj = function(dateStr) {
    	var _self = this;
    	var dateObj = new Date();

    	dateStr = _self.$_h._getDateNum(dateStr);
    	dateObj.setFullYear( parseInt(dateStr.substr(0,4), 10),
                           parseInt(dateStr.substr(4,2), 10)-1,
                           parseInt(dateStr.substr(6,2), 10) );
    	return dateObj;
    };

