        _createDataLst: function(_cfg) {
            var sc = scutilo.isString(_cfg.scopeId) ? $p.getComponentById(_cfg.scopeId) : _cfg.scopeId;
            if(! sc) {
                throw new Error("@@@ scglblo._createDataLst error - scopeId 값을 추가해주세요. _cfg-->", _cfg)
            }
            else {
                if(! _cfg.dataId) {
                    throw new Error("@@@ scglblo._createDataLst error - dataId 값을 추가해주세요. _cfg-->", _cfg);
                }
                else {
                    // 데이터 키 생성
                    var dataId = _cfg.dataId;

                    // dataLstId 값으로 dataList 찾기
                    var dataListObj = sc.scope.$p.getComponentById(dataId);
                    // dataList가 유효하면 dataList에 법원정보 바인딩
                    if(dataListObj) {

                    }
                    // dataList가 유효하지 않으면 생성
                    else {
                        // 법원 데이터 DataCollection 생성
                        var dataListOption = com._getCodeDataListOptions(_cfg.dataLstFieldInf);
                        // 데이터 키 생성
                        dataListOption.id = dataId;
                        // dataList 생성
                        sc.scope.$p.data.create(dataListOption);
                        // dataLstId 값으로 dataList 다시 찾기
                        dataListObj = sc.scope.$p.getComponentById(dataId);
                    }

                    var resultData = _cfg.getDataFunc();
                    dataListObj.setJSON(resultData);
                    return dataListObj.id;
                }
            }
        },

        /**
         * <pre>
         * scjs 용 웹스퀘어 컴포넌트에 바인딩 공통용 함수
         * </pre>
         */
        _bindComponentData: function(_cfg) {
            var _self = scglblo;
            var sc = $p.getComponentById(_cfg.scopeId);
            if(! sc) {
                throw new Error("@@@ scglblo.$_h._bindComponentData error - scopeId 값을 추가해주세요. _cfg-->", _cfg)
            }
            else {
                if(! _cfg.compId) {
                    throw new Error("@@@ scglblo.$_h._bindComponentData error - compId 값을 추가해주세요. _cfg-->", _cfg);
                }
                else {
                    var compArr = (_cfg.compId).replaceAll(" ", "").split(",");
                    for (var i = 0; i < compArr.length; i++) {
                        //컴포넌트 ID
                        var aTmpCompId = compArr[i].split(':');
                        var tmpCompId = aTmpCompId[0];
                        var tmpColId = aTmpCompId.length > 1 ? aTmpCompId[1] : null;
                        var comp = sc.scope.$p.getComponentById(tmpCompId);
                        if(comp) {
                            var compType = comp.getPluginName();
                            //그리드
                            if(compType === 'gridView') {
                                //setColumnNodeSet( colIndex , nodeset , label , value )
                                comp.setColumnNodeSet(tmpColId, "data:" + _cfg.dataLstId, _cfg.label, _cfg.value);
                            }
                            //그리드 외 컴포넌트
                            else {
                                //setNodeSet( nodeset , label , value )
                                comp.setNodeSet("data:" + _cfg.dataLstId, _cfg.label, _cfg.value);
                            }
                        } else {
                            throw new Error("@@@ scglblo.$_h._bindComponentData error - 컴포넌트를 찾을수 없습니다. _cfg-->", _cfg);
                        }
                    }
                }
            }
        },

