        _copySCMainDataList: function(descDataList, scopeFrameId, newId, dataCopyYn) {
            var descId = "";

            if ( typeof descDataList  === "string" ) descId = descDataList;
            else descId = descDataList.id;

            var dataCollection = scutilo.getSCMain().$p.top().$p.getComponentById(descId);
            var dataType = dataCollection.getObjectType().toLowerCase();
            if (dataType !== "datalist") return;

            var info = dataCollection.getInfo();
            var columnInfo = info.columnInfo;

            var makeColumnInfo = [];
            Object.keys(columnInfo).forEach(function(key) {
                makeColumnInfo.push(columnInfo[key]);
            })

            var option = { 
                     "type":"dataList", 
                     "option":{ 
                         "baseNode":"list" ,
                         "repeatNode":"map"
                     }};
            option.id = newId;
            option.columnInfo = makeColumnInfo;

            var copyScope = $p.getComponentById(scopeFrameId).scope;
            copyScope.$p.data.create( option );

            if ( dataCopyYn == "Y" ) {
                var dataListObj = copyScope.$p.getComponentById(newId);
                if ( dataListObj != null ) dataListObj.setJSON(descDataList.getAllJSON());
            }
        },

