            sRtnStr = psSeed + sRtnStr;
        return sRtnStr;
    };
    
    /*
     * ============= ============ ==========================
     *  Date          Author       Description
     * ============= ============ ==========================
     *  2022.01.17.   백승우       [NELS]최초 생성
     * ============= ============ ==========================
     */
    /**
     * <pre>
     * 전달된 문자열(psStr)이 사용자가 지정한 길이보다 짧은 경우 오른쪽을 전달된 문자(psSeed)로 채워서 반환한다.
     * 단, 문자열(psStr)이 리턴할 문자열의 길이(piLen) 보다 긴 경우에는 받은 그대로를 반환한다
     * 
     * @memberOf scutilo
     * 
     * @example ex)
     * scutilo.getRPadding("한글정보", 13, " "); -> "한글정보 "
     * scutilo.getRPadding("한글정보", 13, "**"); -> "한글정보" <-- 처리안됨
     * scutilo.getRPadding("한글정보입니다", 13, " "); -> "한글정보입니다"  <-- 전달된 문자열이 반환될 길이보다 긴 경우
     * 
     * @param {String} psStr - padding할 문자열
     * @param {Number} piLen - 리턴할 문자열의 길이(Byte)
     * @param {String} psSeed - 전달된 문자열(psStr)이 리턴할 길이(piLen)보다 짧을 경우 오른쪽에 보충할 문자
     * 
     * @return {String} - 결과 문자열
     * </pre>
     */
    var getRPadding = function(psStr, piLen, psSeed) {
        var sRtnStr = String(psStr);
        psSeed = String(psSeed);
        if (this.getByteLen(psSeed) != 1)
            return sRtnStr;
        for (var i = 0; i < (piLen - this.getByteLen(psStr)); i++)
            sRtnStr = sRtnStr + psSeed;
        return sRtnStr;
    };
    
    /*
     * ============= ============ ==========================
     *  Date          Author       Description
     * ============= ============ ==========================
     *  2022.01.17.   백승우       [NELS]최초 생성
     * ============= ============ ==========================
     */
    /**
     * <pre>
     * 전달된 문자열의 Byte 길이를 반환한다.
     * 
     * @memberOf scutilo
     * 
     * @example ex)
     * scutilo.getByteLen("정상한글"); -> 12을 반환
     * 
     * @param {String} str - 길이를 구할 문자열
     * 
     * @return {Number} - byte 길이
     * </pre>
     */
    //var getByteLen = function(s,b,i,c) {
    var getByteLen = function(s) {
        s = String(s);
        var b, i, c;
        // 한글 2byte 계산
        //for (b = i = 0; c = s.charCodeAt(i++); b += c >> 11 ? 2 : c >> 7 ? 2 : 1);
        // 한글 3byte 계산
        for (b = i = 0; c = s.charCodeAt(i++); b += c >> 11 ? 3 : c >> 7 ? 2 : 1);
        return b;
    };
    
    /*
     * ============= ============ ==========================
     *  Date          Author       Description
     * ============= ============ ==========================
     *  2022.01.17.   백승우       [NELS]최초 생성
     * ============= ============ ==========================
     */
    /**
     * <pre>
     * 전달된 문자열(str)의 길이와 사용자가 지정한 최대 길이(limit)를 비교하여 그 결과를 반환한다.
     * 
     * @memberOf scutilo
     * 
     * @example ex)
     * scutilo.isValidStrLen('test', 4); -> true
     * scutilo.isValidStrLen('test', 3); -> false
     * scutilo.isValidStrLen('가', 3); -> true
     * scutilo.isValidStrLen('가1', 3); -> false
     * 
     * @param {String} str - 작업대상 문자열
     * @param {Number} limit - maxlength
     * 
     * @return {Boolean} - 문자열 최대 길이 검증 결과
     * </pre>
     */
    var isValidStrLen = function(str, limit) {
        if (this.getByteLen(str) > limit)
            return false;
        else
            return true;
    };

    /*
     * ============= ============ ==========================
     *  Date          Author       Description
     * ============= ============ ==========================
     *  2022.01.17.   백승우       [NELS]최초 생성
     * ============= ============ ==========================
     */
    /**
     * <pre>
     * 사건번호등의 경우 전체 사건번호에서 연번을 추출한 후, input text에 값을 할당할 경우 앞 부분의 "0" 를 제거하고 표현해 주어야 한다. 이런 경우 이 함수를 사용한다.
     * 
     * @memberOf scutilo
     * 
     * @example ex)
     * scutilo.skipZero('000001234567890') -> 1234567890
     * 
     * @param {String} str - 작업대상 문자열
     * 
     * @return {String} - 결과 문자열
     * </pre>
     */
    var skipZero = function(str) {
        var pos = 0;
        str = String(str);
        for (var i = 0; i < str.length; i++) {
            if (str.charAt(i) != "0") {
                pos = i;
                break
            }
        }
        return str.substr(pos, str.length);
    };

    /*
     * ============= ============ ==========================
     *  Date          Author       Description
     * ============= ============ ==========================
     *  2022.01.17.   백승우       [NELS]최초 생성
     * ============= ============ ==========================
     */
    /**
     * <pre>
     * 출력등의 경우에 이름등을 공백없이 출력하는 것이 아니라 공백을 두고 출력하기 위해 사용하는 함수이다.
     * 
     * @memberOf scutilo
     * 
     * @example ex)
     * scutilo.getNmCenter("가나다", 10) <-- 처리안됨
     * scutilo.getNmCenter("가나다", 12) --> "가 나 다" <-- 11자리로 처리됨
     * 
     * @param {String} psStr - 작업대상 문자열
     * @param {Number} piByte - 조정할 길이 (기본: 18)
     * 
     * @return {String} - 결과 문자열
     * </pre>
     */
    var getNmCenter = function(psStr, piByte) {
        var sSpace = "";
        var sResult = "";
        var iSpace = 0;

        psStr = this.skipSpaces(psStr);
        if (String(piByte) == "undefined")
            piByte = 18;
        if (psStr.length == 1)
            return psStr;
        iSpace = parseInt((parseInt(piByte, 10) - this.getByteLen(psStr))
                / (psStr.length - 1), 10);
        if (iSpace <= 0)
            return psStr;

        sSpace = this.getLPadding(sSpace, iSpace, " ");
        for (var i = 0; i < psStr.length; i++)
            sResult += psStr.charAt(i) + sSpace;

        sResult = this.getAllTrim(sResult);
        if ((this.getByteLen(sResult) == piByte - 1) && (psStr.length % 2 == 0))
            sResult = sResult.substr(0, parseInt(sResult.length / 2, 10))
                    + " "
                    + sResult.substr(parseInt(sResult.length / 2, 10),
                            sResult.length);
        return sResult;
    };

    /*
     * ============= ============ ==========================
     *  Date          Author       Description
     * ============= ============ ==========================
     *  2022.01.17.   백승우       [NELS]최초 생성
     * ============= ============ ==========================
     */
    /**
     * <pre>
     * 입력받은 문자열의 숫자여부를 반환한다.
     * 
     * @memberOf scutilo
     * 
     * @example ex)
     * scutilo.isNumber("0123456789") --> true
     * scutilo.isNumber("012345678 9") --> false
     * scutilo.isNumber("aa") --> false
     * 
     * @param {String} str - 숫자 여부를 확인할 객체
     * 
     * @return {Boolean} - 숫자여부
     * </pre>
     */
    var isNumber = function(str) {
        fmt = /^\d+\d*$/;
        return fmt.test(str);
    };

    /*
     * ============= ============ ==========================
     *  Date          Author       Description
     * ============= ============ ==========================
     *  2022.01.17.   백승우       [NELS]최초 생성
     * ============= ============ ==========================
     */
    /**
     * <pre>
     * 입력된 수를 금액형태로 변환한다. 즉, 콤마(,)를 추가한다.
     * 
     * @memberOf scutilo
     * 
     * @example ex)
     * scutilo.getCommaFmt("123456789") --> 123,456,789
     * scutilo.getCommaFmt("-123456789") --> -123,456,789
     * scutilo.getCommaFmt("1400000") --> 1,400,000
     * 
     * @param {String} num - 수 : 변환할 수
     * 
     * @return {String} - 결과 문자열
     * </pre>
     */
    var getCommaFmt = function(num) {
        var currency = '';        
        num = parseInt(this.skipZero(num), 10);
        var str = String(Math.abs(num));
        while (str.substr(str.length - 3, 3).length == 3) {
            currency = ',' + str.substr(str.length - 3, 3) + currency;
            str = str.substr(0, str.length - 3);
        }
        if (str.length == 0)
            currency = currency.substr(1, currency.length);
        else
            currency = str + currency;
        if (num<0)  currency = '-' + currency;
        return currency;
    };

    /*
     * ============= ============ ==========================
     *  Date          Author       Description
     * ============= ============ ==========================
     *  2022.01.17.   백승우       [NELS]최초 생성
     * ============= ============ ==========================
     */
    /**
     * <pre>
     * 입력된 금액을 일반 숫자 형태로 변환한다. 즉, 콤마(,)를 제외시킨다.
     * 
     * @memberOf scutilo
     * 
     * @example ex)
     * scutilo.getPlainFmt("123,456,789") --> 123456789
     * scutilo.getPlainFmt("1,400,000") --> 1400000
     * 
     * @param {String} currency - 금액 : 변환할 금액
     * 
     * @return {String} - 결과 문자열
     * </pre>
     */
    var getPlainFmt = function(currency) {
        var num = '';
        var i = 0;
        currency = this.skipZero(currency);
        while ((currency.length - 4 * ++i) > 0) {
            if (currency.substr(currency.length - 4 * i, 1) != ",") {
            	scutilo.showMsg(scglblo.MSG.WARN, "잘못된 인수입니다.");
                return 0;
            }
            num = currency.substr((currency.length - 4 * i) + 1, 3) + num;
        }
        num = currency.substr(0, currency.length - num.length - i + 1) + num;
        return parseInt(num, 10);
    };
    
    /*
     * ============= ============ ==========================
     *  Date          Author       Description
     * ============= ============ ==========================
     *  2022.01.17.   백승우       [NELS]최초 생성
     * ============= ============ ==========================
     */
    /**
     * <pre>
     * Encoding된 문자열에서 공백에 해당하는 "%20"을 공백으로 재변환한다.
     * 
     * @memberOf scutilo
     * 
     * @example ex)
     * scutilo.getEncodeToBlnk('TEST (%20가나')
     * 
     * @param {String} str - 문자열 : Decoding할 문자열
     * 
     * @return {String} - 결과 문자열
     * </pre>
     */
    var getEncodeToBlnk = function(str) {
        var rtnStr = '';
        while (str.indexOf("%20") > -1) {
            iPos = str.indexOf("%20");
            rtnStr = rtnStr + str.substr(0, iPos) + " ";
            str = str.substr(iPos + 3);
        }
        if (str != "")
            rtnStr = rtnStr + str;
        if (rtnStr.charAt(0) == '"')
            rtnStr = rtnStr.substr(1);
        if (rtnStr.charAt(rtnStr.length - 1) == '"')
            rtnStr = rtnStr.substr(0, rtnStr.length - 1);
        return rtnStr;
    };

    /*
     * ============= ============ ==========================
     *  Date          Author       Description
     * ============= ============ ==========================
     *  2022.01.17.   백승우       [NELS]최초 생성
     * ============= ============ ==========================
     */
    /**
     * <pre>
     * 보안차원에서 자바 스크립트를 제한 할 경우 꺽쇠 문자가 차단되므로 사전에 꺽쇠문자를 변환하는 기능을 제공한다.
     * "<" 또는 ">" 문자를 "&amplt;" 또는 "&ampgt;"로 변환
     * 
     * @memberOf scutilo
     * 
     * @example ex)
     * scutilo.getTagExclStr('TEST <가나>')
     * 
     * @param {String} text - 변경대상 텍스트
     * 
     * @return {String} - 결과 문자열
     * </pre>
     */
    var getTagExclStr = function(text) {
        var reValue = text;
        reValue = reValue.replace(/\</g, "&lt;");
        reValue = reValue.replace(/\>/g, "&gt;");
        return reValue;
    };
    
    /*
     * ============= ============ ==========================
     *  Date          Author       Description
     * ============= ============ ==========================
     *  2022.01.17.   백승우       [NELS]최초 생성
     * ============= ============ ==========================
     */
    /**
     * <pre>
     * 인자로 전달받은 데이터의 비어있는("", null, undefined 체크) 상태여부를 반환한다.
     * 
     * @memberOf scutilo
     * 
     * @example ex)
     * scutilo.isEmpty('가나다')
     * scutilo.isEmpty(null)
     * scutilo.isEmpty(undefined)
     * scutilo.isEmpty(0)
     * scutilo.isEmpty(1)
     * 
     * @param {String}  str - 문자열
     * 
     * @return {Boolean} - 빈 문자열 여부
     * </pre>
     */
    var isEmpty = function(str) {
        if(str === null || str === undefined) {
            return true;
        }
        else if(this.isJson(str)) {
            return Object.keys(str).length === 0;
        }
        else if(this.isArray(str)) {
            return str.length === 0;
        }
        // 숫자 0의 경우 빈값으로 인지되기 때문에 분기처리
        else {
            str = String(str);
            return str ? false : true;
        }
    };
    
    /*
     * ============= ============ ==========================
     *  Date          Author       Description
     * ============= ============ ==========================
     *  2022.01.17.   백승우       [NELS]최초 생성
     * ============= ============ ==========================
     */
    /**
     * <pre>
     * 인자로 전달받은 데이터의 비어있지않은("", null, undefined 체크) 상태여부를 반환한다.
     * 
     * @memberOf scutilo
     * 
     * @example ex)
     * scutilo.isNotEmpty('가나다')
     * scutilo.isNotEmpty(null)
     * scutilo.isNotEmpty(undefined)
     * scutilo.isNotEmpty(0)
     * scutilo.isNotEmpty(1)
     * 
     * @param {String}  str - 문자열
     * 
     * @return {Boolean} - 비어있지 않은 문자열 여부
     * </pre>
     */
    var isNotEmpty = function(str) {
        return ! this.isEmpty(str);
    };
    
    /*
     * ============= ============ ==========================
     *  Date          Author       Description
     * ============= ============ ==========================
     *  2022.01.17.   백승우       [NELS]최초 생성
