     * scutilo.bindCmpnt('acp_cortSelect3', sccdo.getIntgCdLst('CORT_TYP_CD'), scglblo.CMPNT_ITEMSET.SCCDO);
     * scutilo.bindCmpnt('acp_cortSelect3', scjdbn.getJdbnLst(scglblo.JDBN_SYSTM_TYP.NORMAL, true, "", scglblo.JDBN_TYP.NORMAL), scglblo.CMPNT_ITEMSET.SCJDBN);
