    /**
     * <pre>
     * 입력한 대체 정렬 컬럼 기준으로 원본 컬럼을 정렬한다.
     *
     * @memberOf scutilo
     * 
     * @example  
     * scutilo.sortGrid(gridView , "userCsNo", "csNo");
     * 
     * @param {Object} grdObj - 웹스퀘어 gridView ID
     * @param {String} originSortCol - 원본 정렬 컬럼
     * @param {String} replaceSortCol - 대체 정렬 컬럼 
     * 
     * </pre>
     */
    var sortGrid = function(grdObj, originSortCol, replaceSortCol) {
        
        if(com.util.isEmpty(grdObj)) return;
        if(grdObj.getPluginName() !== "gridView") return;
        
        var dataList = $p.getComponentById(grdObj.getDataList());
        var sortStatus = grdObj.getSortableStatus();
//        console.log("scutilo sortStatus :: ", sortStatus);
        //sort 구분자 space 
        var delim = " ";
        var strSortOrder = replaceSortCol + delim + originSortCol;
        
        if (sortStatus.length == 0) {
            var option = { sortIndex: strSortOrder , sortOrder:"1 1" };
            dataList.multisort(option);
        } else {
            for (var idx = 0 ; idx < sortStatus.length ; idx++) {
                var colID = sortStatus[idx].colID;
//                console.log("colID ::", colID);
                if (colID === originSortCol) {
                    var sortOrder = sortStatus[idx].sortOrder;
//                    console.log('sortOrder == ', sortOrder);
                     //1로 설정되면 오름차순 정렬, -1로 설정되면 내림차순 정렬
                    if (sortOrder == -1) {
                        //sordOrder 0이면 원래대로
                        var option = { sortIndex:strSortOrder, sortOrder:"0 0" };
                        dataList.multisort( option );
                    } else if (sortOrder == 1) {
                        var option = { sortIndex:strSortOrder, sortOrder:"-1 -1" };
                        dataList.multisort( option );
                    } else if (sortOrder == 0) {
                        var option = { sortIndex:strSortOrder, sortOrder:"1 1" };
                        dataList.multisort( option );
                    }
                }
            }
        }       
    };
    
    /*
     * ============= ============ ==========================
     *  Date          Author       Description
     * ============= ============ ==========================
     * 2022.01.17   임현진                 최초 생성
     * ============= ============ ==========================
     */
    /**
     * <pre>
     * 입력한 다중 컬럼에 해당하는 정렬 기준으로 정렬한다. 
     *
     * @memberOf scutilo
     * 
     * @example
     * 1) 원본 정렬 기준 컬럼에 대해서 정렬 컬럼의 변경이 필요한 경우
     * scutilo.sortGridMulti(gridView , ["jdbnNm", "csNo", "csProgStepNm"], ["1" , "-1" , "1"], {"csProgStepNm" : "csProgStepCd" , "csNo" : "dbCsNo"});
     * 
     * 2) 원본 정렬 기준으로만 정렬하는 경우
     * 2-1) scutilo.sortGridMulti(gridView , ["jdbnNm", "csNo", "csProgStepNm"], ["1" , "-1" , "1"], null);
     * 2-2) scutilo.sortGridMulti(gridView , ["jdbnNm", "csNo", "csProgStepNm"], ["1" , "-1" , "1"]);
     * 
     * @param {Object} grdObj - 웹스퀘어 gridView ID
     * @param {Array} arrOriginSortCol - 정렬할 원본 기준의 컬럼
     * @param {Array} arrSortOrder - 정렬할 order by 구분 {"1" : "오름차순정렬" , "-1" : "내림차순정렬"}
     * @param {Json} replaceMapSortCol(Options) - 정렬할 원본 기준의 컬럼을 변경하여 정렬하는 경우 json으로 맵핑하여 데이터 생성 {"원본 필드 컬럼" : "변경할 필드 컬럼"}
     * 
     * </pre>
     */
    var sortGridMulti = function(grdObj, arrOriginSortCol, arrSortOrder, replaceMapSortCol) {
        
        if(com.util.isEmpty(grdObj)) return;
        if(grdObj.getPluginName() !== "gridView") return;
        
        if(com.util.isEmpty(arrOriginSortCol)) return;
        if(!arrOriginSortCol instanceof Array) return;
        
        if(com.util.isEmpty(arrSortOrder)) return;
        if(!arrSortOrder instanceof Array) return;
        
        var arrOriginSortColLen = arrOriginSortCol.length;
        var arrSortOrderLen = arrSortOrder.length;
        
        if(arrOriginSortColLen === 0) return;
        if(arrOriginSortColLen !== arrSortOrderLen) return;
        
        var jsonReplaceKey = null;
        var arrTotSortOrderIndex = [];
        var arrTotSortOrderBy = [];
        
        var arrOriginKey = [];
        var arrReplaceKey = [];
        
        //변경할 필드가 존재하면
        if(!com.util.isEmpty(replaceMapSortCol) && scutilo.isJson(replaceMapSortCol)) {
            jsonReplaceKey = Object.keys(replaceMapSortCol);
            
            for(var i = 0;i<jsonReplaceKey.length;i++) {
                var key = jsonReplaceKey[i];
                arrOriginKey.push(key);
                arrReplaceKey.push(replaceMapSortCol[key]);
            }
            
            for(var i = 0 ;i<arrOriginSortCol.length;i++){
                var isChangeCol = false;
                var originSortCol = arrOriginSortCol[i];
                //원본  order by push
                arrTotSortOrderIndex.push(originSortCol);
                arrTotSortOrderBy.push(arrSortOrder[i]);
                for(var j =0;j<jsonReplaceKey.length;j++){
                    var key = jsonReplaceKey[j];
                    if(key === originSortCol){
                        //변경 orderby push
                        arrTotSortOrderIndex.push(replaceMapSortCol[key]);
                        arrTotSortOrderBy.push(arrSortOrder[i]);
                        isChangeCol = true;
                    }
                }
                if(isChangeCol){
                    //변경이 되면 변경된 필드가 우선되어야 함. //원본데이터 다시 add
                    arrTotSortOrderIndex.push(originSortCol);
                    arrTotSortOrderBy.push(arrSortOrder[i]);
                    
                    //앞에 넣었던 원본 데이터 제거
                    for(var k=0; k <arrTotSortOrderIndex.length;k++){
                        if(arrTotSortOrderIndex[k] == originSortCol){
                            arrTotSortOrderIndex.splice(k,1);
                            arrTotSortOrderBy.splice(k,1);
                            break;
                        }
                    }
                }
            }
        } else {
            //변경할 필드가 존재하지 않는 경우
            for(var i = 0 ;i<arrOriginSortCol.length;i++) {
                var originSortCol = arrOriginSortCol[i];
                //원본  order by push
                arrTotSortOrderIndex.push(originSortCol);
                arrTotSortOrderBy.push(arrSortOrder[i]);
            }
        }
        
        var strTotSortOrderIndex = "";
        var strTotSortOrderBy = "";
        var delim = " ";
        
        for(var i=0;i<arrTotSortOrderIndex.length;i++){
            strTotSortOrderIndex += arrTotSortOrderIndex[i] + delim;
            strTotSortOrderBy += arrTotSortOrderBy[i] + delim;
            // 마지막 delim 제거
            if(i == (arrTotSortOrderIndex.length-1)){
                strTotSortOrderIndex = strTotSortOrderIndex.substring(0,strTotSortOrderIndex.length-1);
                strTotSortOrderBy = strTotSortOrderBy.substring(0,strTotSortOrderBy.length-1);
            }
        }
        var dataList = $p.getComponentById(grdObj.getDataList());
        var sortStatus = grdObj.getSortableStatus();
//        console.log("scutilo sortStatus :: ", sortStatus);
        //sort 구분자 space 
        for (var idx = 0 ; idx < sortStatus.length ; idx++) {
            var colID = sortStatus[idx].colID;
//            console.log("colID ::", colID);
            if (strTotSortOrderIndex.indexOf(colID) > -1) {
                var sortOrder = sortStatus[idx].sortOrder;
                 //1로 설정되면 오름차순 정렬, -1로 설정되면 내림차순 정렬 //sordOrder 0이면 원래대로
                 //orderBy를 파라미터로 넘어온 그대로 수행
                if (sortOrder == -1) {
                    var option = { sortIndex: strTotSortOrderIndex, sortOrder: strTotSortOrderBy };
                    dataList.multisort( option );
                } else if (sortOrder == 1) {
                    var option = { sortIndex: strTotSortOrderIndex, sortOrder: strTotSortOrderBy };
                    dataList.multisort( option );
                } else if (sortOrder == 0) {
                    var option = { sortIndex: strTotSortOrderIndex, sortOrder: strTotSortOrderBy };
                    dataList.multisort( option );
                } 
            }
        }
    };
    
    /*
     * ============= ============ ==========================
     *  Date          Author       Description
     * ============= ============ ==========================
     *  2022.01.17.   백승우       [NELS]최초 생성
     * ============= ============ ==========================
     */
    /**
     * <pre>
     * 해당 문자열에서 숫자만 추출하여 문자열로 다시 이어붙여 반환한다.
     * 
     * @memberOf scutilo
     * 
     * @example ex)
     * scutilo.getNumrExtrStr('010-9431-1234');
     * scutilo.getNumrExtrStr('031-111-5555asdf');
     * scutilo.getNumrExtrStr('039-111-5555가나다');
     * 
     * @param {String} str - 문자열 : 숫자만 추출할 문자열
     * @return {String} - 결과 문자열
     * </pre>
     */
    var getNumrExtrStr = function(str) {
        var sResult = "";
        var sTemp = "";
        for (var i = 0; i < str.length; i++) {
            sTemp = str.substr(i, 1);
            if (sTemp.charCodeAt(0) > 47 && sTemp.charCodeAt(0) < 58) {
                sResult = sResult + sTemp;
            }
        }
        return sResult;
    };

    /*
     * ============= ============ ==========================
     *  Date          Author       Description
     * ============= ============ ==========================
     *  2022.01.17.   백승우       [NELS]최초 생성
     * ============= ============ ==========================
     */
    /**
     * <pre>
     * scmsg를 변환하여 반환.
     * 
     * @memberOf scutilo
     * 
     * @example ex)
     * scutilo.getMsg(scmsgo.AAO.C_0007, '치환1');
     * scutilo.getMsg(scmsgo.AAO.C_0001);
     * 
     * @param {String} msg - 메시지
     * @param {String} words - 치환 단어
     * 
     * </pre>
     */
    var getMsg = function(msg, ...words) {
        words.forEach(function(word) {
            msg = msg.replace('<%s>', word);
        });
        return msg;
    };
    
    
    /*
     * ============= ============ ==========================
     *  Date          Author       Description
     * ============= ============ ==========================
