    /**
     * <pre>
     * 인자(유효성 검사 옵션)에 대해서 유효성 검사를 수행한다.
     * 필수 값 외에 검사가 필요한 경우 'validInf.func' 속성에 검증 실패시 노출할 메시지를 반환하는 함수를 설정한다.
     * 유효성 검사 가능한 웹스퀘어 컴포넌트 유형 - input, secret(비밀번호), textarea, selectbox, multiselect, checkbox, radio, autocomplete
     * 
     * @memberOf scutilo
     * 
     * @example ex)
     * 1건 검증시 -> var valInfo = [{
                id: "acp_task",
                label: '업무구분',
            }
        ];
        var isValid = scutilo.isValidFild(valInfo);
        if(isValid) {
            com.executeSubmission(sbm_search);
        }
     * n건 검증시 -> var valInfo = [{
                id: "acp_task",
                label: '업무구분',
            },{
                id: "acp_jdbn",
                label: '재판부',
            },
        ];
        var isValid = scutilo.isValidFild(valInfo);
        if(isValid) {
            com.executeSubmission(sbm_search);
        }
     * 사용자 유효성 검사 함수(validInf.func) 사용시 -> var valInfo = [{
                id: "ibx_addFolder",
                label: '그룹명',
                mandatory: false,
                func: function(value, comObj, validInf) {
                    // 숫자만 입력 가능
                    if(scutilo.isNotEmpty(value) && ! scutilo.isNumber(value)) {
                        return scmsgo.COMMON.W_0015;
                    }
                    // 숫자만 100까지만 입력 가능
                    else if(scutilo.isNotEmpty(value) && scutilo.isNumber(value) && parseInt(value, 10) > 100) {
                        return scutilo.getMsg(scmsgo.COMMON.W_0013, '금액');
                    }
                },
            },{
                "id": "ibx_addFolder2",
                label: '태스트2',
            },
        ];
        var isValid = scutilo.isValidFild(valInfo);
        if(isValid) {
            // 유효성 검증 후 실행할 로직
        }
     * 
     * @param {String} validInf.id - 검사 필드 ID
     * @param {String} validInf.label - 검사 라벨
     * @param {String} validInf.mandatory(Options) - 입력값 검사 여부 : true(입력값체크,default) / false(입력값체크안함)
     * @param {String} validInf.func(Options) - 사용자 유효성 검사 함수 (선언 함수는 파라미터 3개를 제공함. value(validInf.id 웹스퀘어컴포넌트객체 값), comObj(validInf.id 웹스퀘어컴포넌트객체), validInf(현재 검사정보))
     * 
     * @returns {Boolean} 유효성 검사 결과
     * 
     * </pre>
     */
    var isValidFild = function(validInfArr) {
        var _self = this;
        var isValid = true;
        var failValidObj = null;
        for (var validInf of validInfArr) {
            // 기본옵션과 파라미터 옵션 머지
            var validInf = $.extend(true, {
                // 입력값 체크 여부
                mandatory: true,
            }, validInf);
            
            var comObj = $p.getComponentById(validInf.id);
            // 유효하지 않은 컴포넌트는 패스
            if(! comObj) {
                continue;
            }
            // 유효한 컴포넌트만 검사
            else {
                var pluginName = comObj.options.pluginName.toLocaleLowerCase();
                // 입력값 검사 여부
                if(validInf.mandatory) {
                    if(['input','secret','textarea','selectbox', 'multiselect', 'checkbox', 'radio', 'autocomplete'].includes(pluginName)) {
                        if(_self.isEmpty(comObj.getValue())) {
                            isValid = false;
                            // 현재 검사 조건을 복사
                            failValidObj = $.extend(true, {}, validInf);
                            // 메시지 분기
                            var finalConsonant = com.str.isFinalConsonant(failValidObj.label) ? '을' : '를';
                            if(['selectbox', 'multiselect', 'checkbox', 'radio', 'autocomplete'].includes(pluginName)) {
                                failValidObj.message = _self.getMsg(scmsgo.COMMON.W_0010, failValidObj.label + finalConsonant);
                            }
                            else {
                                failValidObj.message = _self.getMsg(scmsgo.COMMON.W_0019, failValidObj.label + finalConsonant);
                            }
                            break;
                        }
                    }
                }
                
                // 사용자 유효성 검사 함수가 있음
                if(_self.isFunction(validInf.func)) {
                    // 함수를 호출
                    var msg = validInf.func.call(null, comObj.getValue(), comObj, validInf);
                    // 리턴된 메시지가 빈값이면 검증성공, 빈값이 아니면 검증실패로 처리
                    isValid = _self.isEmpty(msg);
                    if(! isValid) {
                        // 현재 검사 조건을 복사
                        failValidObj = $.extend(true, {}, validInf);
                        failValidObj.message = msg;
                        break;
                    }
                }
            }
        }
        
        if(failValidObj) {
        	scutilo.showMsg(scglblo.MSG.WARN, failValidObj.message, function() {
                var obj = $p.getComponentById(failValidObj.id);
                obj.focus();
            });
        }
        return isValid;
    };

    /*
