     * scutilo.encode('가나다');
     * 
     * @returns {String} base64 암호화
     * </pre>
     */
    var encode = function(str) {
        // 각 화면에서 컴포넌트 이벤트로 바로 설정할 경우 this는 컴포넌트가 반환되어 예외로 _self 는 scutil로 선언
        var _self = scutilo;
        var encVal = _self.$_h._encodeBase64(encodeURIComponent(str));
        return encVal.replace(/\+/gi, '*');
    };
    
    /*
