    /**
     * <pre>
     * 해당 url에 POST로 파라메터를 전송하여 파일을 다운로드 한다.
     * 
     * @memberOf scutilo
     * 
     * @example ex)
     * var url = "/aao/aaomain/downloadFile.on";
     * var params = {
       		key : "value"
       };
     * scutilo.downloadFile(url, params);
     * 
     * @param {String} url - 다운로드 url     
     * @param {Object} params - url에 전달할 파라메터    
     * </pre>
     */
    var downloadFile = function(url, params) {
    	if (scutilo.isEmpty(params)) params = {};
		var xhr = new XMLHttpRequest();
		xhr.open('POST', url, true);
		xhr.setRequestHeader('Content-Type', 'application/json');
		com.setHeader(xhr); // SCHeader setting
		xhr.responseType = 'blob';
		xhr.onreadystatechange = function() {
			if (this.readyState === XMLHttpRequest.DONE) {
				if (this.status === 200) {
					if (this.getResponseHeader('Content-Type').indexOf('stream') < 0) {
						scutilo.showMsg(scglblo.MSG.WARN, scutilo.getMsg(scmsgo.COMMON.W_0014, '응답결과가 파일이')); //W_0014: "<%s> 아닙니다."
						return;
				    }
					var filename = "";
					var contentDisposition = this.getResponseHeader('Content-Disposition');
					if (contentDisposition && contentDisposition.indexOf('attachment') !== -1) {
						var filenameRegex = /filename[^;=\n]*=((['"]).*?\2|[^;\n]*)/;
						var matches = filenameRegex.exec(contentDisposition);
						if (matches != null && matches[1]) {
							filename = matches[1].replace(/['"]/g, '');
						}
					}
					var blob = new Blob([this.response], { type: 'application/octet-stream' });
					var downloadLink = document.createElement('a');
					downloadLink.href = URL.createObjectURL(blob);
					downloadLink.download = decodeURIComponent(filename) || 'unknown'; // 한글명 대응 
					downloadLink.click();
				} else {
					scutilo.showMsg(scglblo.MSG.ERROR, scutilo.getMsg(scmsgo.COMMON.E_9006, '파일 다운로드에')); //<%s> 실패하였습니다.
				}
			} 
		};
		xhr.onerror = function() {
			// 요청 중 오류 발생 시 메시지 출력
			scutilo.showMsg(scglblo.MSG.ERROR, scutilo.getMsg(scmsgo.COMMON.E_9006, '다운로드 요청에')); //<%s> 실패하였습니다.
		};
		xhr.send(JSON.stringify(params));
    };
    
