/**
 * <pre>
 * 화면프로그램ID로 해당 작업XML 경로를 반환
 * (예) psp611m01 ==> "/psp/ui/psp610/PSP611M01.xml"
 *
 * (사용법) getXmlPathByPgmId('psp611m01'), getXmlPathByPgmId('PSP611M01')
 * </pre>
 *
 * @param   prgmId    화면프로그램ID (예) psp611m01, PSP611M01
 * @return  화면XML 경로
 * ============= ============ ==========================
 *  Date          Author       Description
 * ============= ============ ==========================
 *  2023.03.31.   안종광         [NELS]최초 생성
 * ============= ============ ==========================
 */
psp.getXmlPathByPgmId = function(prgmId) {
    var xmlpath = psp.CONTEXT_ROOT + "/ui";
    try {
        var pgmid = prgmId.toLowerCase();
        var chr4  = pgmid.charAt(3); // 0-7, a,b,c

        //pspa00, pspb00, pspc00, pspz00, psp100
        xmlpath += "/" + pgmid.substring(0,3);
        xmlpath += chr4; // a,b,c,d,z, 1..7
        xmlpath += isNaN(chr4) ? pgmid.charAt(4) : '0'; //('b'==chr4 || 'c'==chr4 || 'd'==chr4 || 'z'==chr4) ? pgmid.charAt(4) : '0';
        xmlpath += '0';
        xmlpath += "/" + pgmid.toUpperCase() + ".xml"; //PSP611M01.xml

        var chr7  = pgmid.charAt(6); // P or M or F
        if ( (new RegExp(/[P]/gi)).test(chr7) ) { //(팝업이면, 7번째 P) PSPZIPP01
            if ( ! (new RegExp(/[0-9ABCDIGZK]/gi)).test(chr4) || new RegExp(/pspzip/).test(pgmid) ) { //PSP1xxP01, ..., PSP7xxP01, PSPAxxP01, PSPBxxP01 이 아니면, 공통팝업
                xmlpath = psp.CONTEXT_ROOT + "/ui/psppop/" + pgmid.toUpperCase() + ".xml"; // 공통팝업 (예) PSPZIPP01
            }
        }
    }
    catch(e) {
        xmlpath += "/pspcom/pferror.xml";
        _error("[#gxpbpi] 화면ID = [" + prgmId + "], XML경로 = [" + xmlpath + "]");
    }
    _trace("[#gxpbpi] 화면ID = [" + prgmId + "], XML경로 = [" + xmlpath + "]");
    return xmlpath;
};

/**
 * <pre>
 * [ 주PID, 부PID ]를 참조하여 최종적으로 작업영열에 로드할 xml경로를 결정하여 반환
 *
 * (1)주PID 우선 (2)부PID있으면 사용
 * </pre>
 *
 * @param   mPgmId    주화면프로그램ID (예) PSP611M01
 * @param   sPgmId    부화면프로그램ID (예) PSP611M02
 * @return  화면XML 경로
 * ============= ============ ==========================
 *  Date          Author       Description
 * ============= ============ ==========================
 *  2023.03.31.   안종광         [NELS]최초 생성
 * ============= ============ ==========================
 */
psp.getXmlPath2Load = function(mPgmId, sPgmId) {
	var mPID = mPgmId.toUpperCase();
	var pageinfo = {
		"viewid": mPID,
		"viewtype": "main",
		"viewpath": "",
	}
	var xmlpath = this.getXmlPathByPgmId(mPID); // scwin.getXmlPathByPrgmId(s);
	pageinfo.viewpath = xmlpath;
	if ( scutilo.isEmpty(sPgmId) || mPID.startsWith("PSP10") ) { //s값이 없거나, m값이 로그인/사용자 화면이면,
		return pageinfo;
	}
	if ( xmlpath.endsWith("pferror.xml") ) { //오류페이지 연결
		return pageinfo;
	}

	var sPgmIdTmp = 2>=sPgmId.length ? mPgmId.substring(0,7) + (1==sPgmId.length ? "0" : "") + sPgmId : sPgmId;
	if ( sPgmIdTmp == mPgmId ) {
		return pageinfo;
	}

	pageinfo.viewpath = this.getXmlPathByPgmId(sPgmIdTmp);
	pageinfo.viewtype = "sub";
	pageinfo.viewid = sPgmIdTmp;
	_trace("[#gxp2l] 화면정보 :", pageinfo);
	return pageinfo;
};

