/**
 * 페이지 초기화 처리후
 * 웹스퀘어 파라미터(wframeParam)와 추가 파라미터를 합쳐서 반환
 *
 * @param	wsObj		웹스퀘어 오브젝트
 * @param	addParam	추가 파라미터 객체
 * @return	페이지 파라미터(wframeParam)
 * ============= ============ ==========================
 *  Date          Author       Description
 * ============= ============ ==========================
 *  2023.03.31.   안종광         [NELS]최초 생성
 * ============= ============ ==========================
 */
psp.getPageInit = function(wsObj, addParam) {
	var frmId = ""; // wsObj == $p
	try {
		frmId = wsObj.getFrame().id; // mf_pfwork (or) mf_pfwork_wfm_csBas (or) mf_pfwork_wfm_csBas_...
	}
	catch(e) {
		frmId = "mf_pfwork";
	}
	_trace("[#g_p_i] frame(id) :", frmId);
	scglblo.setCtxtPath("/psp");

	if ( "mf_pfwork" != frmId ) {
		return psp.getPageParam(wsObj); //하위 프레임이 로드되면, 전달된 파라미터객체만 전달하면 됨.
	}

	//scglblo.setCtxtPath("/psp");
	var _scmain = scutilo.getSCMain();
	if ( null==_scmain.scglblo.getCtxtPath() ) {
		_scmain.scglblo.setCtxtPath("/psp");
	}
	_trace("[#g_p_i] (_scmain) context path : " + _scmain.scglblo.getCtxtPath() + "");
	_trace("[#g_p_i] added param : ", addParam);

	var pageparam = psp.getPageParam(wsObj);
	_trace("[#g_p_i] page param :", pageparam);

	// 모바일웹인 경우 서류화면이동 제한(@2023-12)
	if ( true==psp.env.isMobileWeb() )
	{
		var mWebMsg = psp.getRestrictMenuMessageOnMobWeb(pageparam, null);
		_debug("[#g_p_i] 모바일웹제한메시지 :", mWebMsg);
		if ( scutilo.isNotEmpty(mWebMsg) ) {
			//scutilo.showMsg(scglblo.MSG.INFO, mWebMsg);
			// (참조메시지) C_0104: "모바일앱(App) 설치후 사용할 수 있는 메뉴(화면)입니다.\n앱(App) 설치를 진행하시겠습니까?"
			scutilo.showConfirm(scglblo.MSG.CONFIRM, scutilo.getMsg(pspmsg.PSP.C_0104), function(result) {
				if ( result.clickValue) {
					window.self.location = "mcsscourt://"; //param : 실행시 파라미터를 넘길 경우
					setTimeout(() => {
						alert("추후 앱스토어에 정식 등록되면 설치화면으로 이동."); //설치 URL로 수정 예정 (iOS, android 다름)
						psp.go_url(); //TODO
					}, 200);
				}
				else {
					psp.go_url();
				}
			});
			return false; //서류 화면이동을 처리하지 않음
		}
	}

	//1. 페이지타이틀(id = tbx_pagetitle)의 텍스트를 메뉴명으로 교체
	psp.initPageTitleComponent(pageparam);
	psp.initPageMyMenuComponent(pageparam);
	psp.initPagePrintComponent(pageparam);

	var viewid = null;

	//2. 메뉴경로 표시
	try {
		psp.displayMenuPath(pageparam); //build_screen_path();

		viewid = scutilo.isEmpty(pageparam["viewid"]) ? "" : pageparam["viewid"];

		if ( scutilo.isNotEmpty(viewid) ) {
			var _url = "index.on?s=" + viewid;
			_trace("[#g_p_i] history :", _url);
			//history.pushState({ data: pageparam }, null, _url);
		}
	}
	catch(e) {
		_warn("[#g_p_i]", "build_screen_path() ", e.message);
	}

	//3. 문서메뉴는 다른 좌측 메뉴
	try {
		$p.top().pfmenu.show();
		$p.top().pfright.show();

		if ( scutilo.isNotEmpty(viewid) ) {
			var chr4 = viewid.charAt(3);
//			if ( isNaN(chr4) ) { //문서메뉴인 경우 [A,B,C]
//				$p.top().pfmenu.setSrc(psp.CONTEXT_ROOT + "/ui/pspcom/pfmenudoc.xml", pageparam);
//			}
//			else { //일반메뉴
				$p.top().pfmenu.setSrc(psp.CONTEXT_ROOT + "/ui/pspcom/pfmenu.xml", pageparam);
				_trace("[#getPageInit] 일반메뉴 viewid", viewid);
				if ( viewid.toUpperCase().startsWith("PSP004M") ) { //통합검색일때,
					$p.top().pfmenu.hide();
					$p.top().pfright.hide();
				}
//			}
		}
		else {
			_warn("[#g_p_i] No viewid :", pageparam);
		}
	}
	catch(e) {
		_warn("[#g_p_i] 문서메뉴는 다른 좌측 메뉴", e.message);
	}

	//4. 기타 처리
	try {
		$(".right_menus2").removeClass("active"); //우측 바로가기 감추기
		$(".process_box").hide();
	}
	catch(e) {
		_warn("[#g_p_i] 기타 처리", e.description);
	}
	try { //4.2) 메인(Mxx)에서는 프로그램ID를 헤더에 설정함
		scscrno.setScPgmId(pageparam["viewid"]);
	}
	catch(e) {
		_warn("[#g_p_i] 기타 처리", e.message);
	}

	//5. 추가 처리 (1) QS에 tab=1 이 전달되면, 탭선택
	try {
		var pgmTabIdx =  pageparam["tab"];
		if ( scutilo.isNotEmpty(pgmTabIdx) && wsObj.getComponentById("tabCtrl") ) {
			wsObj.getComponentById("tabCtrl").setSelectedTabIndex(pgmTabIdx);
		}
	}
	catch(e) {
		_warn("[#g_p_i] 추가 처리", e.message);
	}

	return pageparam;
};


