		_debug("[#i_p_t_c] sub 화면은 제목을 조정하지 않음.");
		return;
	}
	var pgTtlComp = psp.componentById("tbx_pagetitle", psp.WORK_FRAME_ID);
	try {
		if (null==pgTtlComp) {
			var comps = psp.componentsBy("textbox", ["title"], $p.top().pfwork); // "dsInb"
			pgTtlComp = comps[0];
		}
		pgTtlComp.setValue(pageparam["viewname"]);
	}
	catch(e) {
		_debug("[#i_p_t_c] 페이지 타이틀 없음!");
	}
};

/**
 * 업무영역 상단의 [나의 메뉴 추가] 버튼 초기화 처리
 *
 * @param	pageparam	페이지 파라미터
 * ============= ============ ==========================
 *  Date          Author       Description
 * ============= ============ ==========================
 *  2023.05.03.   안종광         [NELS]최초 생성
 * ============= ============ ==========================
 */
psp.initPageMyMenuComponent = function(pageparam) {
	var mmComp = null;
	try {
		var comps = psp.componentsBy("trigger", ["btn_icT_myAdd", "btn_fcm"], $p.top().pfwork);
		mmComp = comps[0];
		mmComp.setValue('나의 메뉴 추가');
		mmComp.setTitle('나의 메뉴 추가');

		var myFavMnLst = psp.ss.get(psp.LS_KEY_MN_F).filter( mn => '01' === mn.elpMenuDvsCd );
		var isInclFavMn = false;

		if ( scutilo.isEmpty(psp.session()) || "sub"==pageparam.viewtype ) {
			mmComp.setDisabled(true);
			return;
		}
		mmComp.setDisabled(false);

		myFavMnLst.forEach(function(menu, index) {
			if ( pageparam.viewid == menu.pgmUrl ) {
				mmComp.setTitle('나의 메뉴 삭제'); mmComp.setValue('나의 메뉴 삭제');
				return false;
			}
		});

		if ( false==mmComp.getDisabled() ) {
			mmComp.bind("onclick", function() {
				WebSquare.layer.showProcessMessage(`나의 메뉴 로드중입니다.`);
				var trxnTyp = this.getValue() == "나의 메뉴 삭제" ? "delete" : "insert";
				_debug("[#i_p_mm_c] my menu", trxnTyp);
				psp.setHeader();

				//진행중사건 -> 나의법원설정 에서 <- 이전페이지가기 클릭시 psp.pageparam 사라짐 현상으로
				// 나의메뉴추가시 오류발생 방지
				if ( "PSP221M01"==pageparam.viewid ) {
					pageparam["elpMenuSrno"] = "150201";
				}

				WebSquare.layer.showProcessMessage(`나의 메뉴 ${"delete"==trxnTyp ? "삭제":"등록"}중입니다.`);
				com.executeAjax({ //
					action: psp.CONTEXT_ROOT + `/pspmenu/${trxnTyp}FavMenu.on`, //"/pspmenu/insertFavMenu.on"
					mode: "asynchronous",
					mediatype: gcm.DEFAULT_OPTIONS_MEDIATYPE,
					requestData: JSON.stringify(Object.assign({'elpMenuDvsCd':'01'}, pageparam)),
					success: function(R) {
						WebSquare.layer.hideProcessMessage();
						var rslt = R.responseJSON.data.dma_result;
						var trnx = rslt["trnx"];
						var favmenu = R.responseJSON.data.dlt_favmenu;
						_debug("[#i_p_mm_c] 즐겨찾기메뉴 처리(결과) :", rslt);
						if ( ! scutilo.isEmpty(trnx) && null!=favmenu ) {
							psp.ss.remove(psp.LS_KEY_MN_F);
							psp.ss.set(psp.LS_KEY_MN_F, favmenu);
							var label = "insert" == trnx ? "나의 메뉴 삭제" : "나의 메뉴 추가";
							mmComp.setTitle(label); mmComp.setValue(label);
							_debug("[#i_p_mm_c] 즐겨찾기메뉴 처리후 개수 :", favmenu.length);
						}
						try {
							( "insert"===trnx ) ? $p.top().pfright.scope.scwin.createFavMenu(pageparam) : $p.top().pfright.scope.scwin.removeFavMenu(pageparam);
						}
						catch (e) {
							_info("[#i_p_mm_c] (cause)", e.message);
						}
					},
				});
			});
		}
	}
	catch(e) {
		_info("[#i_p_mm_c] No MyMenu Component! (cause)", e.message);
	}
};

