 * ============= ============ ==========================
 *  Date          Author       Description
 * ============= ============ ==========================
 *  2023.03.31.   안종광         [NELS]최초 생성
 * ============= ============ ==========================
 */
psp.displayMenuPath = function(pageparam) {
	var currMenuinfo = scutilo.isEmpty(pageparam["pgmUrl"]) ? psp.ss.get(psp.LS_KEY_MN_C) : psputils.clone(pageparam); //psp_currmenu
	var menulist = psp.hierarchyMenuList(currMenuinfo);
	var menulen = menulist==null ? -1 : menulist.length;

	var currLv1Menu = 0==menulen ? currMenuinfo : menulist[menulen-1];
	var currLv2Menu = 2>menulen ? currMenuinfo : menulist[menulen-2];
	var currLv3Menu = 3>menulen ? null : menulist[menulen-3];

	psp.componentById("spn_lvl_1", "pfpath").setValue( currLv1Menu["menuNm"] );
	psp.componentById("spn_lvl_2", "pfpath").setValue( currLv2Menu["menuNm"] );
	if ( null!=currLv3Menu ) {
		psp.componentById("spn_lvl_3", "pfpath").setValue( currLv3Menu["menuNm"] );
		psp.componentById("li_lvl_3", "pfpath").show();
	}
};

/**
 * 현재 서류화면의 스텝 정보를 좌측메뉴 영역에 생성하여 표시 (메뉴정보는 감춤)
 *
 * @param   pObj      호출한 $p 객체
 * @return  오류메시지
 * @see     pfmenu.xml#createDocSteps()
 * ============= ============ ==========================
 *  Date          Author       Description
 * ============= ============ ==========================
 *  2023.08.15.   안종광        [NELS]최초 생성
 *  2024.10.07.   김기석        pStepNm 파라미터 추가
 * ============= ============ ==========================
 */
psp.displayDocSteps = function(pObj,pStepNm) {

	// pStepNm
	// 1.문서작성     - psp.displayDocSteps($p);              -- 기존대로 호출
	// 2.최종문서확인 - psp.displayDocSteps($p,"문서확인");
	// 3.전자서명     - psp.displayDocSteps($p,"서명");
	// 4.소송비용납부 - psp.displayDocSteps($p,"납부");
	// 5.전자제출     - psp.displayDocSteps($p,"제출");


	var errMsg = null;
	var pFrm = null==pObj ? $p.top().pfwork : pObj.getFrame();

	try {
		var thisFrmId = pObj.id; //(ex) 'mf_pfwork_wfm_tab01_'
		var objDma = psp.componentById("dma_docmt"); //pObj.getComponentById("dma_docmt") //pObj.parent().dma_docmt
		var objDlt = psp.componentById("dlt_steps"); //pObj.getComponentById("dlt_steps") //pObj.parent().dlt_steps

		var dmaDocmt = objDma.getJSON();
		var dltSteps = objDlt.getAllJSON();
		if ( null==dmaDocmt || null==dltSteps ) {
			errMsg = "서류 단계정보를 참조할 수 없습니다!";
			_error("[#d_d_s]", errMsg);
			return errMsg;
		}

		var panels = WebSquare.util.getChildren(pFrm, {recursive:true, includePlugin:"panels"}); //$p.top().pfwork
		var pnl0id = (null==panels || 0==panels.length) ? null : panels[0].id; // (ex) mf_pfwork_wfm_tab01_acd_mainDoc_panel_pan_csBasInf (or) mf_pfwork_acd_mainDoc_panel_pnl_csBas

		var tabCtrlObj = null;
		var tabArr = null;
		var tabIdx = -1;
		var tabFrmId = null;

		//if ( scutilo.isNotEmpty(pnl0id) && ( pnl0id.indexOf("wfm_tab")>0 || pnl0id.indexOf("wfmTab")>0 ) ) {
		if ( ! pFrm.id.endsWith("pfwork")  ) {
			//1번째 탭컨트롤 객체
//			tabCtrlObj = WebSquare.util.getChildren(pFrm.getParentFrame(), {recursive:true, includePlugin:"tabControl"})[0]; //$p.top().pfwork 이 맞음
//			if ( "none" == tabCtrlObj.getStyle("display") ) { // (노트) 회생파산서류 - 파산관재인보고서 는 탭컨트롤이 2개임.
//				tabCtrlObj = WebSquare.util.getChildren(pFrm.getParentFrame(), {recursive:true, includePlugin:"tabControl"})[1];
//			}
			tabCtrlObj = pspscrn.getTabControl(pFrm); //엔진 버그가 있어서 회피하는 코드를 추가(2024-01-04)
			tabArr     = tabCtrlObj.tabArr;
			var contArr = tabCtrlObj.contentsArr; //WebSquare.util.getChildren($p.top().pfwork, {recursive:true, includePlugin:"tabControl"})[0].contentsArr[0].xml.childNodes[1].id
			for(var i=0; i<contArr.length; i++) {
				var cNodes = contArr[i].xml.childNodes;
				for(var x=0; x<cNodes.length; x++) {
					if ( "w2:wframe" == cNodes[x].nodeName ) { //nodeType=1
						tabIdx = i;
						tabFrmId = cNodes[x].id;
						break;
					}
				}
				if ( scutilo.isNotEmpty(tabFrmId) ) {
					break;
				}
			}
			_debug(`[#d_d_s] tabArr# = ${tabArr.length}, tabIdx = ${tabIdx}, tabFrmId = '${tabFrmId}'`);
		}
		//$p.top().pfmenu.scope.scwin.createDocSteps(dmaDocmt, dltSteps, panels, pObj);
		$p.top().pfmenu.scope.scwin.createDocStepsWithTab(dmaDocmt, dltSteps, panels, tabArr, tabIdx, tabFrmId, tabCtrlObj, pObj, pStepNm);


	}
	catch(e) {
		errMsg = e.message;
		_error("[#d_d_s]", e.message);
	}
	return errMsg;
};


/**
 * 현재 서류메뉴의 스텝1(문서작성) 리스트 정보를 현재 패널의 표시/감춤여부에 따라 다시 표시한다.
 * (요구사항) 업무화면에서 패널의 표시/감춤이 동적으로 변경된다. 이에 따라 문서작성 단계를 다시 표시하도록 함.
 *
 * @param   delayMillis   지연시각(밀리초)
 * @see     pfmenu.xml#redisplayDocSteps()
 * ============= ============ ==========================
 *  Date          Author       Description
 * ============= ============ ==========================
 *  2024.07.05.   안종광        [NELS]최초 생성
 * ============= ============ ==========================
 */
psp.redisplayDocSteps = function(delayMillis) {
	var millis = undefined==delayMillis || 10>delayMillis || 5000<delayMillis ? 100 : delayMillis;
	setTimeout(function() {
		$p.top().pfmenu.scope.scwin.redisplayDocSteps();
	}, millis);
};

/**
 * 팝업화면을 표시 (레이어팝업)
 * (참조) scutilo.openUrlPopup()
 *
 * (소스히스토리)
 * 1. scutil.openUrlPopup()
 * 2. scutilo 에는 없음.
 * 3. psp.js에 위 scutil.openUrlPopup() 을 참조하여, openPopup()로 수정
 * 4. 이 함수에 대응하는 close() 함수는 com.win.closePopup()임 (소스 commonScope.js)
 * 5. 위 4함수를 사용하지 않고, openPopup의 짝함수로 closePopup() 여기(psp.js)에 두고 사용.
 *
 * @example scutilo.openUrlPopup("~/psp000/PSP000P01.xml", "PSP000P01", "주소정보조회" , {"initData1" : "123", "initData2" : "456"}, 820 , 1650 ,  "scwin.callBackAddrExec");
 * @param   popupId         오픈 팝업아이디 (예) 'PSP000P01' (또는) '/psp/ui/pspcom/PSPLayoutDefault.xml'
 * @param   popupNm         오픈 팝업명 (예) 담당직원지정
 * @param   paramInfo       오픈되는 팝업화면에 넘겨줄 정보
 * @param   popupScrnHght   팝업 높이
 * @param   popupScrnWdth   팝업 넓이
 * @param   callbackFn      팝업창이 닫힐 때 결과를 수신하여 처리할 콜백함수
 * @param   disableClose    [X] 버튼 표시여부. false이면 표시안함
 */
psp.open_popup = function(popupId, popupNm, paramInfo, popupwidth, popupheight, callbackFn, disableClose, classNm) {
    _debug(`[_#o_p] popupId = '${popupId}', popupNm = '${popupNm}'`);
    var baseUrl = ""; //사용안함 // "/psp/ui/pspcom/PSPLayoutDefault.xml"; //"/stg/ui/stgmain/STGMainPSubContainer.xml";
    var hCrtVal = 70; //높이에 대한 보정값
    var pgmUrl = psp.getXmlPathByPgmId(popupId);

    //팝업아이디가 아닌 전체 경로를 전달한 경우이면, 경로에서 역으로 팝업아이디 추출 @2023-09
    if ( 0 <= popupId.indexOf("/ui/") && 0 < popupId.split("/").length ) {
        pgmUrl = popupId;
        let len = popupId.split("/").length;
        popupId = popupId.split("/")[len-1].replace(/.xml/, ''); //
    }
    _debug(`[_#o_p] popupId = '${popupId}', pgmUrl = '${pgmUrl}'`);

    var opt = {};
        opt.id     = popupId;
        opt.width  = popupwidth;
        opt.height = popupheight;
        opt.type   = "wframePopup"; // "browserPopup";
        opt.modal  = true;
        opt.popupName = popupNm + "";
        opt.disableCloseButton = null==disableClose ? false : disableClose;
        opt.className = null==classNm ? "" : classNm;

    var data = {};
    $.extend(data, paramInfo);
    data.callbackFn = callbackFn;
    data.popupId = popupId;

    //dataobject에 추가할 데이터 셋팅
    var moveData = {
        originUrl : pgmUrl,
        title : opt.popupName,
        frame : "main"
    };

    $.extend(data, moveData);

    var _dataObj = {
        type : "json",
        data : data,
        name : "paramData"
    };
    var width = opt.width || 500;
    var height = opt.height || 500;

    try {
        var deviceWidth = parseFloat($("body").css("width"));
        var deviceHeight = parseFloat($("body").css("height"));

        if (!opt.notMinSize) {
            var borderSize = 4;
            if (opt.type != "browserPopup"){
                borderSize = 4
                if (deviceWidth > 0 && width > deviceWidth) {
                    width = deviceWidth - borderSize; // 팝업 border 고려
                }

                if (deviceHeight > 0 && height > deviceHeight) {
                    height = deviceHeight - borderSize; // 팝업 border 고려
                }
            }
            else {
                if (window.screen.availHeight <= height) {
                    height = window.screen.availHeight-10;
                }
            }
        }
    }
    catch (e) {
        _error("[#o_p]", "<ERROR>", e.message);
    }

    opt.type = opt.type || "wframePopup";

    var top = ((document.body.offsetHeight / 2) - ( (com.num.parseInt(height) + hCrtVal ) / 2) + $(document).scrollTop()); // hCrtVal(높이에 대한 보정값)
    try {
        if (top < 0) { // 음수값일 경우 팝업 상단 잘리므로 처리 (24-09-30)
        	top = 0;
        }
    	let windowTopPosition = Number(window.pageYOffset || document.documentElement.scrollTop || document.body.scrollTop || 0);
    	if (top < windowTopPosition) { // 현재 윈도우 top 위치보다 작을 경우 팝업 상단 잘리므로 처리 (24-10-02)
    		top = windowTopPosition;
    	}
    } catch (e) {
    	_error("psp.open_popup 최소 top 높이 계산 error");
    	_debug("psp.open_popup 최소 top 높이 계산 error", e.stack);
    }
    var top = top + "px";

    var left = ((document.body.offsetWidth / 2) - (com.num.parseInt(width) / 2) + $(document).scrollLeft()) + "px";

    if (opt.type == "browserPopup") {
        top = Math.floor(((window.screen.availHeight- 50 - com.num.parseInt(height)))/ 2) + (window.screen.availTop|| 0) + "px";
        left = Math.floor((window.screen.availWidth - com.num.parseInt(width)) / 2) + (window.screen.availLeft || 0 ) + "px";
    }
    _trace("[_#o_p] $p.id : " + $p.id + "\n\n- window.$p.getPopupId()=" + window.$p.getPopupId())

    if (typeof _dataObj.data !== "undefined") {
        if (typeof _dataObj.data.callbackFn == "function") {
            var cbFuncIdx = ++gcm.CB_FUNCTION_MANAGER["cbFuncIdx"];
            var idx = "__close_callback_Func__" + new Date().getTime() + "_" + cbFuncIdx;
            gcm.CB_FUNCTION_MANAGER["cbFuncSave"][$p.id + idx] = _dataObj.data.callbackFn;
            _dataObj.data.callbackFn = $p.id + idx;
        }
        else if (typeof _dataObj.data.callbackFn === "undefined") {
            _dataObj.data.callbackFn = "";
        }
        else if (typeof _dataObj.data.callbackFn === "string") {
            _dataObj.data.callbackFn = $p.id + _dataObj.data.callbackFn;
        }
        _trace("[_#o_p] [$p.id + idx] = [" + ($p.id + idx) + "]");
        _trace("[_#o_p] [_dataObj.data.callbackFn] = [" + (_dataObj.data.callbackFn) + "]");
    }

    var paramUrl = "";

    if ((opt.type !== "wframePopup") && (com.util.isEmpty(_dataObj.data) === false)) {
        paramUrl = "&" + _dataObj.name + "=" + WebSquare.text.BASE64Encode(com.str.serialize(_dataObj.data)) ;
        _trace("[_#o_p] paramUrl#0 = " + paramUrl);
    }
    _trace("[_#o_p] paramUrl#1 = " + paramUrl);

    var options = {
            id : opt.id,
            popupName : opt.popupName || "",
            type : opt.type || "wframePopup",
            width : width + "px" || "1600px",
            height : height + "px" || "900px",
            top : opt.top || top || "140px",
            left : opt.left || left || "500px",
            modal : (opt.modal == false) ? false : true,
            dataObject : _dataObj,
            alwaysOnTop : opt.alwaysOnTop || false,
            useModalStack : (opt.useModalStack == false) ? false : true,
            useATagBtn: false, // 수정
            resizable : (opt.resizable == false) ? false : true,
            useMaximize : opt.useMaximize || false,
            className :opt.className || "",
            scrollbars : true,
            disableCloseButton  : opt.disableCloseButton || false,
            //popupUrl : ".."+gcm.STG_CONTEXT_PATH+"/popup"
            accessibility : true, //추가
            useATagTitle : true //추가
        };

	if ( false===options.disableCloseButton ) {
		//(@2024-07-08) 팝업창 [X] 클릭시 처리하는 콜백함수로, 현재 팝업창의 콜백함수가 지정되어 있으면 해당 함수를 호출함.
		options["closeAction"] = function(id, info) {
			//com.win._closePopup(id, _dataObj.data.callbackFn, "{}");
			var cbFuncId = _dataObj.data.callbackFn; //콜백함수아이디
			var cbfunc = gcm.CB_FUNCTION_MANAGER["cbFuncSave"][cbFuncId];
			if (cbfunc) {
				try {
					delete gcm.CB_FUNCTION_MANAGER["cbFuncSave"][cbFuncId];
					cbfunc({}); //완전한 빈객체를 반환 //cbfunc(info); //(참고)info = {"isCloseButtonClick":true}
				}
				catch (e) {
					_error("[_#o_p] closeAction() ", e.message);
				}
			}
			return true;
		};
	}

    if ( ""==paramUrl ) {
        paramUrl = pgmUrl;
    }
    _trace("[_#o_p] options = " + JSON.stringify(options));

    if (options.type !== "wframePopup") {
        var __url = baseUrl + paramUrl;
        _trace("[_#o_p] url = " + __url);
        $p.openPopup(baseUrl + paramUrl, options);
    }
    else {
        var __url = gcm.CONTEXT_PATH + baseUrl + paramUrl;
        _trace("[_#o_p] popup path = " + __url);
        $p.openPopup(__url, options);
    }

};

