 * ============= ============ ==========================
 *  Date          Author       Description
 * ============= ============ ==========================
 *  2023.03.31.   안종광         [NELS]최초 생성
 * ============= ============ ==========================
 */
psp.get_allmenu_list = function(doforcely) {
	var allmenu = null;
	var allmenustr = null;

	if ( null==doforcely || true!=doforcely ) {
		allmenu = psp.ss.get(psp.LS_KEY_MENU, true);
		if ( null!=allmenu && 'object'== typeof allmenu ) {
			return allmenu;
		}
		//뭔가 오류가 있으면, 메뉴 조회후 반환
	}
	psp.ss.remove(psp.LS_KEY_MENU); //WebSquare.localStorage.removeItem("psp_allmenu");

