 *
 * @param  doforcely  무조건 조회하여 설정하려면 true
 * @return 사용자유형별 메뉴 목록
 * ============= ============ ==========================
 *  Date          Author       Description
 * ============= ============ ==========================
 *  2023.06.30.   안종광         [NELS]최초 생성
 * ============= ============ ==========================
 */
psp.getUserMenu = function(doforcely) {
	var usermenu = null;
	if ( null==doforcely || true!=doforcely ) {
		usermenu = psp.ls.get(psp.LS_KEY_MENU, true); //(주의) 사용자메뉴지만, 저장키로는 'psp_allmenu' 사용
		if ( null!=usermenu && 'object'== typeof usermenu ) {
