/**
 * 서버측 세션에서 지정한 키의 값을 조회하여 반환. 콜백함수가 지정되면 async로 호출하고 해당 콜백함수를 호출
 *
 * @param	key			조회할 키문자열 (예) "elpUserId", "elpUserId,loginType"
 * @param	callback	조회후 호출할 콜백함수(문자열 반환값으로 콤마 구분값)
 * @return	콜백함수가 지정되지 않은 경우 sync로 호출되며 (문자열 반환값으로 콤마 구분값) 반환
 * @see
 * ============= ============ ==========================
 *  Date          Author       Description
 * ============= ============ ==========================
 *  2023.02.14.   안종광        [NELS]최초 생성
 * ============= ============ ==========================
 */
psp.getSession = function(key, callback) {
    var _mode = "synchronous";
    var val = null;

    if ( null!=callback && 'function'== typeof callback ) {
        _mode = "asynchronous";
    }

	//client 세션값 체크 추가
    if(!psp.ss.hasData(psp.LS_KEY_USER)) {
        psp._clearClntSesn(2);  //세션조회결과 없음
        if ( "asynchronous"===_mode ) {
        		callback.call(null, val);
        }
        return val;
    }

    var param = {
        "dma_ssreq" : {
            "n":psp.session('userRandNo'),
            "k":scutilo.encode(null==key||scutilo.isEmpty("key")?"elpUserId":key)
        }
    }
    try {
        var url = psp.CONTEXT_ROOT + "/psp001/session.on"; //getSession
        com.executeAjax({
            action: url,
            mode: _mode,
            method: 'POST',
            mediatype: gcm.DEFAULT_OPTIONS_MEDIATYPE,
            requestData: JSON.stringify(param),
            success: function(_data) {
                var _dma = _data.responseJSON.data.dma_ssresp;
                respCode = _data.responseJSON.data.dma_ssresp.respCode;
                //_debug("[#gs] (dma_ssresp)", _dma);
                if ( "00"==respCode ) {
                    var k = scutilo.decode( _dma["k"] );
                    val = scutilo.decode( _dma["v"] );
                    //_debug("[#gs] 조회결과 : k = [" + k + "], v = [" + val + "]");
                }
                else {
                    psp._clearClntSesn(2);  //세션조회결과 없음
                    _info("[#gs] (resp data)\n", _data.responseJSON.data);
                }
                if ( "asynchronous"===_mode ) {
                    callback.call(null, val);
                }
            },
        });
    }
    catch(e) {
        //psp._clearClntSesn();
        _error("[#gs] (e오류) ", e);
        val = null;
    }
    return val;
};

/**
 * 서버측 세션을 조회하지 않고, 현재 페이지 로드시 설정된 '간단한' 세션정보를 조회하여 반환
 *
 * @param	key		조회할 키문자열 (주의) 1개의 키만 허용
 * @return	키가 지정되면 해당 값(문자열), 키가 지정되지 않으면 '간단한' 세션정보(객체)로 반환. 없으면 null반환
 * @see
 * ============= ============ ==========================
 *  Date          Author       Description
 * ============= ============ ==========================
 *  2023.12.15.   안종광        [NELS]최초 생성
 * ============= ============ ==========================
 */
psp.getSmplSesn = function(key) {
	var ssObj = null;
	try {
		//client 세션값 체크 추가
		if(!psp.ss.hasData(psp.LS_KEY_USER)) return null;

		if ( pdsv['shared'] && pdsv['shared']['ssi'] ) {
			ssObj = JSON.parse( decodeURIComponent ( atob( pdsv['shared']['ssi'] ) ) );
		}
	}
	catch(e) {
		ssObj = null; _error("[#g.s.s] (오류) ", e.message);
	}
	if (null==ssObj) { return null; }
	if (null==key || scutilo.isEmpty(key)) {
		return ssObj;
	}
	return ssObj[key];
};

/**
 * 쿠키에 SID가 존재하는지 확인
 *
 * 실제로 쿠키에 SID가 존재하는지는 확인하지 못함. (쿠키 httponly 속성으로 인해)
 * 따라서, 업무별로 구현한 세션 확인 함수를 통해 결과값을 리턴한다.
 *
 * @param
 * @return
 * @see
 * ============= ============ ==========================
 *  Date          Author       Description
 * ============= ============ ==========================
 *  2024.12.13.   백인호        [NELS]최초 생성
 * ============= ============ ==========================
 */
psp.hasSid = function() {
	// 일반 (인증서로그인, 아이디로그인, 임시사용자 등)
	try {
		if (scutilo.isNotEmpty(psp.session())) {
			return true;
		}
	} catch (e) {
		_error("psp.hasSid", "psp.session");
		_debug("psp.hasSid", "psp.session", e.stack);
	}

	// 관리자
	try {
		if (scutilo.isNotEmpty(pspadmin.session())) {
			return true;
		}
	} catch (e) {
		_error("psp.hasSid", "psp.session");
		_debug("psp.hasSid", "psp.session", e.stack);
	}


	// 재판조력자 커뮤니티
	try {
		if (scutilo.isNotEmpty(psp.getHlprSession())) {
			return true;
		}
	} catch (e) {
		_error("psp.hasSid", "psp.getHlprSession");
		_debug("psp.hasSid", "psp.getHlprSession", e.stack);
	}

	return false;
};

