/**
 * 현재 URL의 주프로그램 메뉴의 권한유형과 세션정보를 참조하여,
 * 접근가능한 메뉴(OK)인지, 로그인 필요, 인증서 로그인 필요 추가 권한이 필요한지 판단한다.
 *
 * @return	세션정보+권한결과정보 (예) [userNm,elpUserTypNm,loginType,elpUserId, elpMenuAthoTypCd, 코드(statCode), 메시지(statMesg)]
 * @see     psp.getSession(key, callback)
 * @see     pfheader#scwin.processCertLogin()
 * @see     PSPMAMP01.xml
 * ============= ============ ==========================
 *  Date          Author       Description
 * ============= ============ ==========================
 *  2023.07.01.   안종광        [NELS]최초 생성
 * ============= ============ ==========================
 */
psp.verifySesnMenuAtho = function() {

	var oSSMA = Object.assign({}, psp.getSmplSesn());

	var mPid = psputils.urlparams("m");
	var sPid = psputils.urlparams("s");
	oSSMA["m"] = mPid;

	//0) Home
	if ( scutilo.isEmpty(mPid) || 'home'==mPid.toLowerCase() ) {
		oSSMA["statCode"] = "OK";
		oSSMA["statMesg"] = "전자소송포털 홈페이지";
		return oSSMA;
	}

	var menuInfo = psp.getMenuInfo(mPid);
	if ( null==menuInfo ) {
		oSSMA["statCode"] = "NEED_MN_ATHO";
		_debug("[#vsma] statCode :", oSSMA["statCode"]);
		psp.open_popup("PSPMAMP01", "메뉴권한 안내", oSSMA, 385, 255, function(rslt) {
			psp.go_url(); return;
		});
		return oSSMA;
	}

	var mnAthoTyp = menuInfo["elpMenuAthoTypCd"]; //1,2,3,4
	oSSMA["elpMenuAthoTypCd"] = mnAthoTyp;

	//1) 모두가능한 메뉴임. 세션체크 불필요
	if ( "1"===mnAthoTyp ) {
		oSSMA["statCode"] = "OK";
		oSSMA["statMesg"] = "모두 접근가능한 메뉴입니다.";
		return oSSMA;
	}

	var menuOpt = menuInfo["menuOpt"]; //메뉴옵션 (ex) '{"authHandler": true}'
	var needLgnTypNm = "3"===mnAthoTyp ? "인증서" : "4"===mnAthoTyp ? "아이디" : "";
	//var loginType = oSSMA["loginType"];
	var loginType = psp.getSession("loginType");
	var loginTypNm = "Q"==loginType ? "금융인증서" : "P"==loginType ? "인증서" : "N"==loginType ? "간편인증(인증)" : "M"==loginType ? "간편인증(미인증)" : "G"==loginType ? "아이디" : "(X)";

	var opts = {"n":mPid};
	if ( scutilo.isNotEmpty(sPid) ) {
		opts["t"] = sPid;
	}

	//2) 로그인필요 & 세션없음
	//if ( scutilo.isEmpty(loginType) || !psp.ss.hasData(psp.LS_KEY_USER) ) { //미로그인 상태
	if ( scutilo.isEmpty(loginType) || scutilo.isEmpty(psp.getSession()) ) { //미로그인 상태
		oSSMA["statCode"] = "NEED_INTG_LGN";
		_debug("[#vsma] statCode :", oSSMA["statCode"]);

		psp.open_popup("PSPMAMP01", "로그인 안내", oSSMA, 385, 255, function(rslt) {
			if ( null==rslt || scutilo.isEmpty(rslt.loginType) ) { //취소
				psp.go_url(); return;
			}
			psp.go_url("PSP101M01", opts);
		});
		return oSSMA;
	}

	oSSMA["elpUserId"] = psp.getSession();
	//oSSMA["dispUserTypNm"] = psp.getSession("elpUserTypNm"); // 함수 상단에서 정의한 dispUserTypNm 값 그대로 사용
	oSSMA["userNm"] = psp.getSession("userNm");

	//3) 인증서로그인이 필요 & 아이디로 로그인
	if ( "3"===mnAthoTyp && ("G"==loginType || "M"==loginType) ) {
		oSSMA["statCode"] = "NEED_CERT_LGN";
		_debug("[#vsma] statCode :", oSSMA["statCode"]);

		pdtv.shared["CERT_STATE"] = "NEED_CERT_LGN"; //PSP 임시공유변수(@see pspdefault.jsp)

		let isMenuAuthHandler = false;

		if ( scutilo.isNotEmpty(menuOpt) && true===JSON.parse(menuOpt).authHandler ) {
			isMenuAuthHandler = $p.top().pfwork.scope.scwin.dmfn_authHandler && 'function' == typeof $p.top().pfwork.scope.scwin.dmfn_authHandler;
		}

		if ( true===isMenuAuthHandler ) {
			try {
				oSSMA["statCode"] = "OK";
				oSSMA["statMesg"] = loginTypNm + " 로그인 되었습니다. (권한처리자 있음)";
				$p.top().pfwork.scope.scwin.dmfn_authHandler(oSSMA);
			}
			catch(e) {
				_error("[#vsma] pfw.scw..dmfn_authHandler error :", e.message);
				psp.go_url();
			}
		}
		else {
			psp.open_popup("PSPMAMP01", "인증서 안내", oSSMA, 385, 255, function(rslt) { //(rslt) {"loginType":"","cancel":true}
				if ( null==rslt || scutilo.isEmpty(rslt.loginType) ) {
					psp.go_url(); return;
				}
				if ( "P"==rslt.loginType ) {
					try {
						$p.top().pfheader.scope.scwin.certLgnWithSesn();
					}
					catch(e) {
						_error("[#vsma] pfh..certLgnWithSesn error :", e.message());
						psp.go_url();
					}
				}
				else if ( "M"==rslt.loginType ) {
					alert("행자부 간편인증 로그인 처리는 진행예정입니다.");
					psp.go_url();
				}
			});
			return oSSMA;
		}
	}

	//4) 인증서로그인
	oSSMA["statCode"] = "OK";
	oSSMA["statMesg"] = loginTypNm + " 로그인 되었습니다."; //loginType : N(간편인증+등록), P(공동인증서), Q(금융인증서)
	_debug("[#vsma] oSSMA elpUserTypNm :", oSSMA["dispUserTypNm"]);
	return oSSMA;
};

