/**
 * 레이어 메시지창을 표시하고, 클릭한 결과(true)를 반환
 *
 * (사용법)
 * myFunction = async function() { // async 지정
 *     var msg  =
 *     var rslt = await showMsg(scglblo.MSG.INFO, msg, callback); // await 지정, 콜백함수는 지원하나 비추천
 *     //[확인] 클릭한 경우 처리
 * }
 *
 *
 * (주의1) 동기식으로 사용하기 위해서만 사용
 * (주의2) showMsg()을 사용하는 함수 async 지정, await psp.showMsg 지정
 * (주의3) 콜백함수 지원하지만 비추천 (이유) 콜백과 리턴후의 선후 관계는 보장하지 않음.
 *
 * @param	title	통합공통 메시지 상수 (예) scglblo.MSG.INFO, scglblo.MSG.ERROR
 * @param	message	표시할 메시지
 * @param	cbfn	콜백함수
 * ============= ============ ==========================
 *  Date          Author       Description
 * ============= ============ ==========================
 *  2023.04.21.   안종광        [NELS]최초 생성
 * ============= ============ ==========================
 */
psp.showMsg = async function(title, message, cbfn) {
	var rslt = null;
	if ( cbfn && 'function'== typeof cbfn) {
		rslt = await psp._showMsg(title, message); //scutilo.showMsg(title, message);
		if (true===rslt) {
			cbfn.call(null, rslt);
		}
	}
	else {
		rslt = await psp._showMsg(title, message);
	}
	return rslt;
};

psp._showMsg = function(title, message) {
    return new Promise((resolve, reject )=>{
        scutilo.showMsg(title, message, (p) => { return resolve(true); });
    });
};

