/**
 * 레이어 메시지 확인창을 표시하고, 클릭한 결과(확인=true, 취소=false)를 반환
 *
 * (사용법)
 * myFunction = async function() { // async 지정
 *     var rslt = await psp.showConfirm(scglblo.MSG.INFO, msg); // await 지정, 콜백함수는 지원하지 않음
 *     if (true===rslt) {
 *         //[확인] 클릭한 경우 처리
 *     }
 *     else {
 *         //[취소] 클릭한 경우 처리
 *     }
 * }
 *
 *
 * (주의1) 동기식으로 사용하기 위해서만 사용
 * (주의2) psp.showConfirm()을 사용하는 함수 async 지정, await psp.showConfirm 지정
 * (주의3) 콜백함수 지원X (이유) 콜백과 리턴후의 선후 관계 복잡
 *
 * @param	title		메시지창의 제목
 * @param	message		메시지 문자열
 * @param	_notuse		미사용파라미터 (참고) scutilo.showConfirm 함수의 매개변수 맞추기위함
 * @param	opts		메시지창에 전달할 옵션 (@since 2023-12)
 * ============= ============ ==========================
 *  Date          Author       Description
 * ============= ============ ==========================
 *  2023.04.21.   안종광        [NELS]최초 생성
 * ============= ============ ==========================
 */
psp.showConfirm = async function(title, message, _notuse, opts) {
	let r = await psp._showConfirm(title, message, _notuse, opts);
	return r;
};

psp._showConfirm = function(title, message, _notuse, opts) {
	var options = Object.assign({}, {
		popupName: title,
		focusBtn: null==opts ? '' : (null==opts.focusBtn ? '' : opts.focusBtn)
	});
	options["data"] = opts; //전달된 옵션이 있다면 'data'에 담아서 전달함.
	return new Promise((resolve, reject )=>{
		com.win.confirm(message, (p) => {
			resolve(p.clickValue);
		}, options);
	});
};

// @see scutilo.showConfirm(t, m, f, opts)
// 위 AA공통함수는 opts를 제거해버려서, 데이터를 전달할 방법이 없음 ==> psp용으로 데이터 전달 필요 @since 2023-12
// opts (예) {"ylabel": "확인합니다", "nlabel": "취소합니다", "clabel": "확인!!!"};
psp.confirm = function(title, message, callback, opts) {
	var options = Object.assign({}, {
		popupName: title,
		focusBtn: null==opts ? '' : (null==opts.focusBtn ? '' : opts.focusBtn)
	});
	options["data"] = opts; //전달된 옵션이 있다면 'data'에 담아서 전달함.
	com.win.confirm(message, callback, options); //@see "/psp/cm/scui/SCMsgBox.xml"
};

/**
 * 전달된 스코프ID와 현재 프레임ID를 참조하여 scope 객체를 반환
 *
 * 1) 전달된 스코프ID 우선
 * 2) 위 1)없으면, 현재 프레임ID를 참조
 * 3) 위 2)없으면, 디폴트(mf_pfwork) 스코프 반환
 *
 * @param	sScopeId	참조할 스코프ID (예) "wfm_csBas" (or) "mf_pfwork_wfm_csBas" (or) "pfwork_wfm_csBas"
 * ============= ============ ==========================
 *  Date          Author       Description
 * ============= ============ ==========================
 *  2023.05.02.   안종광        [NELS]최초 생성
 * ============= ============ ==========================
 */
psp.getScope = function(sScopeId) {
	var scopeObj = null;
	var scopeId = psp.getScopeId(sScopeId);
	//#1. 전달된 스코프ID 우선
	try {
		scopeObj = $p.getComponentById(scopeId).scope;
	}
	catch(e) {
		scopeObj = null;
	}
	//#2. 위 1)없으면, 현재 프레임ID를 참조
	if ( null==scopeObj ) {
		try {
			scopeObj = $p.getFrame().scope;
		}
		catch(e) {
			scopeObj = null;
		}
	}
	//#3. 위 2)없으면, 디폴트(mf_pfwork) 스코프 반환
	if ( null==scopeObj ) {
		scopeObj = $p.getComponentById("mf_pfwork").scope;
	}
	return scopeObj;
};

psp.getScopeId = function(sScopeId) { // (예) "wfm_csBas" (or) "mf_pfwork_wfm_csBas" (or) "pfwork_wfm_csBas"
	var scopeId = null;
	//#1. 전달된 스코프ID 우선
	try {
		if ( scutilo.isNotEmpty(sScopeId) ) {
			if ( sScopeId.startsWith("pf") ) {
				scopeId = "mf_" + sScopeId;
			}
			else if ( sScopeId.startsWith("wfm") ) {
				scopeId = "mf_pfwork_" + sScopeId;
			}
			else {
				scopeId = sScopeId.trim();
			}
		}
	}
	catch(e) {
		scopeId = null;
	}
	//#2. 위 1)없으면, 현재 프레임ID를 참조
	if ( null==scopeId ) {
		try {
			scopeId = $p.getFrame().getID();
		}
		catch(e) {
			scopeId = null;
		}
	}
	//#3. 위 2)없으면, 디폴트(mf_pfwork) 스코프 반환
	if ( null==scopeId ) {
		scopeId = "mf_pfwork";
	}
	return scopeId;
};

/**
 * 지정한 키정보등으로 DataMap 객체를 생성하고 그 생성된 객체(자체)를 반환
 *
 * (데이터맵용 키정보)
 * [
 *     { "id":"column1", "name":"column1", "dataType":"text" },
 *     { "id":"column2", "name":"column2", "dataType":"text" }
 * ]
 *
 *
 * (참고1) DataMap ID가 없으면, "dma_" + [8자리생성문자] 로 정함
 * (참고2) 스코프ID가 없으면, "mf_pfwork"를 지정
 * (주의3)
 *
 * @param	arrKeyInfo	DataMap 객체의 키정보 배열 (예)
 * @param	sDataMapId	DataMap 객체의 ID문자열 (예) "dma_docmt"
 * @param	sScopeId	DataMap 객체의 스코프ID문자열 (예) "mf_pfwork"
 * ============= ============ ==========================
 *  Date          Author       Description
 * ============= ============ ==========================
 *  2023.05.01.   안종광        [NELS]최초 생성
 * ============= ============ ==========================
 */
psp.createDma = function(arrKeyInfo, sDataMapId, sScopeId) {
	if (null==arrKeyInfo) {
		_error("[#createDma] NO key infos for DataMap!");
		return null;
	}
	if ( ! Array.isArray(arrKeyInfo) || 1>arrKeyInfo.length ) {
		_error("[#createDma] Key infos for DataMap is NOT array!");
		return null;
	}

	var dmaId = sDataMapId.trim();
	if ( scutilo.isEmpty(sDataMapId) ) {
		try {
			let uuids = crypto.randomUUID().split("-"); //(예) ['67a37baf', '232d', '4a41', '827b', '9b0a4dbed18a']
			dmaId = "dma_" + uuids[1] + "" + uuids[2]; // (예)  dma_232d4a41
		}
		catch(e) {
			dmaId = "dma_" + new Date().getTime().toString().substring(5); // (예)  dma_901777933 //'1682901777933'
		}
	}

	var option = {
		"id": dmaId,
		"type": "dataMap",
		"option":{
			"baseNode":"map"
		},
		"keyInfo": arrKeyInfo
	};

	var scopeObj = psp.getScope(sScopeId);
		scopeObj.$p.data.create(option); //$p.data.create(option);

	var dmaObj = scopeObj.$p.getComponentById(dmaId);
	_debug("[#createDma] DataMap created. ID = ", dmaObj.getID());

	return dmaObj;
};

/**
 * 지정한 키정보등으로 DataList 객체를 생성하고 그 생성된 생성된 객체(자체)를 반환
 *
 * (DataList용 키정보)
