/**
 * 헤더에 {프로그램ID,사용자ID} 값을 설정후,
 * (common.js주석) submission의 공통 설정에서 사용. submisison 통신 직전 호출. return true일 경우 통신 수행, return false일 경우 통신 중단
 *
 * @param    sbmObj    서브미션 객체
 * @see      file:///websquare/config.xml
 * ============= ============ ==========================
 *  Date          Author       Description
 * ============= ============ ==========================
 *  2023.04.11.   안종광        [NELS]최초 생성
 * ============= ============ ==========================
 */
psp._sbm_preSubmission = function(sbmObj) {
	let obj = psp.setHeader(sbmObj); //헤더에 {사용자ID} 값을 설정
	let usrid = obj["SC-Userid"];  //psp.C.REQH_KEY_USRID
	let trcid = obj["SC-Traceid"]; //psp.C.REQH_KEY_TRCID

	try {
		if ( null!=sbmObj && 'submission'==sbmObj._pluginName ) {
			var scReqHds = sbmObj.getScopeWindow().scscrno.getScRequestHeaders();
			if ( ! scReqHds["SC-Traceid"] ) {
				if ( trcid==usrid || scutilo.isEmpty(trcid) ) {
					let pgmid = scReqHds["SC-Pgmid"];
					trcid = `${pgmid}@${usrid}`;
				}
				sbmObj.setRequestHeader({"SC-Traceid": trcid});
				_debug("[#_sbm_preSbm] Traceid :", trcid);
			}
		}
//		var arrDataId = psputils.getSbmRefDcIdLst(sbmObj);
	}
	catch(e) {
		_error("[#_sbm_preSbm]", e.message);
	}

	return true;
};

