/**
 * (확인) websquare/config.xml
 * submission/ajax중 에러가 발생한 경우 에러 처리 함수
 *
 * @param    resObj    responseData 객체
 * @see      this#_sbm_defCallbackSubmission()
 * ============= ============ ==========================
 *  Date          Author       Description
 * ============= ============ ==========================
 *  2023.07.21.   안종광        [NELS]최초 생성
 * ============= ============ ==========================
 */
psp._sbm_comErrorHandler = function(resObj) {
	if (resObj.responseStatusCode == 200) {
		return;
	}
	_error("[#_sbm_comErr] 응답코드 = " + resObj.responseStatusCode);

	var errorMsg;
	try {
		//{"timestamp":1689905838190,"errors":{"errorMessage":"에러가 발생했습니다. 관리자에게 문의바랍니다.","errorCode":"","referedUrl":"http://localhost/psptst/assert/certLogin.on"},"data":null,"token":null}

		var body = JSON.parse(resObj.responseBody);
		errorMsg = body.errors.errorMessage; //+ "\n\n" + "[PSP] 요청경로 : " + body.errors.referedUrl + "\n"; //+ "서버명 : " + body.errors.serverName;
		var referedUrl = body.errors.referedUrl;

		var loginType = psp.session("loginType");
		if(referedUrl.indexOf("/psp9") >= 0 || referedUrl.indexOf("/admindex") >= 0) loginType = pspadmin.session("loginType");
		var need2intgLogin = errorMsg.indexOf("로그인")>=0 && errorMsg.indexOf("아이디")>=0;
		var need2certLogin = errorMsg.indexOf("로그인")>=0 && errorMsg.indexOf("인증서")>=0;

		_debug("[#_sbm_comErr] responseBody :", body);
		_error("[#_sbm_comErr] referedUrl = " + referedUrl);
		_error("[#_sbm_comErr] loginType = " + loginType);


		// 401, 500 인 경우 로그인 페이지로 이동
		if ( 401 == resObj.responseStatusCode || 500 == resObj.responseStatusCode ) { //401 Unauthorized
			_debug("[#_sbm_comErr] 401, 500 인 경우 로그인 페이지로 이동 ==================>");
			if ( scutilo.isEmpty(loginType) ) { //로그인 되지 않은 경우
				errorMsg += "\n\n로그인 화면으로 이동하시겠습니까?";
				scutilo.showConfirm(scglblo.MSG.ERROR, errorMsg, function(rslt) {
					if ( true==rslt.clickValue) {
						//관리자인 경우에 관리자로그인 화면으로 이동
						if(referedUrl.indexOf("/psp9") >= 0) {

							var mPid = psputils.urlparams("m");
							var sPid = psputils.urlparams("s");
							var opts = {"n":mPid};
							if ( scutilo.isNotEmpty(sPid) ) {
								opts["t"] = sPid;
							}

							pspadmin._sessionNullify();
							pspadmin.go_url("PSP901M01", opts);
						} else {
							psp.go_url("PSP101M01");
						}
					}
				});
				return;
			}

			if ( need2certLogin ) {
				_error("[#_sbm_comErr] 오류메시지 :", errorMsg);
				errorMsg += "\n\n인증서로 로그인하시겠습니까?";
				scutilo.showConfirm(scglblo.MSG.ERROR, errorMsg, function(rslt) {
					if ( true==rslt.clickValue) {
						try {
							$p.top().pfheader.scope.scwin.certLgnWithSesn();
						}
						catch(e) {
							alert("오류가 발생하였습니다.\n\n" + e.message);
						}
					}
				});
				return;
			}

			scutilo.showMsg(scglblo.MSG.ERROR, errorMsg);
			return;
		}
		else {
			scutilo.showMsg(scglblo.MSG.ERROR, errorMsg);
		}
	}
	catch(ex) {
		errorMsg = resObj.responseStatusCode + ' Error' + '\n'
					+ "요청경로 : " + resObj.resourceUri;
	}
	_debug("[#_sbm_comErr] resObj.responseStatusCode ==================> " + resObj.responseStatusCode);
	_error("[#_sbm_comErr] 응답메시지 : " + errorMsg);
	//alert("[PSP오류발생]\n\n" + errorMsg);

	return false; //(노트) gcm._sbm_comErrorHandler()

	// 성공인 경우 하단 toast 메시지 출력
	var rsJSON = resObj.responseJSON || null;
	var message = rsJSON && rsJSON.message ? rsJSON.message : '';
	if (message && resObj.responseStatusCode === 200) {
		com.win.showToastMessage(gcm.MESSAGE_CODE.STATUS_SUCCESS, message);
	}
};

/**
 * 간단한 조회 fetch 처리를 진행하며, 2023현재 개발/테스트용 함수
 *
 * @param	url		서비스URL
 * @param	data	요청PayLoad 데이터객체
 * @param	option	window.fetch의 옵션으로 ['headers', 'body']를 제외한 옵션이 전달되면 적용됨
 * @param	headers	window.fetch의 'headers' 옵션으로 값이 전달되면 'headers'에 적용됨
 * @return	Promise 응답값(json객체)
 * @throw	오류시 psp.PspError 객체를 throw
 * ============= ============ ==========================
 *  Date          Author       Description
 * ============= ============ ==========================
 *  2023.12.14.   안종광        [NELS]최초 생성
 * ============= ============ ==========================
 */
psp.fetch = async function(url="/psp/pspcom/datetime.on", data={}, option={}, headers) {
	let [pgmid] = url.split(/\//).slice(-1);
	let usrid = psp.session(); usrid = scutilo.isEmpty(usrid) ? "anonymous" : usrid;
	var _headersDefault = {
		"Content-Type": "application/json;charset=UTF-8", // || 'application/x-www-form-urlencoded' application/json;charset=UTF-8
		"SC-Userid": usrid,
		"SC-Pgmid": pgmid,
		"SC-Traceid": `${pgmid}@${usrid}`,
	};
	var _headers = Object.assign(_headersDefault, headers);  //전달된 헤더옵션이 있다면 적용됨 (참조) 'SC-Userid'등이 전달되면 해당 값을 사용함

	var _fetchOptionDefault = {
		method: "POST", // *GET, POST, PUT, DELETE 등
		mode: "cors", // no-cors, *cors, same-origin
		cache: "no-cache", // *default, no-cache, reload, force-cache, only-if-cached
		credentials: "same-origin", // include, *same-origin, omit
		redirect: "follow", // manual, *follow, error
		referrerPolicy: "no-referrer", // no-referrer, *no-referrer-when-downgrade, origin, origin-when-cross-origin, same-origin, strict-origin, strict-origin-when-cross-origin, unsafe-url
		//headers: { "Content-Type": "application/json" }, // 'Content-Type': 'application/x-www-form-urlencoded',
		//body: JSON.stringify(data), // body의 데이터 유형은 반드시 "Content-Type" 헤더와 일치해야 함
	};
	var _fetchOption = Object.assign(_fetchOptionDefault, option); //전달된 옵션이 있다면 적용됨 (제외) body, headers
		_fetchOption['headers'] = _headers;	            // 'headers'에 적용
		_fetchOption['body']    = JSON.stringify(data); //data 파라미터가 'body'에 적욛됨
	var _url = (url.startsWith("/") ? url : "/"+url);
		_url = (_url.startsWith("/psp/") ? _url : "/psp" + _url);

	const response = await fetch(_url, _fetchOption);
	const result   = await response.json();
	_debug("[#p.ftch] ", result);
	WebSquare.layer.hideProcessMessage();

	if ( 200!=result.status ) {
		let errMsg = result.errors.errorMessage;
		let yn = await psp.showMsg(scglblo.MSG.ERROR, "처리중 오류가 발생하였습니다.\n\n" + errMsg);
		throw new psp.PspError(result); //Error(errMsg);
	}
	return result; //(주의) async 선언된 함수로 Promise가 반환됨
};


/**
 * PSP 오류객체
 *
 * @param	objError	오류응답데이터(json객체)
 *          (예) {
 *               "timestamp":1702517474399,
 *               "errors": {
 *                   "errorMessage":"에러가 발생했습니다. 관리자에게 문의바랍니다.",
 *                   "errorCode":"",
 *                   "referedUrl":"http://localhost/pspcom/datetime1.on"
 *               },
 *               "data":null,
 *               "token":null
 *               }
 *
 * ============= ============ ==========================
 *  Date          Author       Description
 * ============= ============ ==========================
 *  2023.12.14.   안종광        [NELS]최초 생성
 * ============= ============ ==========================
 */
psp.PspError = function(objError) {
	this.timestamp = new Date().getTime();
	this.code      = "PE000";
	this.message   = "오류가 발생했습니다.";
//	if ( null==objError || 0===Object.keys(objError).length ) {
//		this.message = "오류가 발생했습니다.";
//	}
	if ( null!=objError ) { // && 0<Object.keys(objError).length
		if ( objError.errors ) {
			this.message = objError.errors.errorMessage;
			this.code    = objError.errors.errorCode;
			this.refered = objError.errors.referedUrl;
			if ( objError.timestamp ) {
				this.timestamp = objError.timestamp;
			}
		}
	}
	_info("[#PspError] ", this);
};

