/**
 * 보안키패드 호출
 * - PC환경이면 npPfsStartup() 호출(nppfs-1.13.0.js) - nProtect
 * - 모바일환경이면 $h.mtranskey.showSecureKeypad() 네이티브 호출 - Raon
 *
 * ============= ============ ==========================
 *  Date          Author       Description
 * ============= ============ ==========================
 *  2025.01.13.   이상엽        [NELS]최초 생성
 * ============= ============ ==========================
 */
psp.npPfsStartup = function(form, firewall, securekey, fds, keypad, e2eattr, e2eval) {

	// 모바일
	if (psp.env.isMobileApp()) {

		// nProtect 적용 객체 대상으로 Raon KeyPad 도 적용
		// 적용대상 선청
		var secureKeypadObjs = form.querySelectorAll('[npkencrypt]');
		for (var secureKeypad of secureKeypadObjs) {
			// 상태 확인
			var state = secureKeypad.getAttribute('npkencrypt');
			if (state == 'on') {
				// 대상에 이벤트 핸들러 추가
				if (secureKeypad.classList.contains('click-event-on')) {
					break;
				}
				secureKeypad.classList.add('click-event-on');
				var clickCallback = function(e) {
					var _this = this;
					var callback = function(result) {
						// 대상에 키패드 입력값 설정
						_this.value = result.data.plainData || '';
						_this.blur();
					}
					var options = {
						maxlength: _this.maxLength,
						algorithmType: 0
					};
					if (psp.isIosApp()) {
						// iOS keypad-type 옵션
						options.keypadtype = _this.getAttribute('data-keypad-type') == 'num' ? 1 : 0;
					}
					else {
						// 안드로이드 keypad-type 옵션
						options.keypadtype = _this.getAttribute('data-keypad-type') == 'num' ? 4 : 5;
					}
					// 보안키패드 on
					$h.mtranskey.showSecureKeypad(callback, options);
				};
				secureKeypad.addEventListener('focus', clickCallback);
			}
		}
	}
	// PC
	else {
		npPfsStartup(form, firewall, securekey, fds, keypad, e2eattr, e2eval);

		//  npPfsStartup(document.formtag, false, true, false, true, "npkencrypt", "on");
		//  1. form 양식 : 기본값 DOM Document 상의 첫번째 form
		//  2. 개인방화벽 사용여부 : 기본값 false
		//  3. 키보드보안 사용여부 : 기본값 false  -  제품 설치 확인 관련 옵션  무조건 에이전트가 설치 되어야  사용 가능 ,
		//  4. 단말정보수집 사용여부 : 기본값 false
		//  5. 마우스입력기 사용여부 : 기본값 false
		//  6. 키보드보안 E2E 필드 설정 속성명 : 기본값 "npkencrypt"
		//  7. 키보드보안 E2E 필드 설정 속성값: 기본값 "on"
		// *** 키보드 보안 사용 true 시 프로그램 설치 되어있지 않으면 설치 페이지로 이동하겠냐는 confirm 발생함
	}
}

/**
 * <pre>
 * Opener 또는 Parent의 함수를 호출한다.
 *
 * </pre>
 *
 * @parameter [String] functionName : 서버 경로
 * @parameter [Object] param : 파미터 {aaa : 111, bbb : 222, ccc : 333}
 * @return N/A
 * @see com.win.openPopup
 * ============= ============ ==========================
 *  Date          Author       Description
 * ============= ============ ==========================
 * 2024.03.07.   전명호         [NELS] 최초생성
 * 2025.01.24.   김영규         [NELS] 포팅
 * ============= ============ ==========================
 */
psp.callOpenerFunction = function (functionName, param) {
//	console.log("psp.callOpenerFunction functionName = " + functionName);
	if (!functionName.startsWith("mf_")) {
		functionName = "mf_" + functionName;
	}
    var funcArr = functionName.split(".");
    var caller = opener || parent;
    if (caller[funcArr[0]] && typeof caller[funcArr[0]][funcArr[1]] == "function") {
        caller[funcArr[0]][funcArr[1]](param);
    }
    else {
        console.log('Function Name Error : ' + functionName)
    }
};


