psp.getDeepLinkParameterCallbackFn = function(result) {
	console.log("psp.getDeepLinkParameterCallbackFn");
	WebSquare.layer.hideProcessMessage();
	const param = result.data.parameter;
	if (scutilo.isEmpty(param)) {
		return;
	} else if (param === "csSearch") { // qr 파라미터가 csSearch인 경우 메인화면으로 이동
    	$h.common.resetParameter();
    	// TODO : 현재페이지가 메인페이지면 수행 x
    	psp.go_url();
    } else {
        // 로그인여부 체크 후 로그인 및 발급문서조회
        if (scutilo.isNotEmpty(psp.verifySesnMenuAtho().elpUserId)) {
			$h.common.resetParameter();
            // resetParameter 딥링크 파라미터 초기화
            //위에서 로그인 후 다시 실행하면서 당사자명 입력받고 발급문서조회한다.
            let encDocIssuNo = param;
            let docIssuNo = scutilo.decode(encDocIssuNo);       //
            // 당사자명 입력팝업 호출
            let data = {
                "docIssuNo": docIssuNo,             //문서발급번호
                "btprtNm": "",                      //입력받을 당사자명
                "btprtNmCallback": "docViewer",     //당사자명 입력받고 호출하는 콜백
                "popupId": "PMBbtprtNm"
            }
            let options = {
                    id : "PSPbtprtNm",
                    popupName : "당사자명 입력",
                    modal : true,
                    type : "wframePopup",
                    dataObject: data
            };

            //열려있는 팝업 닫기
        	$p.getPopupList().forEach( function (_o) {
        		$p.closePopup(_o.id);
        	});

            //const href =  !psp.isIosApp() ? location.href.substr(0, location.href.indexOf("psp")+3) : $p.top().scwin.IOS_HREF ? $p.top().scwin.IOS_HREF : '';
            const href = location.href.substr(0, location.href.indexOf("psp")+3);

            setTimeout(function() {
            	//com.win.openPopup(href + "/ui/psppop/PSPbtprtNm.xml", options, data);	// 로컬호스트
            	psp.pspPbtprtNmPopupMove(href + "/ui/psppop/PSPbtprtNm.xml", options, data);
            }, 500);
        } else {        // 로그인 안한 상태 : 로그인화면으로 이동
            psp.go_url("PSP101M01");
        }
    }
}

