/**
 * (모바일용) 네이티브 앱 버전 최신여부
 * 현재 실행 중인 앱이 최신인 경우 : true / 최신이 아닐 경우 : false
 * ============= ============ ==========================
 *  Date          Author       Description
 * ============= ============ ==========================
 *  2025.02.18.   김영규       [NELS]최초 생성
 * ============= ============ ==========================
 */
psp.storeVersionPromise = function() {
	return new Promise ((resolve, reject) => {
		if (!psp.isMobileApp()) {
			reject();
		}
		$h.common.storeVersion((result)=>{
			if (psp.isIosApp()) {
				result.data.storeVersion;
				result.data.appVersion;
				if (result.data.appVersion.localeCompare(result.data.storeVersion, undefined, {numeric: true}) >= 0) {
					resolve(true);
				} else {
					resolve(false);
				}
			} else {
				resolve(Number(result.data.currentAppVersion) >= result.data.storeVersion);
			}
		});
	});
}

/**
 * (모바일용) 네이티브 앱 토스트 메시지(하단 짧은 알림메시지)
 * param : time(int 정수형 시간에 비례)
 * ============= ============ ==========================
 *  Date          Author       Description
 * ============= ============ ==========================
 *  2025.02.27.   김영규       [NELS]최초 생성
 * ============= ============ ==========================
 */
psp.toastPromise = function(message, time) {
//	console.log("psp.toastPromise param \n message : " + message + "\n time :" + time);
	return new Promise ((resolve, reject) => {
		if (!psp.isMobileApp()) {
			reject("this is not app");
		}
		if (!$h.view.toast) {
			reject("this app version has no toast function");
		}
		time = time ? time : 0;
		$h.view.toast((result)=>{
			if (result.statusCode === 1000) {
				resolve();
			} else {
				reject("toast function is failed");
			}
		}, {message:message, time:time});
	});
}

