 * 로컬스토리지 get/set/others 래핑 객체
 *
 * (사용법) psp.ls.get(key, parseOrNot)
 * (사용법) psp.ls.hasData(key)
 * (사용법) psp.ls.set(key, val)
 * (사용법) psp.ls.remove(key1, key2, ...)
 *
 * @param	key    키문자열
 * @param	val    값(문자열 또는 기타는 객체)
 * ============= ============ ==========================
 *  Date          Author       Description
 * ============= ============ ==========================
 *  2023.07.21.   안종광        [NELS]최초 생성
 * ============= ============ ==========================
 */
psp["ls"] = { //localStorage
		/**
		 * 로컬스토리지에 해당 키로 값을 설정 (주의) 키 또는 값이 null이면 저장X
		 *
		 * @param	key    키문자열
		 * @param	val    값(문자열 또는 기타는 객체)
		 * ============= ============ ==========================
		 *  Date          Author       Description
		 * ============= ============ ==========================
		 *  2023.07.21.   안종광        [NELS]최초 생성
		 * ============= ============ ==========================
		 */
		set : function(key, val) {
			if ( scutilo.isEmpty(key) || null==val ) {
				return;
			}
			if ( 'string'==typeof val ) {
				WebSquare.localStorage.setItem(key, val);
			}
			else {
				WebSquare.localStorage.setItem(key, JSON.stringify(val));
			}
		}
		,
		/**
		 * 로컬스토리지에 해당 키로 값을 조회하여 반환
		 *
		 * @param	key         조회할 키문자열
		 * @param	parseOrNot  디폴트 true, false이면 무조건 문자열로 반환
		 * @return	해당 키로 값(디폴트 객체이면 객체타입, 문자열이면 문자열타입)
		 * ============= ============ ==========================
		 *  Date          Author       Description
		 * ============= ============ ==========================
		 *  2023.07.21.   안종광        [NELS]최초 생성
		 * ============= ============ ==========================
		 */
		get : function(key, parseOrNot) {
			if ( scutilo.isEmpty(key) ) {
				return null;
			}
			var val = null;
			try {
				val = ( null==parseOrNot || true==parseOrNot )
					? JSON.parse(WebSquare.localStorage.getItem(key))
					: WebSquare.localStorage.getItem(key);
			}
			catch(e) {
				_error("[#ls.get]", e.message);
				val = WebSquare.localStorage.getItem(key); //혹시 파싱오류면 그대로 문자열값으로 반환
			}
			return val;
		}
		,
		/**
		 * 로컬스토리지에 해당 키로 값이 정상적으로 존재하는지 체크
		 *
		 * @param	key         조회할 키문자열
		 * @return	해당 키로 정상적인 데이터가 존재하면 true
		 * ============= ============ ==========================
		 *  Date          Author       Description
		 * ============= ============ ==========================
		 *  2023.08.11.   안종광        [NELS]최초 생성
		 * ============= ============ ==========================
		 */
		hasData : function(key) {
			if ( scutilo.isEmpty(key) ) {
				return null;
			}
			var strData = WebSquare.localStorage.getItem(key);
			if ( scutilo.isEmpty(strData) || "null"==strData || "undefined"==strData ) {
				return false;
			}
			return true; //! ( scutilo.isEmpty(strData) || "null"==strData || "undefined"==strData );
		}
		,
		/**
		 * 로컬스토리지에 전달된 모든 키를 삭제
		 *
		 * @param	args    삭제할 키문자열(가변배열)
		 * ============= ============ ==========================
		 *  Date          Author       Description
		 * ============= ============ ==========================
		 *  2023.07.21.   안종광        [NELS]최초 생성
		 * ============= ============ ==========================
		 */
		remove: function() {
			try {
				for(let i=0; i<arguments.length; i++) {
					WebSquare.localStorage.removeItem(arguments[i]);
				}
			}
			catch(e) {
				_debug("[#ls.rem]", e.message);
			}
		}
};

