 * <pre>
 * 전자소송포털 [STG공통, PSP공통] 데이터 로드 및 제공함수
 *
 * 1) 해당 데이터가 없으면, 조회
 * 2) 조회된 데이터는 localStorage에 저장 : 키구조는 "pd." + 시스템코드 + "." + [코드 등] (예) "pd.STG.cort",
 * 3) 용량상의 제한으로 많이 사용하는 데이터를 선정하여 저장하며, 데이터도 실제사용하는 데이터만(예, {코드, 코드명, 사용여부 등})
 * </pre>
 */
psp["data"] = {

	key_courts : "pd.STG.court"
	,
	/**
	 * 아래 등록된 키만 localStorage에 저장 (사용예) STG-SYSTM_CD, LSC-CS_DVS_CD
	 */
	allow_code_groups : [ "SYSTM_CD", "CS_DVS_CD" ]
	,
	/**
	 * 법원코드 전체 목록을 반환
	 * (사용예) var courtList = psp.data.courts()
	 */
	courts : function() {
		var sCourt = WebSquare.localStorage.getItem(psp.data.key_courts);
		var oCourt = null;
		if ( scutilo.isEmpty(sCourt) ) {
			oCourt = sccorto.getCortLst();
			if ( null!=oCourt ) {
				WebSquare.localStorage.setItem(psp.data.key_courts, JSON.stringify(oCourt));
			}
		}
		else {
			oCourt = JSON.parse(sCourt);
		}
		return oCourt;
	}
	,
	/**
	 * 통합공통코드를 조회하여 localStorage에 저장하게될 키명
	 * 참고) 키형식 : "pd." + [시스템코드] + "." + [코드그룹코드] (예) "pd.STG.SYSTM_CD"
	 */
	key_of_codes : function(systm, codeGroup) {
		let _scd = scutilo.isEmpty(systm) ? "STG" : systm.toUpperCase();
		let _cdg = scutilo.isEmpty(codeGroup) ? "SYSTM_CD" : codeGroup.toUpperCase();
		if ( ! psp.data.allow_code_groups.includes(_cdg) ) {
			return null; //허용되지 않은 코드그룹은 localStorage에 저장하지 않음.
		}
		var k = "pd." + _scd + "." + _cdg; //디폴트 [pd.STG.SYSTM_CD]
		return k;
	}
	,
	/**
	 * [시스템, 코드그룹]의 코드 목록을 반환. (주의) 시스템코드가 다르면 데이터 없음. '사건구분코드'=("LSC", "CS_DVS_CD")
	 * (사용예)
	 * var sysCdList = psp.data.codes(); //디폴트 시스템코드목록
	 * var cdclist = psp.data.codes("LSC", "CS_DVS_CD");
	 */
	codes : function(systm, codeGroup) {
		var skey = psp.data.key_of_codes(systm, codeGroup);
		var oCodes = null;
		var sCodes = WebSquare.localStorage.getItem(skey);
		if ( scutilo.isEmpty(sCodes) ) {
			let _sys = scglblo.SYSTM[scutilo.isEmpty(systm) ? "STG" : systm.toUpperCase()];
			let _cdg = scutilo.isEmpty(codeGroup) ? "SYSTM_CD" : codeGroup.toUpperCase();
			let _url = scglblo.getCtxtPathUrl("/scframe/lib/sccd/list.on");
			if ( ! _url.startsWith(psp.CONTEXT_ROOT) ) {
				_url = psp.CONTEXT_ROOT + _url;
			}
			_trace("[cdp#codes] url :", _url);
			com.executeAjax({
				action: _url,
				mode: "synchronous",
				mediatype: gcm.DEFAULT_OPTIONS_MEDIATYPE,
				requestData: JSON.stringify({"intgGrpCdLst": _sys +"-"+_cdg}), //예) { "intgGrpCdLst": "STG-SYSTM_CD" }
				success: function(_data) {
					oCodes = _data.responseJSON.data.sccdLst;
					if ( null!=oCodes && oCodes.length>0  && scutilo.isNotEmpty(skey) ) {
						WebSquare.localStorage.setItem(skey, JSON.stringify(oCodes));
					}
				}
			});
		}
		else {
			oCodes = JSON.parse(sCodes);
		}
		return oCodes;
	}
	,

	/**
	 * 사건구분코드의 명칭을 반환 (예) '001'(3자리문자열) --> '가단'
	 * (사용예) var cdcnm = psp.data.getCsDvsNm('001'); == '가단'
	 */
	getCsDvsNm : function(csDvsCd) {
		if ( scutilo.isEmpty(csDvsCd) || scutilo.getAllTrim(csDvsCd).length!=3 ) {
			return csDvsCd;
		}
		var cdc = scutilo.getAllTrim(csDvsCd);
		var cdclist = psp.data.codes("LSC", "CS_DVS_CD");
		var cdnm = csDvsCd;
		try {
			cdclist.forEach(function(cdcinfo) {
				if ( cdcinfo.intgCd == csDvsCd ) {
					cdnm = cdcinfo.intgCdNm;
					return false; //break;
				}
			});
		}
		catch(e) {
			_trace("[#getCsDvsNm]" + e);
		}
		return cdnm;
	}
	,

	/**
	 * 사건구분번호를 코드명을 포함한 번호로 변환하여 반환
	 * (사용예) psp.data.getCsNoNm('20220010123456'); == '2022가단0123456'
	 */
	getCsNoNm : function(csDvsNo) {
		if ( scutilo.isEmpty(csDvsNo) || scutilo.getAllTrim(csDvsNo).length<7 ) {
			return csDvsNo;
		}
		var cdcnm = psp.data.getCsDvsNm(csDvsNo.substring(4,7));
		return csDvsNo.substring(0,4) + cdcnm + csDvsNo.substring(7);
	}
	,

	/**
	 * 사건구분번호를 코드명을 포함한 번호로 변환하여 반환2
	 * (사용예) psp.data.getCsNoNm('20220010000010'); == '2022가단10'
	 */
	getCsNoNm2 : function(csDvsNo) {
		if ( scutilo.isEmpty(csDvsNo) || scutilo.getAllTrim(csDvsNo).length<7 ) {
			return csDvsNo;
		}
		var cdcnm = psp.data.getCsDvsNm(csDvsNo.substring(4,7));
		return csDvsNo.substring(0,4) + cdcnm + (csDvsNo.substring(7)*1);
	}


};
