/**
 * <pre>
 * 조회 조건 YYYMMDD 형식의 시작 날자와 종료날자 조회조건기준  31일 계산
 *
 * @param sday(조회시작일자), eday(조회종료일자), maxCnt(최대조회기간)
 *
 * @return ture,false
 * </pre>
 */
pspdate.cfChkMaxDay  = function(sday, eday, maxCnt) {
	if (sday.length == 8) {
		sday = sday.replace(/(\d{4})(\d{2})(\d{2})/,"$1.$2.$3");
	}
	if (eday.length == 8) {
		eday = eday.replace(/(\d{4})(\d{2})(\d{2})/,"$1.$2.$3");
	}
	var startDate = new Date(parseInt(sday.substring(0,4),10),(parseInt(sday.substring(5,7),10) - 1), parseInt(sday.substring(8,10),10));
	var endDate   = new Date(parseInt(eday.substring(0,4),10),(parseInt(eday.substring(5,7),10) - 1), parseInt(eday.substring(8,10),10));
	var diffDays  = (endDate.getTime() - startDate.getTime()) / (24*60*60*1000);

	// 최대조회기간에서 -1을 하여 일자를 구함
	//ex) maxCnt가30 경우 29로 해야 최대조회기간으로 됨
	if (diffDays > (maxCnt - 1)) {
		return false;
	}
	return true;
}


/**
 * <pre>
 * 선택한 날자가 미래일자인지를 체크한다.
 *
 * @param sday(조회시작일자)
 * @param boolean {showMsgYn: 메세지 표시 여부(true: 표시, false: 미표시)}
 * @return ture,false
 * ============= ============ ==========================
 *  Date          Author       Description
 * ============= ============ ==========================
 *  2023.09.01.   김영범       수정 - 메세지 표시 여부 추가
 * ============= ============ ==========================
 * </pre>
 */
pspdate.cfChkFutureDay = function(sday, showMsgYn){
    var vhday = pspdate.cfGetToday(""); // 현재일자 가져오기
    vhday = new Date(parseInt(vhday.substring(0,4),10),(parseInt(vhday.substring(4,6),10) - 1), parseInt(vhday.substring(6,8),10));

    var vsday = sday.replace(/\./g,"");
    vsday = new Date(parseInt(vsday.substring(0,4),10),(parseInt(vsday.substring(4,6),10) - 1), parseInt(vsday.substring(6,8),10));
    var diffDays = (vhday.getTime() - vsday.getTime()) / (24*60*60*1000);

    if(diffDays < 0 ){
    	showMsgYn = (showMsgYn == undefined)? true : showMsgYn; //default: 표시

