		//convBfrRrno = "20" + rrno1.substr(0, 2) + "-" + rrno1.substr(2, 2) + "-" + rrno1.substr(4, 2);
		convBfrRrno = "20" + rrno1;
	}

	resultStr = (parseInt(currentDate) - parseInt(convBfrRrno)) + "";

	if (resultStr.length < 8) {
		for (var i = 0; i < 8 - resultStr.length; i++) {
			resultStr = "0" + resultStr;
		}
	}

	resultYear = parseFloat(resultStr.substr(1, 2));
	resultDay = parseFloat(resultStr.substr(3, 5));

	if (resultYear == 19 && resultDay > 0) {// 20살 생일 경과, 미성년 기준 19세로 변경
