/**
 * <pre>
 * 날자와 시간을 가져오는 함수
 * </pre>

 * @see ECF000.cfGetTimeStamp
 * ============= ============ ==========================
 *  Date          Author       Description
 * ============= ============ ==========================
 *  2023.07.05.   전성영       [NELS]최초 생성
 * ============= ============ ==========================
 */
pspdate.cfGetTimeStamp = function(e) {
  var vStamp = "";
  var vTDate = new Date();

  var vCurYear = vTDate.getFullYear();
  var vCurMonth = vTDate.getMonth()+1;
  var vCurDay= vTDate.getDate();
  var vCurHour = vTDate.getHours();
  var vCurMin = vTDate.getMinutes();
  var vCurSec = vTDate.getSeconds();

  if ((vCurMonth.toString()).length == 1) {
    vCurMonth  = "0"+vCurMonth;
  }
  if ((vCurDay.toString()).length == 1) {
    vCurDay  = "0"+vCurDay;
  }
  if ((vCurHour.toString()).length == 1) {
    vCurHour  = "0"+vCurHour;
  }
  if ((vCurMin.toString()).length == 1) {
    vCurMin  = "0"+vCurMin;
  }
  if ((vCurSec.toString()).length == 1) {
    vCurSec  = "0"+vCurSec;
  }

  vStamp = "" + vCurYear + vCurMonth + vCurDay + vCurHour + vCurMin + vCurSec;

  return vStamp;
}

/**
 * <pre>
 * 시간 자동완성
 *
 * 1-3자리의 숫자 데이터에 대해 0을 추가하여 4자리의 데이터로 자동완성한다.
 * 웹스퀘어의 dataType time 포맷 자동완성이 실제 값은 변경하지 않으므로 실제 값을 4자리로 변경 위해 사용한다.
 *
 * ex)
 * pspdate.getTimeAutoCmplt('7') = '0700'
 * pspdate.getTimeAutoCmplt('11') = '1100'
 * pspdate.getTimeAutoCmplt('123') = '0123'
 *
 * @param 1~3자리의 숫자
 * @return 4자리의 숫자 문자열
 *
 * </pre>
 *
 * ============= ============ ==========================
 *  Date          Author       Description
 * ============= ============ ==========================
 *  2024.03.19.   백인호       [NELS]최초 생성
 * ============= ============ ==========================
 */
pspdate.getTimeAutoCmplt = function(param) {
	// null 또는 빈값일 경우 return
	if (param == null || String(param).trim() == "") {
		return param;
	}

	// 숫자가 아닌 경우 return
	if (isNaN(param)) {
		return param;
	}

	// 값 길이가 유효하지 않은 경우 return
	const paramStr = String(param);
	const len = paramStr.length;
	if (len < 1 || len > 4) {
		return param;
	}

	// 값 리턴
	let result = paramStr;
	if (len == 1) {
		result = "0" + paramStr + "00";
	} else if (len == 2) {
		result = paramStr + "00";
	} else if (len == 3) {
		result = "0" + paramStr;
	} else {
		result = paramStr;
	}
	return result;
}

