    }

    var comp = psp.componentById(frameId + "_" + compId, "");
    compId = comp.id.replace(scopeId + "_" + frameId + "_", "");
    var dataId = compId + String(Math.random());

    var dataLstId = pspscrn.createDataLst({
      scopeId: scopeId,
      dataId: dataId,
      dataLstFieldInf: pspscrn.getMainDataClct(pspscrn.CD_DATA_ID).cellIdList,
      getDataFunc: _self.getIntgCdLst.bind(_self, intgGrpCd),
    });
    pspscrn.bindComponentData({
      scopeId: scopeId,
      compId: compId,
      dataLstId: dataLstId,
      label: 'intgCdNm',
      value: 'intgCdNm',
    });
  }
};


