        scglblo.SYSTM.LBA // 본안사무
      , scglblo.SYSTM.LDC // 독촉사무
      , scglblo.SYSTM.LHB // 형사보호사무
      , scglblo.SYSTM.LHG // 형사공판사무
      , scglblo.SYSTM.LHP // 회생파산사무
      , scglblo.SYSTM.LHY // 형사약식사무
      , scglblo.SYSTM.LJH // 집행사무
      , scglblo.SYSTM.LKS // 기타사건사무
      , scglblo.SYSTM.LKT // 공탁사무
      , scglblo.SYSTM.LSC // 신청사무
      , scglblo.SYSTM.LYJ // 영장
      , scglblo.SYSTM.LGS // 즉결
    ].join("|");

    var intgGrpCds = [
        "DXDY_RSLT_CD"          // 기일결과코드
        ,"DXDY_KND_CD"          // 기일종류코드
        ,"DXDY_LTR_DSGN_RSN_CD" // 기일추후지정사유코드
        ,"BTPRT_DVS_CD"         // 당사자구분코드
        ,"ORDDCS_DVS_CD"        // 명령결정구분코드
        ,"OFDOC_DVS_CD"         // 문건구분코드
        ,"DOC_CL_CD"            // 문서분류코드
        ,"DLVRBL_DVS_CD"        // 송달물구분코드
        ,"DLVRPL_DVS_CD"        // 송달처구분코드
        ,"INVRCD_KND_CD"        // 조서종류코드
        ,"ULTMT_DVS_CD"         // 종국구분코드
        ,"ENTRS_KND_CD"         // 촉탁종류코드
        ,"APLY_CS_KND_CD"       // 신청사건종류코드
        ,"AUCTN_CS_NM_CD"       // 경매사건명코드
        ,"ETEXEC_CS_NM_CD"      // 기타집행사건명코드
    ].join("|");

     if(systmCd.match(systmCds) && intgGrpCd.match(intgGrpCds)) {
         // 타입코드
         pspscrn.setSccdoDsCommCdByTaskCd (systmCd, jdcpcOfcwkTaskTypCd, intgGrpCd, ds);
     }
     else {
         // 시스템코드ds
         pspscrn.setSccdoDsCommCdBySystemCd (systmCd, intgGrpCd, ds);
     }
}


