            "EML_DMN_ADDR_DVS_CD-" + sbx_eml1.getID() + scglblo.DELIMITER.COMMA + sbx_eml2.getID()]],
        ["PSP", ["RPRSV_JBGRD_CD-" + sbx_orgnzRprs.getID()]]]; *
 *
 * ============= ============ ==========================
