pspscrn.selMyCortCdLst = function(dcId, elctnLwstTaskTypCd, pgmId, sim, isAll, isMyCort){
	if(scutilo.isEmpty(isMyCort)) {
		isMyCort = "Y";
	}
    var resultMyCortCd = null;
    com.executeAjax({
        action: psp.CONTEXT_ROOT + "/pspcom/selectMyCortCdLst.on",
        mode: "synchronous",
        method: "POST",
        mediatype: gcm.DEFAULT_OPTIONS_MEDIATYPE,
        requestData: JSON.stringify({
          elctnLwstTaskTypCd: elctnLwstTaskTypCd,
            pgmId: pgmId,
            sim: sim,
            isAll: isAll,
            isMyCort: isMyCort,
        }),
        success: function(_data) {
          resultMyCortCd = _data.responseJSON.data.result;
        },
        error: function(e) {
            alert("error code : " + e.responseStatusCode);
        },
    });

    //jsonData 생성
    var jsonData = JSON.parse(JSON.stringify(resultMyCortCd));

    //DataCollention에 값 설정
    dcId.setJSON(jsonData);
};

