/**
 * <pre>
 * psp 용 웹스퀘어 컴포넌트에 바인딩 공통용 함수
 * </pre>
 * @parameter
 *  scopeId(화면 프레임 ID) : 필수
 *  compId(바인딩 할 component id) : 필수
 *  dataLstId(Component 바인딩 할 DataList ID) : 필수
 *  label(출력 Label id) : 필수
 *  value(철략 Value id) : 필수
 *
 *
 * ============= ============ ==========================
 *  Date          Author       Description
 * ============= ============ ==========================
 * 2023.02.21.   이석원         [NELS] 최초생성
 * ============= ============ ==========================
 *
 */
pspscrn.bindComponentData = function(param) {
    var sc = $p.getComponentById(param.scopeId);
    if(! sc) {
        throw new Error("pspscrn.bindComponentData error - scopeId 값을 추가해주세요. param :", param)
    }
    else {
        if(! param.compId) {
            throw new Error("pspscrn.bindComponentData error - compId 값을 추가해주세요. param :", param);
        }
        else {
            var compArr = (param.compId).replaceAll(" ", "").split(",");
            for(var idx in compArr) {
                //컴포넌트 ID
                var aTmpCompId = compArr[idx].split(':');
                var tmpCompId = aTmpCompId[0];
                var tmpColId = aTmpCompId.length > 1 ? aTmpCompId[1] : null;
                var comp = sc.scope.$p.getComponentById(tmpCompId);
                if (null==comp) { comp = $p.getComponentById(tmpCompId); }
                if(comp) {
                    var compType = comp.getPluginName();
                    //그리드
                    if(compType === 'gridView') {
                        //setColumnNodeSet( colIndex , nodeset , label , value )
                        comp.setColumnNodeSet(tmpColId, "data:" + param.dataLstId, param.label, param.value);
                    }
                    //그리드 외 컴포넌트
                    else {
                        //setNodeSet( nodeset , label , value )
                        comp.setNodeSet("data:" + param.dataLstId, param.label, param.value);
                    }
                } else {
                    throw new Error("pspscrn.bindComponentData error - 컴포넌트를 찾을수 없습니다. param :", param);
                }
            }
        }
    }
};

/**
 * 웹스퀘어 컴포넌트에 지정한 데이터리스트를 바인딩 처리
 *
 * @param	componentId		컴포넌트ID
 * @param	dataListId		데이터리스트ID
 * @param	labelColumnId	라벨로 사용될 데이터리스트 컬럼ID
 * @param	valueColumnId	값으로 사용될 데이터리스트 컬럼ID
 * @param	scopeId			스코프ID(옵션)
 * @see		pspscrn.bindComponentData(param)
 * ============= ============ ==========================
 *  Date          Author       Description
 * ============= ============ ==========================
 * 2023.08.24.    안종광        [NELS] 최초생성
 * ============= ============ ==========================
 */
pspscrn.bindData = function(componentId, dataListId, labelColumnId, valueColumnId, scopeId) {
	var obj = $p.getComponentById(componentId);
	try {
		if ( null==obj ) {
			obj = psp.componentById(componentId, scopeId);
		}
		var pnm = obj.getPluginName();
		'gridView'==pnm ? obj.setColumnNodeSet(componentId, "data:"+dataListId, labelColumnId, valueColumnId) //TODO: 그리드뷰는 수정필요 id부분
						: obj.setNodeSet("data:"+dataListId, labelColumnId, valueColumnId);
	}
	catch(e) {
		_error("[s#bindData]", e.message);
		throw new Error("컴포넌트(" + componentId + ")를 참조할 수 없습니다.");
	}
};

