 * ============= ============ ==========================
 *  Date          Author       Description
 * ============= ============ ==========================
 *  2023.04.12.   황은관   [NELS]최초 생성
 * ============= ============ ==========================
 * */
pspscrn.cfSetCsDvsCdPANMGNGLMT = function(dcId, elctnLwstTaskTypCd, intgCsNmCd) {
    var arrPCV = ["001", "002", "004", "005", "050", "051", "053", "054", "064", "066", "067"];
    var arrPHS = ["034", "035", "038", "040", "043", "045", "057", "062", "063", "128", "194", "195", "196", "197"];
    var arrPPT = ["046", "047", "129", "132"];

    if(elctnLwstTaskTypCd == psp.C.SO_KIND_PCV) {
        excludeItem(arrPCV, dcId);

        if(intgCsNmCd == psp.C.PANMGNGLMTCANSIN) { // 판결서 열람 등 제한결정 취소신청서(709)
        	pspscrn.autoCompleteInsertData(dcId,['074','카기'])
        }
    } else if(elctnLwstTaskTypCd == psp.C.SO_KIND_PPT) {
        excludeItem(arrPPT , dcId);

        if(intgCsNmCd == psp.C.PANMGNGLMTCANSIN) { // 판결서 열람 등 제한결정 취소신청서(709)
        	pspscrn.autoCompleteInsertData(dcId,['131','카허'])
        }
    } else if(elctnLwstTaskTypCd == psp.C.SO_KIND_PHS) {
        excludeItem(arrPHS , dcId);

        if(intgCsNmCd == psp.C.PANMGNGLMTCANSIN) { // 판결서 열람 등 제한결정 취소신청서(709)
        	pspscrn.autoCompleteInsertData(dcId,['127','아'])
        }
    }

    // arr에 포함되지 않는 사건구분 삭제
    function excludeItem(arr, dcId) {
        for(var idx=0; idx < dcId.getRowCount() ; idx++) {
            var value = dcId.getAllJSON()[idx].value;
            if(arr.indexOf(value) < 0) {
                dcId.removeRow(idx);
                idx = idx - 1 ;
            }
        }
    }
}

