pspscrn.openCsSearch = function(encCsSearchParam,anonymousTyp,btprtNm){
    var setAnonymousTyp = anonymousTyp;
	if ( undefined == setAnonymousTyp || "" == setAnonymousTyp )
		setAnonymousTyp = "02";

	var pBtprtNm = "";

	if ( undefined == btprtNm || "" == btprtNm ) {
		pBtprtNm = "";
	} else {
		pBtprtNm = btprtNm;
	}


	//사건검색 파라미터 정보를 설정한다.
    com.executeAjax({
        action: psp.CONTEXT_ROOT + "/pspcom/getCsSearchParam.on",
        mode: "synchronous",
        method: "POST",
        mediatype: gcm.DEFAULT_OPTIONS_MEDIATYPE,
        requestData: JSON.stringify({
            "encCsSearchParam" : encCsSearchParam,
            "btprtNm" : pBtprtNm,
            "anonymousTyp" : setAnonymousTyp
        }),
        success: function (_data) {
            paramData = {
                "cortCd" : _data.responseJSON.data.result.cortCd,
                "csYear" : _data.responseJSON.data.result.csYear,
                "csDvsNm" : _data.responseJSON.data.result.csDvsNm,
                "csSerial" : _data.responseJSON.data.result.csSerial,
                "btprtNm" : _data.responseJSON.data.result.btprtNm,
                "callDomain" : _data.responseJSON.data.result.callDomain,
                "prwlKey" : _data.responseJSON.data.result.prwlKey,
                "preProgYn" : _data.responseJSON.data.result.preProgYn,
                "typ" : _data.responseJSON.data.result.typ,
                "atho" : _data.responseJSON.data.result.atho,
                "dcRgstNoIndctYn" : _data.responseJSON.data.result.dcRgstNoIndctYn,
                "myCslistLinkYn" : _data.responseJSON.data.result.myCslistLinkYn,
                "nrlnmDvsCd" : _data.responseJSON.data.result.nrlnmDvsCd
            };
            if (psp.env.isMobileApp()) {
            	let host = location.host;
            	if (psp.isIosApp()) {
            		//host = $p.top().scwin.IOS_HREF;
            		host = psputils.IOS_HREF;
            		host.replace("http://", "");
            		host.replace("https://", "");
            	}
            	paramData.mode = "mcs";
            	paramData.mcsDomain = host;
            	paramData.callTyp = "MCSWEB";
            	paramData.ckiStrgYn = "Y"
            }
            window.open("" ,"csSrchDetail", "toolbar=no, width=1100, height=800, directories=no, status=no, scrollorbars=no, resizable=no");
            pspscrn.sendPostForm(_data.responseJSON.data.result.url, paramData, "csSrchDetail");
            if (psp.isIosApp()) {
            	setTimeout(()=>{
                    $h.common.hideXButton((result)=>{
                        console.log("hideXButton 결과\n" + result);
                    },
                    {
                        show:true
                    });
                }, 1000);
            }
        },
        error: function (e) {
//            console.log("error code : " + e.responseStatusCode);
        },
    });
};

