/**
 * <pre>
 * form을 동적으로 생성하여 입력한 파라미터를 변수화하여 post방식으로 submit한다.
 *
 * commonScope.js 에 sendPostForm 함수가 있으나 target 지정하는 기능이 존재하지 않아
 * target 지정기능 추가
 *
 * </pre>
 *
 * @parameter submitPath:url, params:파람, target:타겟
 * @return N/A
 * @see N/A
 * ============= ============ ==========================
 *  Date          Author       Description
 * ============= ============ ==========================
 * 2023.07.25.   전성영         [NELS] 최초생성
 * ============= ============ ==========================
 */
pspscrn.sendPostForm = function (submitPath, params, target) {

    var method = "post";
    var form = document.createElement("form");
    form.setAttribute("method", method);
    form.setAttribute("action", submitPath);
    if(typeof target != "undefined") {
    	form.setAttribute("target", target);
    }

    for(var key in params){
        if(params.hasOwnProperty(key)){
            var hiddenField = document.createElement("input");
            hiddenField.setAttribute("type", "hidden");
            hiddenField.setAttribute("name", key);
            hiddenField.setAttribute("value", encodeURIComponent(params[key]));

            form.appendChild(hiddenField);
        }
    }

    document.body.appendChild(form);
    form.submit();
};

