pspscrn._isAcntNo =  function(rfdactBankCd, lwstCstRfndacno,  rfdactDptrNm, payMensKndCd, isMsg, acntFlag){
	return new Promise((resolve, reject )=>{
    com.executeAjax({
        action: psp.CONTEXT_ROOT + "/pspaisc/isAcntNo.on",
        mode: "synchronous",
        method: "POST",
        mediatype: gcm.DEFAULT_OPTIONS_MEDIATYPE,
        processMsg : "계좌확인 중입니다.",
        requestData: JSON.stringify({
        	rfdactBankCd: rfdactBankCd,
        	lwstCstRfndacno: lwstCstRfndacno,
        	isMsg : isMsg
        }),
        success: function(_data) {
          if (_data.responseJSON.data.dma_result.isResult) {
        	  //유효한 계좌정보 입니다. \n환급계좌에 등록하시겠습니까? \n예금주 : <%s>",
        	  var msg = scutilo.getMsg(pspmsg.PSP.C_0009, _data.responseJSON.data.dma_result.dptrNm);
        	  switch(acntFlag){
        	  		case "dlvrfAutoPay":
        	  			msg = scutilo.getMsg(pspmsg.PSP.C_0441, "송달료 자동납부 ", _data.responseJSON.data.dma_result.dptrNm);
        	  			break;
        	  		default:
        	  			break;
        	  }

        	  scutilo.showConfirm(scglblo.MSG.CONFIRM, msg, function (result) {
                  if (result.clickValue){
                	  resolve(true);
                  }else{
                	  resolve(false);
                  }
        	  });
          }else{
        	  //계좌확인이 되지 않았습니다.
        	  resolve(false);
        	  var msg = scutilo.getMsg(pspmsg.PSP.W_0014);
        	  scutilo.showMsg(scglblo.MSG.WARN, msg, function (result) {
        		  resolve(false);
        	  });
          }
        },
        error: function(e) {
            alert("error code : " + e.responseStatusCode);
            resolve(false);
        },
    });
	});

};

