/**
 * <pre>
 * 발급문서를 프린트 요청한다.
 *
 * </pre>
 *
 * @parameter issuDvs(발급구분), param(발급요청데이터), successCallback(문서발급성공호출함수), failCallback(문서발급실패호출함수)
 * @return N/A
 * @see ECF000.js cfPDFPrint
 * ============= ============ ==========================
 *  Date          Author       Description
 * ============= ============ ==========================
 * 2023.10.19.   이상현         [NELS] 최초생성
 * ============= ============ ==========================
 */
pspscrn.pdfIssuPrint = function(issuDvs, param, successCallback, failCallback){
	if ( issuDvs == 'real' ) {
		com.executeAjax({
	    	passGlobalErrorHandler : true,
	        action: psp.CONTEXT_ROOT + "/pspcom/getPdfIssuQR.on",
	        requestData: JSON.stringify({
	            dma_srchEdms: param,
	        }),
	        mode: "asynchronous",
	        mediatype: gcm.DEFAULT_OPTIONS_MEDIATYPE,
	        method: "POST",
	        beforeAjax: function() {
	        },
	        success: function(_data) {
	            dma_downloadOtpt.setJSON(_data.responseJSON.data.dma_downloadOtpt);
	            dlt_downloadOtpt.setJSON(_data.responseJSON.data.dlt_downloadOtpt);

	            var params = {};
	            var dmaDownloadOtpt = dma_downloadOtpt.getJSON();
	            var dltDownloadOtpt = dlt_downloadOtpt.getAllJSON();
	            params.dma_downloadOtpt = dmaDownloadOtpt;
	            params.dlt_downloadOtpt = dltDownloadOtpt;
	            pdfIssuPrint(issuDvs, params, successCallback, failCallback);

	        },
	        error: function(e) {
//	            console.log("error code : " + JSON.parse(e.responseBody).errors.errorMessage);
	            failCallback("EdocError");
	        },
	    });
	} else {
		pdfIssuPrint(issuDvs, param);
	}
};

/**
 * <pre>
 * 은행조회 공통 함수
 *
 * </pre>
 *
 * @parameter dcId(데이터콜렉션ID): 필수
 * systm(시스템): CSB(소송비용), KGS(공유센터) 등
 * scntmIntgCdOption(두번째공통코드검증옵션): 옵션(코드마다 상이함)
 * scntmIntgCdVal(두번째공통코드의인덱스의 값): 옵션(코드마다 상이함)
 *
 * @return dcId(데이터콜렉션ID)에 등록
 * ============= ============ ==========================
 *  Date          Author       Description
 * ============= ============ ==========================
 * 2023.11.02.   김기오         [NELS] 최초생성
 * 2023.11.09.   김기오         첫번째index 로직 추가
 * ============= ============ ==========================
 */
pspscrn.selBankCdLst = function(dcId, systm, scntmIntgCdOption, scntmIntgCdVal){
    var vIntgCdLst  = psp.data.codes(systm, "BANK_CD");
    var vIntgCdLstR = new Array();
    var vIdx = 0;

    for (var i = 0; i < vIntgCdLst.length; i++) {
    	if(systm == "CSB"){
	        if (vIntgCdLst[i].scntmIntgCdAddCtt.charAt(scntmIntgCdOption - 1) == scntmIntgCdVal && vIntgCdLst[i].scntmIntgCdAddCtt.charAt(0) == "Y") {
	            vIntgCdLstR[vIdx] = vIntgCdLst[i];
	            vIntgCdLstR[vIdx].intgCdNm = vIntgCdLstR[vIdx].intgCdNm.substring(0, vIntgCdLstR[vIdx].intgCdNm.length - 2);
	            vIdx++;
	        }
    	}else{
    		vIntgCdLstR[vIdx] = vIntgCdLst[i];
            vIntgCdLstR[vIdx].intgCdNm = vIntgCdLstR[vIdx].intgCdNm.substring(0, vIntgCdLstR[vIdx].intgCdNm.length - 2);
            vIdx++;
    	}
    }
    dcId.setJSON(vIntgCdLstR);

};

/**
 * <pre>
 * 해당 통합그룹코드에 통합코드로 통합코드명을 조회한다.
 * </pre>
 *
 * @parameter
 *     - systmCd(시스템 코드) : 필수
 *     - taskCd(테스크 코드) : 옵션
 *     - intgGrpCd(공통코드 테이블 상위 그룹 코드) : 필수
 *     - cdVal(코드명을 가지고올 코드 값) : 필수
 *
 * ============= ============ ==========================
 *  Date          Author       Description
 * ============= ============ ==========================
 * 2023.12.11.   손수영         [NELS] 최초생성
 * ============= ============ ==========================
 */
pspscrn.getCdNmByCdVal = function(intgGrpCd, cdVal, systmCd, taskCd){
	if(taskCd == undefined){
		sccdo.loadIntgCdLst(systmCd +  scglblo.DELIMITER.HYPHEN + intgGrpCd);
		sccdo.setTask(systmCd);
	} else {
		sccdo.loadIntgCdLst(systmCd +  scglblo.DELIMITER.HYPHEN + taskCd + scglblo.DELIMITER.HYPHEN + intgGrpCd);
		sccdo.setTask(systmCd, taskCd);
	}
	return sccdo.getIntgCdNm(intgGrpCd, cdVal);
};

/**
 * <pre>
 * 전달된 탭프레임 기준으로 상위인 탭컨트롤 객체를 구하여 반환
 *
 * 1) 회생파산서류 - 파산관재인보고서 는 탭컨트롤이 2개여서 표시되는 탭을 찾아서 반환
 * 2) WebSquare.util.getChildren(tabWframe.getParentFrame(),...) 엔진 버그가 있어서 회피하는 코드를 추가(2024-01-04)
 * </pre>
 *
 * @param	tabWframe	탭프레임객체
 * @return	상위인 탭컨트롤 객체
 * @see		psp.js#psp.displayDocSteps()
 *
 * ============= ============ ==========================
 *  Date          Author       Description
 * ============= ============ ==========================
 * 2024.01.04.    안종광         [NELS] 최초생성
 * ============= ============ ==========================
 */
pspscrn.getTabControl = function(tabWframe) {
	var tabCtrlObj = null;
	try {
		tabCtrlObj = WebSquare.util.getChildren(tabWframe.getParentFrame(), {recursive:true, includePlugin:"tabControl"})[0]; //$p.top().pfwork 이 맞음
		if ( "none" == tabCtrlObj.getStyle("display") ) { // (노트) 회생파산서류 - 파산관재인보고서 는 탭컨트롤이 2개임.
			tabCtrlObj = WebSquare.util.getChildren(tabWframe.getParentFrame(), {recursive:true, includePlugin:"tabControl"})[1];
		}
	}
	catch(e) {
		_warn("[scrn#g_t_ctrl]", e.message);
		tabCtrlObj = null;
	}
	if ( null==tabCtrlObj ) {
		tabCtrlObj = tabWframe.getParent().getParent();
	}

	return tabCtrlObj;
};

