/**
 * <pre>
 * 149번 프로퍼티 공통 법원 코드 목록 조회
 * </pre>
 *
 * @parameter dcId(데이터콜렉션ID): 필수
 * @return 법원코드목록
 * @see
 * ============= ============ ==========================
 *  Date          Author       Description
 * ============= ============ ==========================
 * 2024.07.12.   이상현         [NELS] 최초생성
 * ============= ============ ==========================
 */
pspscrn.selComCortLst = function(dcId) {
    var result = null;
    var jsonArray = new Array();
    com.executeAjax({
        action: "/psp/pspcom/selectComCdPrptLst.on",
        mode: "synchronous",
        method: "POST",
        mediatype: gcm.DEFAULT_OPTIONS_MEDIATYPE,
        requestData: JSON.stringify({uprElpPrptId:"psp.comCortCd"}),
        success: function (_data) {
            result = _data.responseJSON.data.result;
        },
        error: function (e) {
        	alert("error code : " + e.responseStatusCode);
        },
    });

    for (var i = 0; i < result.length; i++) {
        var jsonObj = new Object();
        jsonObj.value = result[i].elpPrptVal;
        jsonObj.label = result[i].prptRmk;
        jsonObj = JSON.stringify(jsonObj);
        jsonArray.push(JSON.parse(jsonObj));
    }

    dcId.setJSON(jsonArray);
};

