    var arrPKS = ["150", "151", "162", "163", "462", "461", "463", "024", "029", "152", "153", "164", "165", "060", "183", "177", "178", "225", "226", "211", "251", "245", "246", "247", "026", "027", "110", "146", "147", "310", "025", "061"];
    var arrPHS = ["194", "195", "034", "196", "197", "057", "036", "037", "126", "133", "188", "311", "184", "109", "035", "038", "062", "043", "128", "040", "063", "045"];
    var arrPPT = ["129", "132", "032", "130", "275", "046", "047"];

    if(elctnLwstTaskTypCd == psp.C.SO_KIND_PCV) {
        removeDvsLst(arrPCV, dcId);
        //pspscrn.autoCompleteInsertData(dcId, ["240", "정가"]);
        pspscrn.autoCompleteInsertData(dcId, ["283", "재정마"]);
    } else if(elctnLwstTaskTypCd == psp.C.SO_KIND_PKS) {
        removeDvsLst(arrPKS, dcId);
    } else if(elctnLwstTaskTypCd == psp.C.SO_KIND_PHS) {
        removeDvsLst(arrPHS , dcId);
        pspscrn.autoCompleteInsertData(dcId, ["127", "아"]);
        pspscrn.autoCompleteInsertData(dcId, ["041", "주"]);
    } else if(elctnLwstTaskTypCd == psp.C.SO_KIND_PPT) {
        removeDvsLst(arrPPT , dcId);
        pspscrn.autoCompleteInsertData(dcId, ["131", "카허"]);
    } else if(elctnLwstTaskTypCd == psp.C.SO_KIND_PJH) {
        pspscrn.autoCompleteInsertData(dcId, ["300", "타인"]);
    }

    // arr에 포함되지 않는 사건구분 삭제
    function removeDvsLst(arr, dcId) {
        for(var idx=0; idx < dcId.getRowCount() ; idx++) {
            var value = dcId.getAllJSON()[idx].value;
            if(arr.indexOf(value) < 0) {
                dcId.removeRow(idx);
                idx = idx - 1 ;
            }
        }
    }
}

