/**
 * 공통 업로드용 이노릭스 컨트롤 파일 첨부전 파일정보를 체크한다.
 *
 *
 * @param   elementId   이노릭스가 바인딩될 (전체)엘리멘트ID (예) '#mf_pfwork_grp_innorix'
 * @return  업로드용 이노릭스 컨트롤 생성 옵션
 * @see     innorox.js
 * ============= ============ ==========================
 *  Date          Author       Description
 * ============= ============ ==========================
 *  2024.01.11.   우근석        최초생성
 *  2024.02.13.   우근석        0 byte용량 체크 추가
 *  2024.07.31.   우근석        파일명 특수문자여부 추가
 * ============= ============ ==========================
 */
pspsoltn.cmnChkAtfl = function(objFileInfo, objInnorix) {
    var filePath = objFileInfo["filePath"]; // (예) "첨부파일 업로드 테스트 hwp 파일 01.hwp"
    var fileSize = objFileInfo["fileSize"]; // (예) 933888
    var fname = filePath.substring(1 + filePath.lastIndexOf("\\"));
    var fnext = fname.substring(1 + fname.lastIndexOf(".")).toLowerCase();

    var allowedExts             = [];
    var oneMmFileSize           = pspsoltn.MAX_SIZE_MM_FILE;
    var oneDocFileSize          = pspsoltn.MAX_SIZE_DOC_FILE;
    var fnamePermImprRegExp     = new RegExp(/[\/\\:*?"^<>|=%&]/i);     // 파일명내에 허용되지 않는 특수문자

    // console.log(`pspsoltn.cmnChkAtfl ==============================> `);
    if(objInnorix != undefined &&  objInnorix.option != undefined) {
        if(objInnorix.option.allowType != undefined) {       // 전체파일
            if( $.isArray(objInnorix.option.allowType) ) {
                allowedExts = objInnorix.option.allowType;
            }
            else {
                objInnorix.option.allowType.split(",").forEach(function(val) {
                    val = val.replaceAll(/[^a-zA-Z0-9]/gi, '');
                    allowedExts.push(val);
                });
            }
        }
        if(objInnorix.option.oneMmFileSize != undefined && scutilo.isNotEmpty(objInnorix.option.oneMmFileSize)) {   // 멀티미디어파일
            oneMmFileSize = objInnorix.option.oneMmFileSize;
        }
        if(objInnorix.option.oneDocFileSize != undefined && scutilo.isNotEmpty(objInnorix.option.oneDocFileSize)) { // 일반파일
            oneDocFileSize = objInnorix.option.oneDocFileSize;
        }
    }

    if (fnamePermImprRegExp.test(fname)) {        // W_0309: "<%s>에 특수문자(/, \\, :, *, ?, \", <, >, |, =, %, &)는 입력할 수 없습니다.",
        scutilo.showMsg(scglblo.MSG.WARN, psputils.unclearXss(scutilo.getMsg(pspmsg.PSP.W_0309, "파일명")), function (p) { return false; });
        return false;
    }

    // 허용하는 첨부파일 종류
    if ( ! allowedExts.includes(fnext) ) {
        var msg = scutilo.getMsg(pspmsg.PSP.W_0332, fnext, fname); //W_0332: "파일확장자(<%s>)는 허용되지 않습니다. 파일명 : <%s>",
        scutilo.showMsg(scglblo.MSG.WARN, msg);
        _debug("[#checkAttachFile] [오류] 파일확장자 :", fnext);
        return false;
    }

    // 파일사이즈가 0인 경우 검증 추가
    if(fileSize <= 0) {
        var msg = scutilo.getMsg(pspmsg.PSP.W_0000, '첨부파일 용량이 '+psputils.getByteText(limitsize, 2)+'입니다.'); //W_0000: "첨부파일 용량이 <%s>입니다.,",
        scutilo.showMsg(scglblo.MSG.WARN, msg);
        return false;
    }

    // 허용하는 단일파일 크기
    var limitsize = pspsoltn.isDocFile(fname) ? oneDocFileSize : oneMmFileSize;

    if ( fileSize > limitsize ) {
        var byteTxt = psputils.getByteText(limitsize, 2);
        var msg = scutilo.getMsg(pspmsg.PSP.W_0333, psputils.getByteText(limitsize, 2), "<br>(" + psputils.getByteText(fileSize, 2) + ")"); //W_0333: "파일 크기는 최대 <%s>까지만 허용됩니다.<%s>",
        scutilo.showMsg(scglblo.MSG.WARN, msg);
        _debug("[#checkAttachFile] [오류] 파일크기 :", fileSize, "==", byteTxt, "/ limitsize =", limitsize, "/ 파일확장자 =", fnext);
        return false;
    }
    return true;
}


pspsoltn.canAttachFile = function(filePath) {
    var fname = filePath.substring(1 + filePath.lastIndexOf("\\"));
    var fnext = pspsoltn.getFileExt(fname);

    if ( !pspsoltn.ALLOWED_FILE_EXTS.includes(fnext) ) {
        var msg = scutilo.getMsg(pspmsg.PSP.W_0332, fnext, fname); //W_0332: "파일확장자(<%s>)는 허용되지 않습니다. 파일명 : <%s>",
        scutilo.showMsg(scglblo.MSG.WARN, msg);
        return false;
    }
    return true;
}

