        var atchDocmtKndCd  = dmaAtflInf.atchDocmtKndCd;    //  첨부서류종류
        var elpUserId       = dmaAtflInf.elpUserId;         //  소송포털사용자
        var frameId         = dmaAtflInf.frameId;           //  프레임ID

        var sScopeId        = psp.getScopeId(frameId);

        dmaAtflInf.atchDocmtRegMthdCd = dmaAtflInf.atchDocmtRegMthdCd || "1";
//        var sPdfTrgt        = psp.prpt.getPrpt("psp.convtFile", "psp.convtFile.extension"); // PDF변환대상
//        var sPdfConvTrgt    = sPdfTrgt.val.split(",").join("|");
//        var sPdfTrgt        = "hwp,hwpx,doc,docx,xls,xlsx,txt,bmp,jpg,jpeg,gif,tif,tiff,png";
        var sPdfConvTrgt    = pspsoltn.PDF_CONV_FILE_EXTS.join("|");
//        console.log(`===============fileUpload > ${sPdfConvTrgt}`);
        // PDF변환 요청
        var dltPdfConvReqObj = psp.createDlt([
            { "dataType":"text",   "id":"elpEcdocNo",              "name":"소송포털전자문서번호" },
            { "dataType":"text",   "id":"elpEcdocAtchDocmtSeq",    "name":"소송포털전자문서첨부서류순번" },
            { "dataType":"text",   "id":"elpEcdocAtflSeq",         "name":"소송포털전자문서첨부파일순번" },
            { "dataType":"text",   "id":"jobKind",                 "name":"작업구분" },
            { "dataType":"text",   "id":"fileEdmsDocId",           "name":"파일EDMS문서ID" },
            { "dataType":"text",   "id":"marginTop",               "name":"상단여백" },
            { "dataType":"text",   "id":"marginBottom",            "name":"하단여백" },
            { "dataType":"text",   "id":"marginLeft",              "name":"왼쪽여백" },
            { "dataType":"text",   "id":"marginRight",             "name":"오른쪽여백" },
            { "dataType":"text",   "id":"pdfConvFileNm",           "name":"PDF변경파일명" },
            { "dataType":"text",   "id":"userId",                  "name":"작성요청자ID" },
            { "dataType":"text",   "id":"docIssuNo",               "name":"문서발급번호" }],
            "dlt_convReq", sScopeId);

        // PDF변환 응답
        var dltPdfConvResObj = psp.createDlt([
            { "dataType":"text",   "id":"elpEcdocNo",              "name":"소송포털전자문서번호" },
            { "dataType":"text",   "id":"elpEcdocAtchDocmtSeq",    "name":"소송포털전자문서첨부서류순번" },
            { "dataType":"text",   "id":"elpEcdocAtflSeq",         "name":"소송포털전자문서첨부파일순번" },
            { "dataType":"text",   "id":"fileEdmsDocId",           "name":"파일EDMS문서ID" },
            { "dataType":"text",   "id":"fileNm",                  "name":"파일명" },
            { "dataType":"text",   "id":"fileSz",                  "name":"파일크기" },
            { "dataType":"text",   "id":"fileUnqNo",               "name":"파일유일번호" },
            { "dataType":"text",   "id":"fileHashVal",             "name":"파일해쉬값" },
            { "dataType":"number", "id":"docPageCnt",              "name":"문서장수" },
            { "dataType":"text",   "id":"docIssuNo",               "name":"문서발급번호" }],
            "dlt_convRes", sScopeId);

        // 파일목록정보 -- 임시저장 정보
        var dltFileSaveInf = psp.createDlt([
            { "dataType":"text",   "id":"elpEcdocNo",              "name":"소송포털전자문서번호" },
            { "dataType":"text",   "id":"elpEcdocAtchDocmtSeq",    "name":"소송포털전자문서첨부서류순번" },
            { "dataType":"text",   "id":"elpEcdocAtflSeq",         "name":"소송포털전자문서첨부파일순번" },
            { "dataType":"text",   "id":"elpUserId",               "name":"소송포털사용자ID" },
            { "dataType":"text",   "id":"atchDocmtNm",             "name":"첨부서류명" },
            { "dataType":"text",   "id":"atchDocmtKndCd",          "name":"첨부서류종류코드" },
            { "dataType":"text",   "id":"atchDocmtRegMthdCd",      "name":"첨부서류등록방법코드" },
