                dltObj.removeAll();
            }
        }
        // EDMS파일을 전송한다.
        var fnEdmsUpload = function () {
            psputils.regEdms(elpUserId, dltObj.getAllJSON(), function(edmsFileLst) {
                var isPdfTrgtYn  = false;

                if(edmsFileLst.length > 0) {
                    for(var idx = 0, len = edmsFileLst.length; idx < len; idx++ ) {
                        var fileObj     = edmsFileLst[idx];
                        var fileNm      = fileObj.fileNm;
                        var fileExt     = fileNm.substring(fileNm.lastIndexOf('.') + 1).toLowerCase();
                        var atflTrgtYn  = fileExt.match(sPdfConvTrgt) ? "Y" : "N";
                        var docIssuNo   = "";

                        if(fileObj.docIssuNo != undefined ) {
                            docIssuNo = fileObj.docIssuNo;
                        }

                        if(atflTrgtYn == "Y") {
                            isPdfTrgtYn = true;
                        }
                        dltFileSaveInf.insertJSON(idx, [{
                            "elpEcdocNo"     : elpEcdocNo,                   // 소송포털 전자문서번호
                            "atchDocmtNm"    : fileObj.docNm,
                            "atchDocmtKndCd" : atchDocmtKndCd,
                            "atflEdmsDocId"  : fileObj.fileEdmsDocId,        // 첨부파일EDMSID
                            "atflHshVal"     : fileObj.fileHashVal,
                            "atflNm"         : fileObj.fileNm,
                            "atflSz"         : fileObj.fileSz,
                            "docPageCnt"     : fileObj.docPageCnt,
                            "elpUserId"      : elpUserId,
                            "atflConvTrgtYn" : atflTrgtYn,
                            "docIssuNo"      : docIssuNo
                        }]);
                    }

                    if(pdfConvYn == "Y" && isPdfTrgtYn) {
                        fnConvertPdf();
                    }
                    else {
                        fnSaveInf();
                    }
                }
                else {
                    fnErr.call(null);
                }
            },
            function(resObj) {
                dltObj.removeAll();
            });
        }

        // PDF변환이 필요한 파일을 PDF로 변환한다.
        var fnConvertPdf = function () {
            // WebSquare.layer.showProcessMessage(scutilo.getMsg(pspmsg.PSP.I_0000, "첨부파일을 등록중입니다."));
            dltPdfConvReqObj.removeAll();
            var jdx = 0;
            for(var idx=0, len=dltFileSaveInf.getRowCount(); idx < len; idx++) {
                var fileObj = dltFileSaveInf.getRowJSON(idx);

                if(fileObj.atflConvTrgtYn == "Y") {
                    var fileNm  = fileObj.atflNm;
                    fileNm      = fileNm.replace(/\s/g, "_");                   // 공백을 허용하지 않음
//                    fileNm      = fileNm.replace(/(.png|.gif)$/, '');           // PNG/GIF 제거
                    fileNm      = fileNm.substring(0, fileNm.lastIndexOf('.')); // 확장자 제거

                    dltPdfConvReqObj.insertJSON(jdx++, [{
                        "jobKind"        : "PSP",                        // EDMS등록 시스템코드
                        "fileEdmsDocId"  : fileObj.atflEdmsDocId,        // 첨부파일EDMSID
                        "pdfConvFileNm"  : fileNm + ".pdf",
                        "userId"         : elpUserId
                    }]);
                }
            }

            if(dltPdfConvReqObj.getRowCount() > 0) {
                var convUrl = "/smko/smkofile/convertPdfFiles.on";
                var maxSize = 0;
                for(var idx = 0, len = dltPdfConvResObj.getRowCount(); idx < len; idx++) {
                    if(dldltPdfConvReqObj.gegetCellData(idx, "atflSz") >= maxSize) {
                        maxSize = dldltPdfConvReqObj.gegetCellData(idx, "atflSz");
                    }
                }
                convUrl = pspsoltn.replaceSmkoBigUrl(convUrl, maxSize);
                com.executeSubmission(
                        psp.createSbm({
                            "mode"               : "asynchronous",
                            "processMsg"         : "PDF변환대상파일을 변환하는 중입니다.",     // 메시지문자열
                            "submitErrorHandler" : fnErr
                        },
                        "sbm_convertPdfFiles",
                        "data:json, {'id':'dlt_convReq','key':'dlt_convertPdfFiles'}",          // 요청
                        "data:json, {'id':'dlt_convRes','key':'data.dlt_convertPdfFilesRes'}",  // 응답
                        convUrl,
                        sScopeId,
                        function(e){
                            for(var idx = 0, len = dltPdfConvResObj.getRowCount(); idx < len; idx++) {
                                var reqFileObj = dltPdfConvReqObj.getRowJSON(idx);
                                var resFileObj = dltPdfConvResObj.getRowJSON(idx);

                                var objs= dltFileSaveInf.getMatchedIndex("atflEdmsDocId", reqFileObj.fileEdmsDocId);

                                dltFileSaveInf.setCellData(objs[0], "convAtflEdmsDocId",    resFileObj.fileEdmsDocId);
                                dltFileSaveInf.setCellData(objs[0], "convAtflNm",           resFileObj.fileNm);
                                dltFileSaveInf.setCellData(objs[0], "convAtflHshVal",       resFileObj.fileHashVal);
                                dltFileSaveInf.setCellData(objs[0], "convAtflSz",           resFileObj.fileSz);
                                dltFileSaveInf.setCellData(objs[0], "docPageCnt",           resFileObj.docPageCnt);
                            }
                            fnSaveInf();
                        }));
            }
            else {
                fnSaveInf();
            }
        }
        //
        var fnSaveInf = function() {
            var dltFile = dltFileSaveInf.getAllJSON();
            dltFileSaveInf.removeAll();
            dltPdfConvReqObj.removeAll();
            dltPdfConvResObj.removeAll();
            if(isSaveYn !== "N") {
                pspsoltn.fnRegAtchDocmt(dmaAtflInf, dltFile, fnSuccess, fnErr);
            }
            else {
                if ( null!=fnSuccess && 'function' == typeof fnSuccess ) {
                    fnSuccess.call(this, dltFile);
                }
            }
        }
        if(dmaAtflInf.atchDocmtRegMthdCd == "1") {
            fnEdmsUpload();
        }
        else {
            dltFileSaveInf.setJSON(dltObj.getAllJSON);
            fnSaveInf();
        }
    }
    // WebSquare.layer.showProcessMessage(scutilo.getMsg(pspmsg.PSP.I_0000, "첨부파일을 등록중입니다."));
    if(scutilo.isEmpty(isExtPdfYn) || isExtPdfYn === "N") {
        pspsoltn.fnPdfValidate(dltObj, function () {
            fnUpload();
        });
    }
    else {
        pspsoltn.fnPdfExtractTxtYn(dltObj, function () {
            fnUpload();
        });
    }
};


