 * ============= ============ ==========================
 */
pspsoltn.replaceSmkoBigUrl = function(url, size) {
//    console.log(`replaceSmkoBigUrl Befor -->  url :: ${url} , size :: ${size}`);

    var maxNormalFile = this.MAX_NORMAL_FILE;
    var maxNormalSize = psp.prpt.getFilePropVal(psp.C.FPPKEY_MAX_NORMAL_FILE)||10;

    maxNormalFile = maxNormalSize*1024*1024;
    if(size > maxNormalFile) {
        url = url.replace("/smko/", "/smkobig/");
    } else {
    	url = url.replace("/smkobig/", "/smko/");
    }
//    console.log(`replaceSmkoBigUrl After -->  url :: ${url} , compSize ::  ${maxNormalSize} , size :: ${size}`);
    return url;
};

/**
 * 업로드용 이노릭스 컨트롤 객체 생성하고, 디폴트 이벤트 핸들러 설정.
 *
 * 1. 객체 생성
 * 2. 파일선택 전처리 : 허용할 파일확장자 필터
 * 3. 파일선택 후처리 : (업로드)
 * 4. 업로드 완료 : 전체 파일크기 표시
 * 5. 업로드 오류
 *
 * (참고) 각 업무화면에서 추가적인 이벤트 처리가 필요한 경우,
 * 이 pspsoltn.initInrx() 로 반환된 객체에서 해당 이벤트를 재정의 하여 사용
 *
 * (사용예 예, @see PSP000M03.xml)
 *
 * scwin.control = pspsoltn.initInrxCtrl('#mf_pfwork_grp_innorix', null, {
 *  gridTrgt:"grdAtchFile",     // 대상그리드
 *  btnInq:"btn_searchFile",    // 파일찾기버튼
 *  btnDel:"btn_selectFileDel", // 파일삭제버튼
 *  mltcsYn:"Y"                 // 다건파일여부
 * },
 * function(){});
 *
 * scwin.control.on('afterAddFiles', function(files) {
 *     //각 화면에서 재정의하여 사용함.
 * }
 *
 *
 * @param   elemId      이노릭스가 바인딩될 (전체)엘리멘트ID (예) '#mf_pfwork_grp_innorix'
 * @param   dltObj      업로드된 파일정보가 저장되는 데이터리스트 객체
 * @param   inrxOption  이노릭스를 생성할 경우 필요한 옵션 - 별도처리를 위한
 * @param   innoParam   {
 *  gridTrgt,        대상 그리드
 *  btnInq,         파일찾기 버튼
 *  btnDel,         파일삭제 버튼
 *  mltcsYn,        여러파일 선택여부
 *  oneMmFileYn     멀티미디어 단건제한여부
 * }
 * @param   uploadYn    업로드 바로등록여부
 * @return  업로드용 이노릭스 컨트롤 객체
 * ============= ============ ==========================
 *  Date          Author       Description
 * ============= ============ ==========================
 *  2024.01.29   우근석        [NELS]최초 생성
 * ============= ============ ==========================
 */
pspsoltn.initInrxCtrl = function(elemId, dltObj, inrxOption, fnSucc, innoParam, uploadYn) {
    var isInnorixIncluded = false;
    try {
        if ( ! innorix ) {
            _error("[soltn#initInrx] can NOT load innorix!");
        }
        isInnorixIncluded = true;
    }
    catch(e) {
        isInnorixIncluded = false;
    }
    if ( ! isInnorixIncluded ) {
        scutilo.showMsg("오류", "파일처리 객체를 로드하지 못하였습니다!"); //, function(p) { return false; });
        return null;
    }

    // 외부에서 이노릭스 옵션을 줄 경우 처리방안
    if(!inrxOption) {
        inrxOption = pspsoltn.getInrxOption(elemId);
        // 초기값 선언
//        var permDocSz    = psp.prpt.getPrpt("psp.attachFile", "psp.attachFile.fileSize").val||'10';                 //첨부 가능 1개 파일 용량
//        var totAtflSz    = psp.prpt.getPrpt("psp.attachFile", "psp.attachFile.totSizeForAttach").val||'50';         //첨부 가능 전체 파일 용량
//
//        var expendYn     = psp.prpt.getPrpt("psp.attachFile", "psp.attachFile.expendAllYn").val||'Y';
//        var expendId     = psp.prpt.getPrpt("psp.attachFile", "psp.attachFile.expendID").val||'';
//        if(expendYn == "Y" || (scutilo.isNotEmpty(expendId) &&
//                              scutilo.isNotEmpty(psp.session()) &&
//                              expendId.split(',').indexOf(psp.session()) > -1)) {
//              permDocSz    = psp.prpt.getPrpt("psp.attachFile", "psp.attachFile.fileSizeNew").val||'20';
//              totAtflSz    = psp.prpt.getPrpt("psp.attachFile", "psp.attachFile.totSizeForAttachNew").val||'100'; //첨부 가능 전체 파일 용량
//        }
//        inrxOption.allowType        = psp.prpt.getPrpt("psp.attachFile", "psp.attachFile.typeAttach").val;             //첨부 가능 대상파일
//        inrxOption.oneDocFileSize   = permDocSz*1024*1024;
//        inrxOption.maxFileSize      = totAtflSz*1024*1024;

        var sAllowType  =   "";
        var permDocSz   =   "";
        var totAtflSz   =   "";

        var fileInfoJson = pspsoltn.getFileInfo("");

        sAllowType  = fileInfoJson["allowTpAtfl"];
        permDocSz   = fileInfoJson["permDocSz"];
        totAtflSz   = fileInfoJson["totAtflSz"];

        inrxOption.allowType        = sAllowType;
        inrxOption.oneDocFileSize   = permDocSz*1024*1024;
        inrxOption.maxFileSize      = totAtflSz*1024*1024;
    }

    if(scutilo.isNotEmpty(inrxOption.allowType)) {
//        console.log(`===================> ${inrxOption.allowType}`);
        if($.isArray(inrxOption.allowType)) {
            inrxOption.allowExtension = inrxOption.allowType;
        }
        else {
            inrxOption.allowExtension = inrxOption.allowType.replaceAll(/[\s\"]/g, '').split(',');
        }
    }

    // #1. 업로드용 이노릭스 컨트롤 객체 생성
    var _innoControl = innorix.create(inrxOption);
    _innoControl.setSize("0px", "0px"); //(생성시 설정안됨) boxHeight: 250,  boxWidth: "100%",

    // #3. 파일추가 전처리 이벤트 핸들러 : 파일상자에 파일을 추가하기 전 체크로직
    _innoControl.on('beforeAddFile', function(p) {
        _debug("[soltn#initInrx] before :", p);
        // 공통파일 검증
        if(!pspsoltn.cmnChkAtfl(p, _innoControl)) {
            return false;
        }
        var fpath = p.filePath;
        var fname = fpath.substring( 1+fpath.lastIndexOf("\\") );
        var fnext = fname.substring( 1+fname.lastIndexOf(".") ).toLowerCase();

        var files = _innoControl.fileList.files;
        // 동일파일 등록여부확인
        if (files.filter(v => v.printFileName == fname).length > 0) {
            scutilo.showMsg(scglblo.MSG.WARN, scutilo.getMsg(pspmsg.PSP.W_0335, `<br>(${fname})`), function (p) { return false; });
            return false;
        }
        if(innoParam != undefined) {
            var mmMltYn = innoParam.oneMmFileYn || "N";
            // 멀티미디어 주장서면의 경우 멀티미디어 파일은 단건만 등록가능함
            if (pspsoltn.isMmFile(fname) && mmMltYn == "Y") {
                if (files.filter(v => pspsoltn.isMmFile(v.printFileName)).length > 0) {
                    scutilo.showMsg(scglblo.MSG.WARN, scutilo.getMsg(pspmsg.PSP.W_0256), function (p) { return false; });
                    return false;
                }
            }
        }

        var filePermCnt = inrxOption.filePermCnt;
        if (files.length >= filePermCnt) {   // 기존에 등록한 값이 허용 수 보다 같거나 많으면
            scutilo.showMsg(scglblo.MSG.WARN, scutilo.getMsg(pspmsg.PSP.W_0212,  filePermCnt), function(e) {
                return false;
            });
            return false;
        }
        // 단일파일을 위한 처리
        // 2024.01.31. 현재까지 올라간 용량을 체크
        var fileSz = 0;
        fileSz = dltObj.getColData('fileSize').reduce((acc, curr) => { return acc+curr}, 0);
        if(fileSz > inrxOption.maxFileSize) {
            scutilo.showMsg(scglblo.MSG.WARN, scutilo.getMsg(pspmsg.PSP.W_0125, psputils.getByteText(inrxOption.maxFileSize, 2)), function(p) {return false;});
            return false;
        }
    });

    // #3. 파일추가 후처리 이벤트 핸들러 : 파일상자에 파일을 추가하기 후 처리할 내용
    _innoControl.on('afterAddFiles', function(files) {

        _debug("[soltn#initInrx] afterAddFiles :", files);
        // files와 컨트롤 파일을 확인해봐야함
        var fileCurrCnt = files.length;
        var filePermCnt = _innoControl.option.filePermCnt;
        // 한번에 등록 가능한 수를 검증
        if(fileCurrCnt > filePermCnt) { // 허용가능한 수보다 많으면,
            scutilo.showMsg(scglblo.MSG.WARN, scutilo.getMsg(pspmsg.PSP.W_0354,  filePermCnt, fileCurrCnt), function(e) {

            });
            // 컨트롤에서 파일 삭제
            for(var idx = files.length-1; idx >= fileCurrCnt; idx--) {
                _innoControl.removeFileByIndex(idx);
            }
            // 올리는 파일에서 삭제
            files.splice(0, fileCurrCnt);
        }

        var oneDocFileSize  = pspsoltn.MAX_SIZE_DOC_FILE;
        if(_innoControl.option.oneDocFileSize != undefined && scutilo.isNotEmpty(_innoControl.option.oneDocFileSize)) { // 일반파일
            oneDocFileSize = _innoControl.option.oneDocFileSize;
        }

        var currFileSz  = 0;
        var compSize    = 0;
        // 파일크기에 따른 업로드URL
        for(var idx=0, len=files.length; idx < len; idx++) {
//            if(files[idx].fileSize > pspsoltn.MAX_NORMAL_FILE) {
//                files[idx].uploadUrl =  files[idx].uploadUrl.replace("/smko/", "/smkobig/");
//            }
//            else {
//                files[idx].uploadUrl =  files[idx].uploadUrl.replace("/smkobig/", "/smko/");
//            }
            if(files[idx].fileSize > compSize) {
                compSize = files[idx].fileSize;
            }
            currFileSz += files[idx].fileSize;
        }
        pspsoltn.checkUploadUrl(compSize, _innoControl);
//        console.log(`====================> URL : ${_innoControl.getUploadUrl()},   FILE_SIZE : ${compSize}`);
        // 한번에 등록 가능한 파일 사이즈
        // 파일컨트롤로 처리해야 하지 않을까?
        var fileSz = dltObj.getColData('fileSize').reduce((acc, curr) => { return acc+curr}, 0);
        fileSz = fileSz + currFileSz;
//        console.log(`====================> fileSz : ${fileSz}`);
        if(fileSz > _innoControl.option.maxFileSize) {
            scutilo.showMsg(scglblo.MSG.WARN, scutilo.getMsg(pspmsg.PSP.W_0125, psputils.getByteText(_innoControl.option.maxFileSize, 2)), function(p) {return false;});
            _innoControl.removeAllFiles();
            return false;
        }
        // 시스템에 등록 가능한 파일 사이즈
        var isSucc = pspsoltn.getElpUserByAtflSz(fileSz);

        if(isSucc) {
            if(uploadYn == "Y") {
                _innoControl.upload(); //(디폴트) 파일을 바로 업로드함
            }
            else {
                pspsoltn.moveInnorixFiles(_innoControl, dltObj);
            }
        }
        else {
            _innoControl.removeAllFiles();
            return false;
        }
    });

    // #4. 업로드 완료 이벤트 핸들러 : 업로드 완료후, 전체 파일사이즈 등 표시
    _innoControl.on('uploadComplete', function (p) {
        _debug("[soltn#initInrxCtrl] uploadComplete :", p);
        var files       = p.files;
        // 기존 목록 제거 후 처리
        dltObj.removeAll();
        for (var idx = 0, len=files.length; idx < len; idx++ ) {
            _debug("[soltn#initInrxCtrl] uploadComplete :", idx, "(파일정보)", files[idx]);
            var rowdata0 = {
                "transferID"    : p.transferID,
                "fileSizeTxt"   : psputils.getByteText(files[idx].fileSize, 2)
            };
            var rowdata = Object.assign({}, rowdata0, files[idx]); //$.extend(rowdata, files[i]);
            dltObj.insertRow(idx);
            dltObj.setRowJSON(idx, rowdata, true);
            _debug("[soltn#initInrxCtrl] uploadComplete : 행인덱스 =",  idx, ", (업로드정보)", dltObj.getRowJSON(idx));
        }
        _innoControl.removeAllFiles(); //업로드 완료후, 파일상자의 파일들은 삭제함
        fnSucc(dltObj.getAllJSON());
    });

    // #5. 업로드 오류 이벤트 핸들러 : 오류시 처리 핸들러
    _innoControl.on('uploadError', function(p) {
        _error("[soltn#initInrxCtrl] uploadError :[파일전송오류]", p);
        _innoControl.transferCancel();      // 전송 취소
        _innoControl.closeTransferWindow(); // 전송창 닫기
        _innoControl.removeAllFiles();      // 파일상자의 파일들은 삭제함
        dltObj.removeAll();                 // 파일업로드 된것을 삭제한다.
        var files = p.files;
        var strErrMsg = "";
        for (var i = 0; i < f.length; i++ ) {
            if (files[i].errorMessage !== undefined)
            strErrMsg += "\n" + files[i].errorMessage; //<br>
        }

        var m = "업로드 중 에러가 발생했습니다!";
            m+= strErrMsg;
        scutilo.showMsg("파일확인", m, function(p) { return false; });
    });


    if(innoParam != undefined) {
        var gridTrgt    = innoParam["gridTrgt"];
        // #6. Target Grid에서 cellclick을 할 경우 처리
        if(gridTrgt != undefined) {
            gridTrgt.unbind("oncellclick");
            gridTrgt.bind("oncellclick", function(rowIdx, col, colId) {
                if(colId.match('btn_atfl_del|btn_atfl_up|btn_atfl_down'))  {
                    if (colId === 'btn_atfl_del') {
                        _innoControl.removeFileById(dltObj.getCellData(rowIdx, 'rowID'));
                    }
                    else {
                        var files       = _innoControl.fileList.files;
                        var fileMaxIdx  = files.length - 1;
                        var elem        = files[rowIdx];

                        if (colId === 'btn_atfl_up' && rowIdx > 0) {
                            files.splice(rowIdx, 1);
                            files.splice(rowIdx - 1, 0, elem);
                        }
                        else if (colId === 'btn_atfl_down' && rowIdx < fileMaxIdx) {
                            files.splice(rowIdx, 1);
                            files.splice(rowIdx + 1, 0, elem);
                        }
                    }
                    pspsoltn.moveInnorixFiles(_innoControl, dltObj);
                }
            });
        }

        var btnInq      = innoParam["btnInq"];
        // 파일찾기 버튼객체가 있는 경우
        if(btnInq != undefined) {
//            console.log(`===================== BTN_INQ =`);
            var mltcsYn     = innoParam["mltcsYn"]||"Y";
            btnInq.unbind("onclick");
            btnInq.bind("onclick", function(e) {
//                console.log(`===================== mltcsYn = ${mltcsYn}`);
                if(mltcsYn == "Y") {
                    _innoControl.openFileDialog();
                }
                else {
                    _innoControl.openFileDialogSingle();
                }
            });
        }
        var btnDel      = innoParam["btnDel"];
        // 파일삭제 버튼객체가 있는 경우
        if(btnDel != undefined ) {
            btnDel.unbind("onclick");
            btnDel.bind("onclick", function(e) {
//                console.log(`===================== BTN_DEL =`);
                var arrChecked = gridTrgt.getCheckedIndex('transferID');
                if (arrChecked.length > 0) {
                    //  서버에 임시저장된 파일을 삭제한다.
                    for (var rowIdx of arrChecked) {
                        _innoControl.removeFileById(dltObj.getCellData(rowIdx, "rowID"));
                    }
                    pspsoltn.moveInnorixFiles( _innoControl, dltObj);
                }
            });
        }
    }
    return _innoControl;
}


/**
 * 이노릭스 객체의 파일순서에 맞춰 해당하는 데이터 소스에 적용한다.
 *
 *
 * @param   vInnoCtrl  이노릭스 컨트롤
 * @param   dltFiles   이노릭스 파일을 적용할 데이터리스트 객체
 * ============= ============ ==========================
 *  Date          Author       Description
 * ============= ============ ==========================
 *  2024.01.29   우근석        [NELS]최초 생성
 * ============= ============ ==========================
 */
pspsoltn.moveInnorixFiles  = function(vInnoCtrl, dltFiles) {
    dltFiles.removeAll();
    var stIdx       = dltFiles.getRowCount();
    for (var idx = 0, len = vInnoCtrl.fileList.getFileCount(); idx < len; idx++) {
        var fileObj = vInnoCtrl.fileList.files[idx];
        dltFiles.insertRow(idx)
        dltFiles.setRowJSON(idx, {
            "rowID": fileObj.rowID,
            "clientFileName": fileObj.printFileName,
            "fileSizeTxt": psputils.getByteText(fileObj.fileSize, 2)
        }, true);
    }
}


/**
 * 계정별로 등록가능한 용량 검증
 *
 * @param   fileSz   비교하려는 파일 크기
 * ============= ============ ==========================
 *  Date          Author       Description
 * ============= ============ ==========================
 *  2024.02.14   우근석        [NELS]최초 생성
 * ============= ============ ==========================
 */
pspsoltn.getElpUserByAtflSz = function(fileSz) {
    var isSucc = true;
    var isTest = true;
    com.executeAjax({
        action      : "/psp/pspA0m/selectElpUserByAtflSize.on",
        requestData : {},
        mode        : "synchronous",
        mediatype   : gcm.DEFAULT_OPTIONS_MEDIATYPE,
        method      : "POST",
        success     : function(_data) {
            var respObj = _data.responseJSON.data.elpUserAtflSz;
            var avlAtflSz   = respObj.elpUserAvlbAtflSz || 0;     // 계정별 가용용량
            var permAtflSz  = respObj.elpUserPermAtflSz || 0;     // 계정별 허용용량
            var useAtflSz   = respObj.elpUserUseAtflSz || 0;      // 계정별 사용용량

            if(fileSz > avlAtflSz && !isTest) {
                // W_0355: "주의사항!!!\t\n\n첨부파일의 용량(<%s>)이 초과되어 더이상 파일을 등록할 수 없습니다.\n현재 사용중인 용량은 <%s>이며 첨부가능한 용량은 <%s>입니다.",
                // scutilo.showMsg(scglblo.MSG.WARN, scutilo.getMsg(pspmsg.PSP.W_0355, psputils.getByteText(permAtflSz, 2), psputils.getByteText(useAtflSz, 2), psputils.getByteText(avlAtflSz, 2)), function(p) {return false;});

                permAtflSz = (Math.round((permAtflSz / 1024 / 1024) * 100) / 100);
                avlAtflSz = (Math.round((avlAtflSz / 1024 / 1024) * 100) / 100);
                useAtflSz = (Math.round((useAtflSz / 1024 / 1024) * 100) / 100);

                // W_0045: "전체 용량(<%s>MB)이 초과되어 파일을 더이상 등록할 수 없습니다. \t\n\n추가첨부 가능한 파일용량은 <%s>MB입니다.\t\n\n작성중 서류에 등록된 문서를 제출 및 삭제해 주시기 바랍니다.",
                scutilo.showMsg(scglblo.MSG.WARN, scutilo.getMsg(pspmsg.PSP.W_0045, permAtflSz, avlAtflSz), function(p) {return false;});
                isSucc = false;
//                return false;
            }
        },
        error       : function(_data) {
            var respObj = _data.responseJSON;
            _error(`ERROR ========> ${JSON.stringify(respObj)}`);
        }
    });
    return isSucc;
//    return true;
}


/**
 * 인증서(AnySign, Raonsecure) 팝법화면 호출.분기처리
 *
 * @param   aOption     4194304
 * @param   aPlain      "SCMAIN"
 * @param   aSvrCert    서버인증서
