pspsoltn.openCertf = function(aOption, aPlain, aSvrCert, aIdn, aUserCallback, aErrorCallback) {


    if (true == psp.env.isMobileApp()) {

        pspsoltn.raonCertf(aOption, aPlain, aSvrCert, aIdn, aUserCallback, aErrorCallback);
    }
    else {

        Sign_without_vid_web(aOption, aPlain, aSvrCert, aIdn,
             function(signedData) {
                send_vid_info(function(envValue) {
                    aUserCallback(signedData, envValue);
                });
            },
            aErrorCallback);
    }
}

