/**
 * <pre>
 * 화면 layer영역 부분을 출력한다.
 *
 *
 * @example ex)
 * psputils.layerPrntng(해당영역id);
 *
 * @param
 * @param
 *
 * @return
 * </pre>
 */
psputils.layerPrntng = function(contentId) {
    // 모바일 지원하지 않음.
    if (psp.env.isMobile() || psp.env.isMobileApp()) { // 모바일에서는 지원하지 않도록. (오픈 대비 임시 처리가 아닌 계속 지원하지 않음.)
        scutilo.showMsg(scglblo.MSG.WARN, scutilo.getMsg(pspmsg.PSP.W_1049), function() {
        });
        return false;
    }

    const iframe = document.createElement('iframe');
    iframe.style.position = "absolute";
    iframe.style.left = "-9999px"; // 화면에서 숨김
    document.body.appendChild(iframe);


    var win = iframe?.contentWindow || ( iframe?.contentDocument?.document || iframe?.contentDocument);
    win.document.open();
    win.document.write('<html class="if_print layer_prntng_class"><head><title></title>');
    var arrcss = document.getElementsByTagName("link");

    for (var idx = 0, len = arrcss.length; idx < len; idx++) {
        if(arrcss[idx].type == "text/css") {
            win.document.write(`<link href="${arrcss[idx].href}" type="text/css" rel="stylesheet">`);
        }
    }
    win.document.write('</head><body >');
    const scriptStr = `<script>
    window.onload = function() {
        setTimeout(() => {
			window.print();
			setTimeout(() => {
			    if (window.frameElement) {
			        window.parent.document.body.removeChild(window.frameElement);
			    }
			}, 5000);
        }, 500);
    };
    </script>`;
    win.document.write(scriptStr);
    win.document.write(document.getElementById(contentId).innerHTML);
    win.document.write('</body></html>');
    win.document.close();

}

