/**
 * <pre>
 * 콤마와 등호로 구분된 문자열을 객체형식으로 반환
 * (예) "key1=val1,key2=val2,..." 문자열을 json 형태로 반환
 *
 *
 * @example ex)
 * psputils.toJsonCommaEqual("key1=val1,key2=val2") ==> { "key1" : "val1" , "key2" : "val2" }
 *
 * @param 	소스문자열
 * @return	변환된 객체
 * </pre>
 */
psputils.toJsonCommaEqual = function (strval) {
	if ( null==strval || undefined==strval ) {
		return null;
	}

	var obj = {}
	var options = strval.split(",");

	for(var k=0; k<options.length; k++) {
		if ( null==options[k] || undefined==options[k] || ""==options[k] || ""==options[k].trim() ) {
			continue;
		}

		var optpairs = options[k].split("=");
		if ( null==optpairs || undefined==optpairs || optpairs.length<2) {
			continue;
		}
		obj[ optpairs[0] ] = optpairs[1];
	}
	return obj;
}

// 대문자가 있는 문자열이면 true
psputils.hasUpper = function (str) {
	if ( null==str || undefined==str ) {
		return false;
	}
	return str != str.replace(/[A-Z]/g, '');
}

//소문자가 있는 문자열이면 true
psputils.hasLower = function (str) {
	if ( null==str || undefined==str ) {
		return false;
	}
	return str != str.replace(/[a-z]/g, '');
}

//숫자문자가 있는 문자열이면 true
psputils.hasNumber = function (str) {
	if ( null==str || undefined==str ) {
		return false;
	}
	return str != str.replace(/[0-9]/g, '');
}

//space문자가 있는 문자열이면 true
psputils.hasSpace = function (str) {
	if ( null==str || undefined==str ) {
		return false;
	}
	return str != str.replace(/ /g, '');
}

//탭문자가 있는 문자열이면 true
psputils.hasTab = function (str) {
	if ( null==str || undefined==str ) {
		return false;
	}
	return str != str.replace(/\t/g, '');
}

//특수문자가 있는 문자열이면 true
psputils.hasSpecial = function (str) {
	if ( null==str || undefined==str ) {
		return false;
	}
	return str != str.replace(/[~!@#$%^&*()_+|.,<>?:;{}\-\[\]\'\"]/g, '');
}

// 일반문자[0-9a-zA-Z]가 3번이상 반복되는 문자열이면 true
psputils.hasCharRepeat = function (str) {
	if ( null==str || undefined==str ) {
		return false;
	}
	return /([0-9a-zA-Z])\1{3,}/.test(str);
}

// 4개 문자가 순차적으로 연속된 문자인 경우 true (예) 6789, abcd, BCDE, WXYZ (참고) 역순은 체크하지 않음(역순은 인지하지 못하는 경우 많음 예, EDC, ZYX
// 3개 순차나열은 너무 자주 걸림. 따라서 4개 체크
psputils.hasContinuousChars = function(str) {
	if ( null==str || undefined==str || str.length<4 ) { //4글자 미만이면 false 반환
		return false;
	}

	_debug("[psputils.hasContinuousChars] str :: ", str);
	for(var i=0; i<str.length-3; i++) {
		var c0 = str.charAt(i+0); var i0 = str.charCodeAt(i+0);
		var c1 = str.charAt(i+1); var i1 = str.charCodeAt(i+1); var d1 = i1 - i0;
		var c2 = str.charAt(i+2); var i2 = str.charCodeAt(i+2); var d2 = i2 - i1;
		var c3 = str.charAt(i+3); var i3 = str.charCodeAt(i+3); var d3 = i3 - i2;

		if ( 1==d1 && 1==d2 && 1==d3 ) {//if ( 1 == (i1-i0)*(i2-i1) ) {
			_trace("[psputils.hasContinuousChars] 순차나열된문자열 :: ["+c0+"]["+c1+"]["+c2+"]["+c3+"] = ["+ i0 +"]["+ i1 + "][" + i2 + "][" + i3 + "]");
			return true;
		}
	}
	return false;
}
psputils.hasNotContinuousChars = function(str) {
	return ! psputils.hasContinuousChars(str);
}

//비밀번호로 사용하지 못하는 문자(qwer,asdf,zxcv,!@#$) 문자열이면 true
psputils.hasRuleChar = function (str) {
	if ( null==str || undefined==str ) {
		return false;
	}

	if(str.toLowerCase().indexOf("qwer") != -1){
		return false;
	}

	if(str.toLowerCase().indexOf("asdf") != -1){
		return false;
	}

	if(str.toLowerCase().indexOf("zxcv") != -1){
		return false;
	}

	if(str.indexOf("!@#$") != -1){
		return false;
	}

	return "1";
}

