//주민등록번호 앞자리  검증(날짜체크)
psputils.validateRrno1 = function(str) {
	if ( null==str || undefined==str || str.length!=6 ) { // W_1002: "[<%s>] 항목은 최소 <%s>자 이상 입력하세요.",
		return scutilo.getMsg(pspmsg.PSP.W_0000, "[주민등록번호 앞자리] 항목은 6자리 숫자입니다!");
	}
	//var thedate = new Date('19'+str.substring(0,2), str.substring(2,4), str.substring(4)); //Date parse 는 검증안됨.
	var m = str.substring(2,4);
	if ( !isFinite(m) || parseInt(m)>12 || 1>parseInt(m) ) {
		return scutilo.getMsg(pspmsg.PSP.W_1011, "주민등록번호 앞자리", "(월)"); //W_1011: "[<%s>] 정보를 정확히 입력하세요. <%s>",
	}
	var d = str.substring(4);
	if ( !isFinite(d) || parseInt(d)>31 || 1>parseInt(d) ) {
		return scutilo.getMsg(pspmsg.PSP.W_1011, "주민등록번호 앞자리", "(일)");
	}
	switch( parseInt(m) ) {
	case 2 : if ( parseInt(d)>29 ) { return scutilo.getMsg(pspmsg.PSP.W_1011, "주민등록번호 앞자리", "(일)"); } break;
	case 4 :
