    insStr.indexOf("<") != -1 ||
    insStr.indexOf(">") != -1 ||
    insStr.indexOf("|") != -1 ||
    insStr.indexOf("=") != -1 ||
    insStr.indexOf("%") != -1 ||
    insStr.indexOf("&") != -1 ) {
