	        if( numMoney.substr( numMoney.length - i, 1 ) != "0" )
	        {
	          strMoney = "천" + strMoney;
	        }
	        break;
	        // 김봉중 2013.11.22 [13A-ECF-1029] 소가 입력 가능 자릿수 변경 end
	    }

	    switch( numMoney.substr( numMoney.length - i, 1 ) )
	    {
	      case "1":
	        strMoney = "일" + strMoney;
	        break;
	      case "2":
	        strMoney = "이" + strMoney;
	        break;
	      case "3":
	        strMoney = "삼" + strMoney;
	        break;
	      case "4":
	        strMoney = "사" + strMoney;
	        break;
	      case "5":
	        strMoney = "오" + strMoney;
	        break;
	      case "6":
	        strMoney = "육" + strMoney;
	        break;
	      case "7":
	        strMoney = "칠" + strMoney;
	        break;
	      case "8":
	        strMoney = "팔" + strMoney;
	        break;
	      case "9":
	        strMoney = "구" + strMoney;
	        break;
	    }
	}

	if(arrNumMoney.length>1){
        numMoney = arrNumMoney[1];
        var strPoint = "";

		for( i=1; i<=numMoney.length; i++ )
		{
		    switch( numMoney.substr( numMoney.length - i, 1 ) )
		    {
		        case "1":
		        	strPoint = "일" + strPoint;
			        break;
			    case "2":
			    	strPoint = "이" + strPoint;
			        break;
			    case "3":
			    	strPoint = "삼" + strPoint;
			        break;
			    case "4":
			    	strPoint = "사" + strPoint;
			        break;
			    case "5":
			    	strPoint = "오" + strPoint;
			        break;
			    case "6":
			    	strPoint = "육" + strPoint;
			        break;
			    case "7":
			    	strPoint = "칠" + strPoint;
			        break;
			    case "8":
			    	strPoint = "팔" + strPoint;
			        break;
			    case "9":
			    	strPoint = "구" + strPoint;
			        break;
    		    case "0":
		    	    strPoint = "공" + strPoint;
		            break;
		    }
		}

		if(!scutilo.isEmpty(strPoint)){
	        strMoney = strMoney+"."+strPoint;
		}

	}

	strMoney = strMoney + " "+unit;

	return strMoney;
}

/**
 * 객체/함수/문자열등을 문자열로 반환
 *
 * @param	obj	객체/함수/문자열등
 * @return	문자열
 * @see		(asis) du.str.getVal
 * ============= ============ ==========================
 *  Date          Author       Description
 * ============= ============ ==========================
 *  2023.02.09.   안종광        [NELS]최초 생성
 * ============= ============ ==========================
 */
psputils.toString = function(obj) {
	//var str = scutilo.isEmpty(obj) ? "" : ('object'==typeof obj ? JSON.stringify(obj) : 'function'==typeof obj ? obj.toString() : obj);
	if (scutilo.isEmpty(obj)) { return ""; }
	var str = "";
	if ( 'object'==typeof obj ) {
		if ( $.isPlainObject(obj) || $.isArray(obj) ) {
			str = JSON.stringify(obj);
		}
		else if ( obj instanceof Date ) {
			str = obj.toISOString();
		}
		else {
			str = String(obj);
		}
	}
	else if ( 'function'==typeof obj ) {
		str = obj.toString();
	}
	else if ( 'number'==typeof obj ) { //==$.isNumeric()
		str = String(obj);
	}
	else { //boolean, string
		str = String(obj);
	}
	return str;
}

// 바이트 배열을 헥사 문자열로 변경 (예) [ 171, 172 ] --> 'abac'
psputils.toHexString = function(byteArray) {
	return Array.from(byteArray, function(byte) {
		return ('0' + (byte & 0xFF).toString(16)).slice(-2);
	}).join('');
}

// 헥사 문자열을 바이트 배열로 변경 (예) 'abac' --> [ 171, 172 ]
psputils.toByteArray = function(hexString) {
	let bytes = [];
	for (let c = 0; c < hexString.length; c += 2) {
		bytes.push(parseInt(hexString.substr(c, 2), 16));
	}
	return new Uint8Array(bytes);
}

/**
 * 문자열에 XSS 보안처리를 수행한다.
 *
 * @param	s	보안처리할 문자열 또는 개체
 * @return	처리된 문자열
 * @see		(asis) du.str.clearXss
 * ============= ============ ==========================
 *  Date          Author       Description
 * ============= ============ ==========================
 *  2023.02.09.   안종광        [NELS]최초 생성
 * ============= ============ ==========================
 */
psputils.clearXss = function(s) {
    var str = psputils.toString(s);
        str = str.replace( /</g, "&#60;" )
            .replace( />/g, "&#62;" )
            .replace( /"/g, "&#34;" )
            .replace( /'/g, "&#39;" )
            .replace( /\\/g,"&#92;" )
            .replace( /\(/g,"&#40;" )
            .replace( /\)/g,"&#41;" );
   return str;
}

/**
 * XSS 보안처리된 문자열을 다시 원복시킨다.
 *
 * @param	s	원복할 문자열 또는 개체
 * @return	원복된 문자열
 * @see		(asis) du.str.unclearXss
 * ============= ============ ==========================
 *  Date          Author       Description
 * ============= ============ ==========================
 *  2023.02.09.   안종광       [NELS]최초 생성
 * ============= ============ ==========================
 */
psputils.unclearXss = function(s) {
    var str = psputils.toString(s);
    str = str.replace( /&lt;/g, "<" )
            .replace( /&gt;/g, ">" )
            .replace( /&#60;/g, "<" )
            .replace( /&#62;/g, ">" )
            .replace( /&#34;/g, '"' )
            .replace( /&#39;/g, "'" )
            .replace( /&#92;/g, "W" )
            .replace( /&#40;/g, "(" )
            .replace( /&#41;/g, ")" )
            .replace( /&amp;/g, "&" )
            .replace( /&nbsp;/g, " " )
            ;
    return str;
}

/**
 * 사건번호의 앞자리 0을 제거처리하고 리턴한다.
 *
 * @param str	사건번호 숫자
 * @return	result 사건번호
 * @see		(asis) ecf000.delPreZeros
 * ============= ============ ==========================
 *  Date          Author       Description
 * ============= ============ ==========================
 *  2023.04.04.   윤중식        [NELS]최초 생성
 * ============= ============ ==========================
 */
psputils.delPreZeros = function(str) {

    var patt1 = new RegExp("[1-9]", "g");

    var result = "";
    //사건번호 0000000인 경우 예외처리
    //사건번호 0000000으로 들어온 경우는 patt1.test(str)이 false
    if(patt1.test(str)) {
        var result = str.substring((patt1.lastIndex)-1);
    }

	return result;

}

