/**
 * <pre>
 * 웹스퀘어의 commonScope.js에서 제공하는 함수이며, (as-is) du.str.getMoney를 포괄하는 함수로서  psputils.js 에서 일부 수정하여 제공
 * ex)세번째자리마다 콤마 표시, 금액, setDisplayFormat("#,###&#46##0", "fn_userFormatter2") - 입력된 str에 포메터를 적용하여 반환한다.
 *
 * @param {String|Number} value 포멧터를 적용할 값
 * @param {String} type 적용할 포멧터 형식(Default:null,dollar,plusZero,won)
 * @memberOf com.num
 * @date 2020.05.16
 * @author Inswave Systems
 * @return {String} 포멧터가 적용된 문자열
 * @example
 * com.num.formatMoney("12345"); // 12,345
 * com.num.formatMoney("12345", "dollar"); // $12,345
 * com.num.formatMoney("12345", "plusZero"); // 123,450
 * com.num.formatMoney("12345", "won"); // 12,345원
 * @see du.str.getMoney
 *</pre>
 * ============= ============ ==========================
 *  Date          Author       Description
 * ============= ============ ==========================
 *  2023.06.26.   황은관       [NELS]최초 생성
 * ============= ============ ==========================
 */
psputils.formatMoney = function (value, type) {
    var amount;

    if (type == "plusZero") {
        amount = new String(value) + "0";
    } else {
        amount = new String(value);
    }

    amount = amount.split(".");

    var amount1 = amount[0].split("").reverse();
    var amount2 = amount[1];

    var output = "";
    for (var i = 0; i <= amount1.length - 1; i++) {
        output = amount1[i] + output;
        if ((i + 1) % 3 == 0 && (amount1.length - 1) !== i)
            output = ',' + output;
    }
    if ( null == value) {
        output = "0";
    }

    if (type == "dollar") {
        if (!amount2) {
            output = "$ " + output;
        } else {
            output = "$ " + output + "." + amount2;
        }
    } else if (type == "won") {
        if (!amount2) {
            output = output + " 원";
        } else {
            output = output + "." + amount2 + " 원";
        }
        if (null == value) {
            output = "0 원";
        }
    } else {
        if (!amount2) {
            output = output;
        } else {
            output = output + "." + amount2;
        }
    }

    return output;
};

