 *  2024.08.09.   우근석        모바일관련 적용
 * ============= ============ ==========================
 */
psputils.dwldEdmsFile = function(atflEdmsDocId, atflNm, elpUserId, type) {

    if ( scutilo.isEmpty(atflEdmsDocId) ) {
        _error("[u#dwldEdmsFile] 다운로드할 첨부파일EDMS문서ID 정보가 없습니다.");
        return false;
    }
    if ( scutilo.isEmpty(atflNm) ) {
        _error("[u#dwldEdmsFile] 다운로드할 첨부파일명 정보가 없습니다.");
        return false;
    }
    if ( scutilo.isEmpty(elpUserId || psp.session()) ) {
        _error("[u#dwldEdmsFile] 첨부파일 사용자 정보가 없습니다.");
        return false;
    }

	// 세션 없을 경우 다운로드용 임시 SID 생성 (sync)
	let isModeTmprSid = false;
    if (!psp.hasSid()) {
		isModeTmprSid = true;
		com.executeAjax({
			action : psp.CONTEXT_ROOT + "/psp001/makeDownloadTmprSid.on",
			mode : "synchronous",
			mediatype : gcm.DEFAULT_OPTIONS_MEDIATYPE,
			requestData : JSON.stringify({
			}),
			success : function(_data) {
			},
		});
    }


    // 다운로드 로직
    let downData = {
        "dma_downloadFile": {
        "jobKind"           : "PSP",
        "edmsUsePurpDvsCd"  : scutilo.isNotEmpty(type) ? type : "TP",
        "userId"            : elpUserId || psp.session(),
        "fileEdmsDocId"     : atflEdmsDocId,
        "fileNm"            : atflNm
    }};

    let request = new XMLHttpRequest();
        request.open('POST', '/smko/smkofile/downloadFile.on', true);
        request.setRequestHeader('Content-Type', 'application/json; charset=UTF-8');
        request.responseType = 'blob';
        request.onload = function (e) {
        	// 다운로드용 임시 SID 사용한 경우 삭제 (async)
        	try {
    			if (isModeTmprSid === true) {
    				com.executeAjax({
    					action : psp.CONTEXT_ROOT + "/psp001/removeDownloadTmprSid.on",
    					mode : "asynchronous",
    					mediatype : gcm.DEFAULT_OPTIONS_MEDIATYPE,
    					requestData : JSON.stringify({
    					}),

    					success : function(_data) {
    					},
    				});
    			}
        	} catch(e) {
        		_error("psputils.dwldEdmsFile", "removeDownloadTmprSid", e.stack);
        	}


            var filename = "";
            var disposition = request.getResponseHeader('Content-Disposition');
            if (disposition && disposition.indexOf('attachment') !== -1) {
                var filenameRegex = /filename[^;=\n]*=((['"]).*?\2|[^;\n]*)/;
                var matches = filenameRegex.exec(disposition);
                if (matches != null && matches[1])
                    filename = decodeURI(matches[1].replace(/['"]/g, ''));
            }
            if (this.status === 200) {
                var blob = this.response;
//                psputils.BlobToBase64(blob, filename);
                if( true==psp.env.isMobileApp() ) {
//                    console.log(` EDMS download ================> Mobile`);
                    psputils.BlobToBase64(blob, filename);
                }
                else {
//                    console.log(` EDMS download ================> Web`);
                    if (window.navigator.msSaveOrOpenBlob) {
                        window.navigator.msSaveBlob(blob, filename);
                    }
                    else {
                        var downloadLink = window.document.createElement('a');
                        var contentTypeHeader = request.getResponseHeader("Content-Type");
                        downloadLink.href = window.URL.createObjectURL(new Blob([blob], { type: contentTypeHeader }));
                        downloadLink.download = filename;
                        document.body.appendChild(downloadLink);
                        downloadLink.click();
                        document.body.removeChild(downloadLink);
                    }
				}
            }
            else {
            	// 다운로드용 임시 SID 사용한 경우 삭제 (async)
				try{
					if (isModeTmprSid === true) {
						com.executeAjax({
							action : psp.CONTEXT_ROOT + "/psp001/removeDownloadTmprSid.on",
							mode : "asynchronous",
							mediatype : gcm.DEFAULT_OPTIONS_MEDIATYPE,
							requestData : JSON.stringify({
							}),

							success : function(_data) {
							},
						});
					}
				} catch(e) {
					_error("psputils.dwldEdmsFile", "removeDownloadTmprSid", e.stack);
				}


                _error(JSON.stringify(this.response, null, '\t'));
                var errMsg = "EDMS " + scutilo.getMsg(pspmsg.PSP.E_0004); //E_0004: "파일 다운로드에 실패하였습니다."
                if ( this.response && this.response.errors.errorMessage ) {
                    errMsg+= "\n\n(원인) " + this.response.errors.errorMessage;
                }
                scutilo.showMsg(scglblo.MSG.ERROR, errMsg, function(rslt) {
                    return false;
                });
                return false;
            }
        };

        request.onreadystatechange = function (e) {
            if (request.readyState == 2) {
                if (request.status != 200) {
                    request.responseType = 'json'; //오류 시 json타입으로 변경
                }
            }
        }
    request.send(JSON.stringify(downData));
}



