/**
 * 이노릭스를 통해 업로드한 파일정보객체에서 '[서버]파일명'으로 docNm(문서명)으로 사용할 문자열 추출 (디폴트 사용을 위함)
 *
 * @param   aInrxFileInfo  첨부파일정보(이노릭스를 통해 업로드한 파일정보객체)
 * @return  docNm(문서명)
 * ============= ============ ==========================
 *  Date          Author       Description
 * ============= ============ ==========================
 *  2023.07.07.   안종광        [NELS] 최초생성
 * ============= ============ ==========================
 */
psputils.defineDocNm = function(aInrxFileInfo) {
    if ( null==aInrxFileInfo ) {
        return null;
    }
    var sDocNm = null;
    try {
        sDocNm = aInrxFileInfo["docNm"];
        if ( scutilo.isEmpty(sDocNm) ) {
            sDocNm = aInrxFileInfo["serverFileName"];
            if ( sDocNm.indexOf(".")>0 ) {
                sDocNm = sDocNm.substring(0, sDocNm.lastIndexOf("."));
            }
        }
    }
    catch(e) {
        sDocNm = null;
        _error("[u#defineDocNm]", e.message);
    }
    return sDocNm;
}

/**
 * EDMS 등록을 위한 요청 파라미터를 반환
 *
 * @param   aInrxFileInfo  첨부파일정보(이노릭스를 통해 업로드한 파일정보객체)
