 * ============= ============ ==========================
 *  2023.08.18.   안종광        [NELS]최초 생성
 * ============= ============ ==========================
 */
psputils.getTabCtlHandler = function(objTabCtl, sEventName) {
	if ( null==objTabCtl || scutilo.isEmpty(sEventName) ) {
		return null;
	}
	var handlerName = null;
	for(let i=0; i<objTabCtl.userEventList.length; i++) {
		var usrEvntNm = objTabCtl.userEventList[i].name;
		if ( sEventName.toLowerCase()==usrEvntNm || usrEvntNm.indexOf(sEventName.toLowerCase())>0 ) {
			handlerName = objTabCtl.userEventList[i].param.handler; //'scwin.tabCtrl_onbeforeselect'
			break;
		}
	}
	return handlerName;
}

/**
 * 지정한 Submission 객체의 ref 의 데이터컬렉션ID 목록을 배열로 반환
 * (예) data:json,"dma_csBasInf" ==> [ "dma_csBasInf" ]
 * (예) data:json,["dma_csBasInf","dma_param"] ==> [ "dma_csBasInf", "dma_param" ]
 *
 * @param	objSubmission	지정한 Submission 객체
 * @return	해당 프레임의 스코프 문자열
 * ============= ============ ==========================
 *  Date          Author       Description
 * ============= ============ ==========================
 *  2023.07.14.   안종광        [NELS]최초 생성
 * ============= ============ ==========================
 */
psputils.getSbmRefDcIdLst = function(objSubmission) {
	var dcIdList = [];
	try {
		let ref = objSubmission["ref"]; //(예) data:json,["dma_loginUser","dma_csBasInf"] // data:json,"dma_csBasInf"
		ref = ref.replace(/data:json,/,'').trim();
		let obj = JSON.parse(ref);
		if ( Array.isArray(obj) ) {
			dcIdList = obj;
		}
		else {
			dcIdList.push(obj);
		}
	}
	catch(e) {
		dcIdList = null;
	}
	if ( null==dcIdList ) {
		dcIdList = [];
		try {
			let ref = objSubmission["ref"]; //(예) data:json,["dma_loginUser","dma_csBasInf"] // data:json,"dma_csBasInf"
			ref = ref.replace(/data:json,/,'').trim();
			let arrDcId = ref.split(",");
			for(var i=0; i<arrDcId.length; i++) {
				var dcid = arrDcId[i].replace(/["\[\]\{\}'\s]/g,''); // 특수문자들 모두 제거 []{}'"
				dcIdList.push(dcid);
			}
		}
		catch(e) {
			dcIdList = null;
		}
	}
	return dcIdList;
}

/**
 * <pre>
 * 숫자로만 구성되어있는지 확인
 *
 * </pre>
 *
 * @parameter str(문자열): 필수
 * @return boolean(true : 영문자숫자조합, false : 영문자숫자조합 아님)
 * (asis) du.core.js(du.chk.isNum)
 * ============= ============ ==========================
 *  Date          Author       Description
 * ============= ============ ==========================
 * 2023.08.06.    김기오         [NELS] 최초생성
 * ============= ============ ==========================
 *
 */
psputils.isCombineNum = function (str) {
    if (null == str || undefined == str || !(typeof str == "string")) {
        return false;
    }
    return /[0-9]/g.test(str) && str.replace(/[0-9]/g, "").length == 0;
}


/**
 * ','가 포함된 숫자형 문자열을 ','가 포함되지 않은 숫자형 문자열로 변환한다.
 * (예) "1,335,260" => "1335260"
 * (asis) wsh.cfWshToExcludeComma
 *
 * @param	{String} commaNumStr
 * @return	{String} numStr
 * ============= ============ ==========================
 *  Date          Author       Description
 * ============= ============ ==========================
 *  2023.08.05.   김기오        [NELS]최초 생성
 * ============= ============ ==========================
 */
psputils.getExcludeCommaNumStr = function(numStrWithComma) {
    var result = "";
    for (var i = 0; i < numStrWithComma.length; i++) {
        if (numStrWithComma.substr(i, 1) != ",") {
            result = result + numStrWithComma.substr(i, 1);
        }
    }
    return result;
}

/**
 * 소숫점 입력가능한 숫자 검증
 * (asis) cfInputAmtMoneyForDemical
 *
 * @param	{String} 검증할 컴포넌트(inputBox)
 * @param   {Number} 소숫점 이하 자리수
 * @return	{String} 결과
 * ============= ============ ==========================
 *  Date          Author       Description
 * ============= ============ ==========================
 *  2023.08.05.   김기오        [NELS]최초 생성
 * ============= ============ ==========================
 */
psputils.chkAndgetDecimalNumStr = async function(obj, length) {
	var numStr = obj.getValue();
	var flag = true;
	if(scutilo.isEmpty(numStr)){
		obj.setValue("");
		obj.focus();
		return;
	}
	var numStrWithoutComma = psputils.getExcludeCommaNumStr(numStr);
	var numArr = numStrWithoutComma.split(".");

	if(numArr.length >= 3){
        var msg = scutilo.getMsg(pspmsg.PSP.W_0628); //asis: "숫자만 입력 가능한 항목입니다."
        await psp.showMsg(scglblo.MSG.ERROR, msg, () => {
    		obj.setValue(0);
    		obj.focus();
    		flag = false;
            return;
        });
	}

	if(numArr[0] != "" && !psputils.isCombineNum(numArr[0])){
        var msg = scutilo.getMsg(pspmsg.PSP.W_0628); //asis: "숫자만 입력 가능한 항목입니다."
        await psp.showMsg(scglblo.MSG.ERROR, msg, () => {
    		obj.setValue(0);
    		obj.focus();
    		flag = false;
            return;
        });
	}

	if(numArr.length == 2 && numArr[1] != "" && !psputils.isCombineNum(numArr[1])){
        var msg = scutilo.getMsg(pspmsg.PSP.W_0628); //asis: "숫자만 입력 가능한 항목입니다."
        await psp.showMsg(scglblo.MSG.ERROR, msg, () => {
    		obj.setValue(0);
    		obj.focus();
    		flag = false;
            return;
        });
	}
	if(flag){
		if(numArr.length == 2 && numArr[1].length > length){
			numArr[1] = numArr[1].substring(0, length);
		}
		if(numArr.length == 1){
			if(numArr[0] == ""){
				obj.setValue(numArr[0]);
			}else{
			obj.setValue(String(Number(numArr[0])));
			}
		}else{
			obj.setValue(numArr[0] + "." + numArr[1]);
		}
	}
}

