	//start 그리드 2줄로 표현되는경우 엑셀에서도 표현가능하도록 수정
	var headRow2Arr = objGridView.struct.head.rowArr[1];
	var bodyRow2Arr = objGridView.struct.body.rowArr[1];
	if(undefined != headRow2Arr){
		var initHeadRowArr = new Array();
		var initBodyRowArr = new Array();
		for(var k=0; k<headRow2Arr.length; k++) {
			if(headRowArr[k].value != ""){
				initHeadRowArr.push(headRowArr[k]);
			}
		}
		for(var k=0; k<headRow2Arr.length; k++) {
			if(headRow2Arr[k].value != ""){
				initHeadRowArr.push(headRow2Arr[k]);
			}
		}
		for(var k=0; k<bodyRowArr.length; k++) {
			if(bodyRowArr[k].id != ""){
				initBodyRowArr.push(bodyRowArr[k]);
			}
		}
		for(var k=0; k<bodyRow2Arr.length; k++) {
			if(bodyRow2Arr[k].id != ""){
				initBodyRowArr.push(bodyRow2Arr[k]);
			}
		}
		headRowArr = initHeadRowArr;
		bodyRowArr = initBodyRowArr;
	}
	//end 그리드 2줄로 표현되는경우 엑셀에서도 표현가능하도록 수정

	var gridInfo = {};
	var gridColInfoList = [];

	var b = 0; //바디 인덱스
	for(var h=0; h<headRowArr.length; h++) {
		var cellId = cellIdList[h];
		if ( null==headRowArr[h] || null==bodyRowArr[h] ) {
			continue;
		}
		var colInfo = {
			"colIndex": h,
			"colId": bodyRowArr[b].id,
			"colText": headRowArr[h].value,
			"colType": bodyRowArr[b].inputType,
			"colMode": bodyRowArr[b].displayMode,
			"width": bodyRowArr[b].width
		};
		if ( Number.parseInt(headRowArr[h].colSpan) > 1 ) {
			b += (Number.parseInt(headRowArr[h].colSpan) - 1); //헤더의 칼럼스팬이 있으면, 바디 인덱스 필요한 만큼 + 함.
		}
		gridColInfoList.push(colInfo);
		b++;
	}
	gridInfo["colInfoList"] = gridColInfoList;

	return gridInfo;
}

/**
 * 지정한 데이터를 조회하여 엑셀파일 생성후 다운로드 처리함.
 *
 * @param  targetUrl  조회후 다운로드 처리할 URL
 * @param  params     입력파라미터 { "gridInfo":"그리드메타정보(엑셀구조)", "dma_param":"조회조건파라미터" }
 * ============= ============ ==========================
 *  Date          Author       Description
 * ============= ============ ==========================
 *  2023.09.01.   안종광        [NELS] 최초생성
 * ============= ============ ==========================
 */
psputils.downloadDataXlsx = function(targetUrl, params) {
    if ( scutilo.isEmpty(targetUrl) ) {
        var msg = scutilo.getMsg(pspmsg.PSP.E_0000, "다운로드 경로 정보가 없습니다.");
        _error("[u#downloadDataXlsx] " + msg);
        scutilo.showMsg(scglblo.MSG.ERROR, msg, function(rslt) { return false; });
        return false;
    }
    if ( null==params || null==params["gridInfo"] ) {
        var msg = scutilo.getMsg(pspmsg.PSP.E_0000, "그리드 메타 정보가 없습니다.");
        _error("[u#downloadDataXlsx] " + msg);
        scutilo.showMsg(scglblo.MSG.ERROR, msg, function(rslt) { return false; });
        return false;
    }
//    let params = {
//        "gridInfo": gridInfo, //그리드 정보(필수) : 'colInfoList'=그리드칼럼정보 목록(필수)
//        "dma_param": dma_excel.getJSON(), //업무데이터를 조회하기 위한 검색조건 데이터맵 (이정보는 각 업무 컨트롤러에서 처리)
//    };

    let request = new XMLHttpRequest();
        request.open('POST', targetUrl, true); // (ex) '/psp/psp221/downloadExcelInProgCsLst.on'
        request.setRequestHeader('Content-Type', 'application/json; charset=UTF-8');
        request.responseType = 'blob';
        request.onload = function (e) {
            var filename = "";
            var disposition = request.getResponseHeader('Content-Disposition');
            if (disposition && disposition.indexOf('attachment') !== -1) {
                var filenameRegex = /filename[^;=\n]*=((['"]).*?\2|[^;\n]*)/;
                var matches = filenameRegex.exec(disposition);
                if (matches != null && matches[1])
                    filename = decodeURI(matches[1].replace(/['"]/g, ''));
            }
            if (this.status === 200) {
                var blob = this.response;
                if( true==psp.env.isMobileApp() ) {
//                    console.log(` EDMS download ================> Mobile`);
                    psputils.BlobToBase64(blob, filename);
                }
                else {
                    if (window.navigator.msSaveOrOpenBlob) {
                        window.navigator.msSaveBlob(blob, filename);
                    }
                    else {
                        var downloadLink = window.document.createElement('a');
                        var contentTypeHeader = request.getResponseHeader("Content-Type");
                        downloadLink.href = window.URL.createObjectURL(new Blob([blob], { type: contentTypeHeader }));
                        downloadLink.download = filename;
                        document.body.appendChild(downloadLink);
                        downloadLink.click();
                        document.body.removeChild(downloadLink);
                    }
                }
                WebSquare.layer.hideProcessMessage();
            }
            else {
            	WebSquare.layer.hideProcessMessage();
                _error(JSON.stringify(this.response, null, '\t'));
                var errMsg = "엑셀 " + scutilo.getMsg(pspmsg.PSP.E_0004); //E_0004: "파일 다운로드에 실패하였습니다."
                if ( this.response && this.response.errors.errorMessage ) {
                    errMsg+= "\n\n(원인) " + this.response.errors.errorMessage;
                }
                scutilo.showMsg(scglblo.MSG.ERROR, errMsg, function(rslt) {
                    return false;
                });
                return false;
            }
        };
        request.onreadystatechange = function (e) {
            if (request.readyState == 2) {
                if (request.status != 200) {
                    request.responseType = 'json'; //오류 시 json타입으로 변경
                }
            }
        }
    request.send(JSON.stringify(params));
    WebSquare.layer.showProcessMessage("엑셀파일 다운로드중입니다...");
}


