 * @returns {string} - 단어의 마지막 글자에 받침이 있으면 "을"을 그렇지 않으면 "를"을 반환.
 * ============= ============ ==========================
 *  Date          Author       Description
 * ============= ============ ==========================
 *  2024.05.29.   백인호        [NELS] 최초생성
 * ============= ============ ==========================
 */
psputils.getMokJosa = function(word) {
	// 문자가 아닐 경우 "를" return
	if (!word || typeof word !== 'string') {
		return "를";
	}

	const lastChar = word[word.length - 1];
	const lastCharCode = lastChar.charCodeAt(0);

	// 마지막 문자가 한글인지 확인
	const isHangul = lastCharCode >= 0xAC00 && lastCharCode <= 0xD7A3;
	if (!isHangul) {
		return "를";
	}

	// 한글 유니코드 범위 내에서 마지막 글자의 받침 확인
	const isFinalConsonant = (lastCharCode - 0xAC00) % 28 > 0;

