/**
 * 브라우저 정보 목록
 * (주의) 크롬베이스 다른 브라우저 먼저 체크하기 위해 배열앞쪽에 배치
 */
psputils.dlt.setCellData = function(objDlt, rowIdxs, columnId, value) {
	if ( null==objDlt || null==rowIdxs || null==columnId ) {
		return;
	}
	var rowIndexes = [].concat(rowIdxs); //배열로 바꿈 1 ==> [1], [1,2,3] ==> [1,2,3];
	for (let i=0; i<rowIndexes.length; i++) {
		objDlt.setCellData(rowIdxs[i], columnId, value); //원본 첨부파일 EDMS아이디 설정
	} //(ex) dlt_atch.setCellData(rowIdx, "atflEdmsDocId", obj["fileEdmsDocId"]);
}
psputils.getRow = function (list, keyObj) {
	if (list == null || list[0] == null) {
		return;
	}

	for (i = 0; i < list.length; i++) {
		var data = list[i];
		for (j = 0; j < Object.keys(keyObj).length; j++) {
			isMatched = true;
			var key = Object.keys(keyObj)[j];
			if (data[key] != keyObj[key]) {
				isMatched = false;
				break;
			}
		}
		if (isMatched) {
			data.idx = i;
			return data;
		}
	}
	return null;
};

