];

/**
 *
 */
psp.browser._searchString = function( data ) {
    for (var i=0; i<data.length; i++) {
        var dataString = data[i].string;
        var dataProp = data[i].prop;
        this.versionSearchString = data[i].versionSearch || data[i].identity;
        if (dataString) {
            if (dataString.indexOf(data[i].subString) != -1) {
                return data[i].identity;
            }
        }
        else if (dataProp) {
            return data[i].identity;
        }
    }
}

/**
 *
 */
psp.browser._searchVersion = function( verStr ) {
    var idx = verStr.indexOf( this.versionSearchString );
    if ( idx == -1 ) return;
    return parseFloat( verStr.substring(idx + this.versionSearchString.length + 1) );
}

/**
 * 브라우저 종류 (예) Chrome, Edge, Firefox, Opera, Safari
 */
psp.browser.browser = psp.browser._searchString( psp.browser._browser ) || "unknown";

