        _trace("[#o_m_c]", "<menu element clicked> <this.id>=", this.id);
    }
    catch(e) {
        menuInfoObj = paramMenuInfo;
    	if ( null!=paramMenuInfo && 5 > Object.keys(paramMenuInfo).length ) {
    		menuInfoObj = psp.getMenuInfo( paramMenuInfo['pgmUrl'] );
    	}
        _trace("[#o_m_c]", "<menuInfo>", menuInfoObj);
    }

    var mPgmId = menuInfoObj["pgmUrl"];
    _trace("[#o_m_c]", "<menu info> pgmUrl(m)", mPgmId, ", <info>", menuInfo); // window.location.href, window.location.search

    if ( scutilo.isEmpty(mPgmId) ) { //메뉴정보 없음
        var subCnt = menuInfoObj["subCnt"];
        if ( subCnt>0 ) {
            _debug("[#o_m_c] sub menu exists."); //이동할 메뉴에 프로그램ID(pgmUrl)이 매핑되지 않음 + 하위메뉴있음.
