        let child1stMenuSize = null==child1stMenuList ? 0 : child1stMenuList.length;

        if ( 0==child1stMenuSize ) {
            var sMenuOpt = menuInfoObj["menuOpt"];
            if ( scutilo.isNotEmpty(sMenuOpt) ) { //연결된 화면이 없지만 내외부링크 정보가 있는 경우
                let menuOpt = JSON.parse(sMenuOpt);
                let linkUrl = menuOpt.url;
                let linkAct = menuOpt.action;
                _debug("[#o_m_c]", "<menuOpt>", menuOpt);
                if ( scutilo.isNotEmpty(linkAct) && linkAct === "location.href" ) {
                    location.href = linkUrl;
                }
                else { // (default)window.open
                    let winOpt = "width="+ window.innerWidth + ", height=" + window.innerHeight + ", directories=yes, location=yes, menubar=yes, scrollbars=yes, status=yes, resizable=yes, toolbar=yes"
                    window.open(linkUrl, "_blank", winOpt);
