/**
 * 스크린ID(프로그램ID)로 로드된(로컬스토리지) 메뉴정보를 찾아서 반환
 */
pspadmin.getMenuInfo = function(screenId) {
	if ( scutilo.isEmpty(screenId) || "1"==screenId ) {
		return null;
	}
    _trace("[#g_m_i]", "<screenId>", screenId);

    var menulist = psp.ss.get(pspadmin.LS_KEY_MENU, true);
    if ( scutilo.isEmpty(menulist) ) {
    	//allmenu = psp.get_allmenu_list(true);
    	menulist = pspadmin.getUserMenu(true);
    }
    /*
     * {"dumy":null,"level":2,"elpMenuSrno":1701,"elpScrnId":61101,"uprElpMenuSrno":17,"menuNm":"공지사항","menuGrpDvsCd":null,
     * "menuUseYn":"Y","userElpMenuStngPsblYn":"N","topElpMenuUseYn":"N","leftElpMenuUseYn":"N","bgngElpMenuStngPsblYn":"N",
     * "elpMenuDpth":2,"elpMenuSortTurn":1,"elpMenuAthoTypCd":"3","elctnSbmsnSystmScrnNm":"공지사항","pgmUrl":"PSP611M01"}
     */

    var objMenuFound = null;
	var _list = [];

	menulist.forEach(function (mnInfo, index) {
		if ( screenId == mnInfo.pgmUrl || screenId == mnInfo.elpMenuSrno ) { //pgmUrl 또는 elpScrnId로도 검색
			_list.push(mnInfo); _trace("[#g_m_i] 메뉴 :", mnInfo);
		}
	});
	var _cnt  = null==_list ? 0 : _list.length;
	if ( 1>_cnt ) {
		_warn("[#g_m_i]", "조회된 메뉴 정보가 없습니다. <screenId>", screenId);
		return null;
	}
	objMenuFound = _list[_cnt-1]; //디폴트(맨마지막)

	var pgparam = psp.ss.get(pspadmin.SS_PAGEPARAM, true);
	if ( null!=pgparam && pgparam.pgmUrl && pgparam.elpMenuSrno ) { //세션파라미터에 메뉴정보가 설정되어 있으면,
		_list.forEach(function (mnInfo, index) {
			if ( pgparam.elpMenuSrno == mnInfo.elpMenuSrno ) {
				objMenuFound = mnInfo;
			}
		});
	}
	return objMenuFound;

};

