/**
 * 로드된(로컬스토리지) 메뉴정보에서 지정한 메뉴포함함 상위 메뉴를 찾아서 배열로 반환
 *
 * (예) 3레벨 메뉴이면 [3레벨메뉴, 2레벨메뉴, 1레벨메뉴] 길이 3인 배열반환
 * (예) 2레벨 메뉴이면 [2레벨메뉴, 1레벨메뉴] 길이 2인 배열반환
 * (예) 1레벨 메뉴이면 [1레벨메뉴] 길이 1인 배열반환
 */
pspadmin.hierarchyMenuList = function(mnInfo) {
	if ( null==mnInfo ) { return []; }
	var menus = [];
		menus.push(mnInfo);
	var uppers = pspadmin.hierarchyMenuList( pspadmin.getMenuInfo( mnInfo["uprElpMenuSrno"] ) );
	return menus.concat(uppers);
}

//지정한 메뉴의 첫번쨰  자식메뉴 목록을 배열로 반환. (참고) hierarchyMenuList 역순
//(예) '사건유형별 절차안내' 이면 [ [사건유형별 절차안내, ]공통안내, 전자소송안내, 전자소송의 개념 ]
pspadmin.hierarchyFirstChildMenuList = function(mnInfo, selfInclude=false) {
	if ( null==mnInfo ) { return []; }
	var arrMenu  = [];
	var prevMnNo = 0;

	for(_m of psp.ss.get(pspadmin.LS_KEY_MENU, true)) {
		if ( _m["level"]==mnInfo["level"] && _m["elpMenuSrno"]==mnInfo["elpMenuSrno"] ) {
			prevMnNo = _m["elpMenuSrno"];
			if ( true===selfInclude ) {
				arrMenu.push(_m);
			}
			continue;
		}
		if ( prevMnNo>0 && prevMnNo == _m["uprElpMenuSrno"] ) {
			prevMnNo = _m["elpMenuSrno"];
			arrMenu.push(_m);
			continue;
		}
		if ( prevMnNo>0 && _m["level"]==mnInfo["level"] ) {
			break;
		}
	}
	return arrMenu;
}

