/**
 * <pre>
 * 모바일전자소송포털 설정관리 js
 * </pre>
 *
 * @see    pspstng.js
 */
var pspstng = {

    /*
     * 컴포넌트 ITEMSET
     */
    KEY	: "scourt.psp",

    /*
     * <pre>
     * 설정값
     *
     * VAL -> 설정값
     * bioLoginYn 	-> 생체인식 로그인
     * </pre>
     */
    VAL	: {
		bioLoginYn :"N",
    },
};

/**
 * <pre>
 * 사용자설정 읽기
 *
 * @return  사용자설정 값
 * pspstng.VAL {
 * bioLoginYn 	-> 생체인식 로그인
 * }
 * </pre>
 */
pspstng.read = function() {

	let strSetting = WebSquare.localStorage.getItem(pspstng.KEY);
	if (scutilo.isNotEmpty(strSetting)) {
		pspstng.VAL = JSON.parse(strSetting);
	}

//	console.log("# pspstng.read", pspstng.VAL);

	return pspstng.VAL;
};

/**
 * <pre>
 * 사용자설정 저장
 *
 * @param  사용자설정 값
 * pspstng.VAL {
 * bioLoginYn 	-> 생체인식 로그인
 * }
 * </pre>
 */
pspstng.write = function(setting) {

	if (scutilo.isNotEmpty(setting)) {
    	pspstng.VAL = setting;
	}
	WebSquare.localStorage.setItem(pspstng.KEY, JSON.stringify(pspstng.VAL)); //현재 메뉴
//	console.log("# pspstng.write", pspstng.VAL);
};
/**
 * <pre>
 * 생체인식 로그인여부
 *
 * @return {Boolean} -생체인식 로그인여부
 * </pre>
 */
pspstng.isBioLogin = function() {
	return pspstng.yn2Bool(pspstng.VAL.bioLoginYn);
};
pspstng.setBioLogin = function(bSetting) {
	pspstng.VAL.bioLoginYn = pspstng.bool2Yn(bSetting);
};

/**
 * <pre>
 * true/false 를 "Y"/"N"으로 변환
 *
 * @param {Boolean} boolTf : True or False
 * @return {String} "Y" or "N"
 * </pre>
 */
pspstng.bool2Yn = function(boolTf) {

	return boolTf ? "Y" : "N";
};

/**
 * <pre>
 * "Y"/"N"을 true/false 로 변환
 *
 * @param {String} strYn : "Y" or "N"
 * @return {Boolean} True or False
 * </pre>
 */
pspstng.yn2Bool = function(strYn) {

	return (strYn === "Y");
};

