/**
 * <pre>
 * psp pspschkey - 단축키 설정 공통 js
 * </pre>
 * 
 * @constructor
 */
var pspschkey = function() {
    /**
     * hidden 변수
     * 
     * @ignore
     */
    var $_psp = {
            //브라우저 단축키의 동작을 정지 시킴 : false일때 브라우저 기본 단축키 동작 정지시킴 true로 설정하면 
            //기본 브라우저 단축키가 반영됨
            IS_USE_BROWSER_SHORTCUT : false,
            _shortcutFunc : {},
            //단축키 keydown 이벤트
            _keydownEvent : function(e) {

                try {
                    var lastKey = e.key || e.keyCode || e.which;
                    var complexKey = "";

                    if (e.ctrlKey && e.altKey) {
                        complexKey = "ctrlAltKey";
                    } else if (e.ctrlKey && e.shiftKey) {
                        complexKey = "ctrlShiftKey";
                    } else if (e.altKey && e.shiftKey) {
                        complexKey = "altShiftKey";
                    } else {
                        if (e.altKey) {
                            complexKey = "altKey";
                        } else if (e.ctrlKey) {
                            complexKey = "ctrlKey";
                        } else if (e.shiftKey) {
                            complexKey = "shiftKey";
                        } else {
                            complexKey = "singleKey";
                        }
                    }

                    // (Ctrl, Alt, Shift)가 아닌 lastKey가 인식될 경우 
                    if (lastKey != "Control" && lastKey != "Alt" && lastKey != "Shift") {

                        // KeyboardEvent.key 값이 전달되지 않는 구형 브라우저에서 lastKey 재설정
                        if ((typeof lastKey === "number") || (lastKey === "Unidentified")) {
                            if (e.keyCode >= 112 && e.keyCode <= 123) {
                                var funtionKey = [ "F1", "F2", "F3", "F4", "F5", "F6", "F7", "F8", "F9", "F10", "F11", "F12" ];
                                lastKey = funtionKey[e.keyCode - 112];
                            } else if (e.keyCode == 9) {
                                lastKey = "Tab";
                            } else if (e.keyCode == 27) {
                                lastKey = "Escape"; 
                            } else if (e.keyCode == 187) {
                                lastKey = "="; 
                            } else if (e.keyCode == 189) {
                                lastKey = "-"; 
                            } else {
                                if (e.keyCode === undefined) 
                                	lastKey = "";   //20230531 comchief  autocomplete select
                                else lastKey = String.fromCharCode(e.keyCode).toUpperCase();
                            }
                        }

                        if (pspschkey.$_psp._isPreventKey(complexKey, lastKey)) {
                            // 아래의 코드는 단축키 로그를 출력하기 위한 코드로 실제 프로젝트에 적용 시 주석으로 막으시기 바랍니다.
                            // 원하는 단축키 동작이 있을 경우
                            // searchBox 컴포넌트에 포커스가 위치한 경우에는 scwin.writeKeyLog 함수를 찾지 못해서 로그 출력이 안됩니다.
                            if (typeof $p.debug.getScope(document.activeElement).scwin.writeKeyLog === "function") {
                                $p.debug.getScope(document.activeElement).scwin.writeKeyLog(complexKey, lastKey);
                            }

                            // 브라우저 단축키의 동작을 정지 시킴
                            if (pspschkey.$_psp.IS_USE_BROWSER_SHORTCUT === false) {
                                // IE에서 F1 Key 동작을 중지 시킴
                                if ('onhelp' in window) {
                                    window.onhelp = function() {
                                        return false;
                                    }
                                }

                                //tab, enter, shift+tab 은 제외 : tab 클릭시 다음 컴포넌트 이동, 좌측메뉴에서 tab, enter 키 사용   
                                if ( (complexKey == "singleKey" && lastKey == "Tab") 
                                		|| (complexKey == "singleKey" && lastKey == "Enter") 
                                			|| (complexKey == "shiftKey" && lastKey == "Tab") ) {
                                }
                                else {
	                                if (e.preventDefault) {
	                                    e.preventDefault();
	                                } else if (e.returnValue) {
	                                    e.returnValue = false;
	                                }
                                }
                            }
                        }
                    }
                } catch (ex) {
                    console.error(ex);
                }               
            }, 
            //단축키 기본 설정  및 브라우저 기본 단축키 기능을  적용할지 여부 설정
            _isPreventKey : function(complexKey, lastKey){
                if (lastKey === undefined) lastKey = "";   //20230531 comchief  autocomplete select
                var exTag = ["INPUT", "TEXTAREA", "IFRAME"]; 
                var controlKeyList = ["F1", "F2", "F3", "F4", "F5", "F6", "F7", "F8", "F9", "F10", "F11", "F12", "ctrlKey", "altKey", "ctrlAltKey", "ctrlShiftKey", "altShiftKey" , "Escape"]; //, "Tab" 제거

                var activeTag = document.activeElement.tagName;
                var ucLastKey = lastKey.toUpperCase();

                if ((exTag.indexOf(activeTag) === -1)) {
                    return true;
                } else if ((exTag.indexOf(activeTag) > -1) && (((complexKey === "ctrlKey") && (ucLastKey === "A"))
                    || ((complexKey === "ctrlKey") && (ucLastKey === "C")) || ((complexKey === "ctrlKey") && (ucLastKey === "V"))
                    || ((complexKey === "ctrlKey") && (ucLastKey === "X")) || ((complexKey === "ctrlKey") && (ucLastKey === "Y"))
                    || ((complexKey === "ctrlKey") && (ucLastKey === "Z")) || ((complexKey === "ctrlShiftKey") && (ucLastKey === "Z")))) {
                    return false;
                } else if ((controlKeyList.indexOf(complexKey) !== -1) || (controlKeyList.indexOf(lastKey) !== -1)) {
                    return true;
                }
            },
            //keydown 이벤트 addEventListener
            _setShortKeyDownAction : function() {
                var shortcutTargetElement = document;
                if (shortcutTargetElement.addEventListener) {
                    shortcutTargetElement.addEventListener('keydown', pspschkey.$_psp._keydownEvent);
                } else if (shortcutTargetElement.attachEvent)  {
                    shortcutTargetElement.attachEvent('keydown', pspschkey.$_psp._keydownEvent);
                }
            }
    };

    /**
     * main 변수 
     * 
     * @ignore
     */
    var $main = {
            //keydown 이벤트 addEventListener
            setShortKeyDownAction : function() {
                var _self = pspschkey;
                _self.$_psp._setShortKeyDownAction();
            }
    };

    return {
        $_psp: $_psp,
        $main: $main,
    }
} ();

