		var currentTime = new Date().getTime();
		if ((currentTime - gStartTime) > 2000) {
			clearInterval(gTimeIntervalFunc);

			var aGuideModule = __SANDBOX.loadModule("guidewindow");
			gGuideDialog = aGuideModule({
				type: "login",
