						aSignFileOption += XW_OPTION_NO_SELECTFILE;
					if (aSignFileOption & XW_OPTION_TEMP_SAVE)
						aSignFileOption -= XW_OPTION_TEMP_SAVE;
					if (aSignFileOption & XW_OPTION_CHECK_WRITE_FILE)
						aSignFileOption -= XW_OPTION_CHECK_WRITE_FILE;
