					aErrCallback = gErrCallback_common;

				_show_guidewindow = function () {
					if (aGuideDialog) return;

					aGuideModule = __SANDBOX.loadModule("guidewindow");
					aGuideDialog = aGuideModule({
						type: "loading",
						args: "",
						onconfirm: "",
						oncancel: function () { aGuideDialog.dispose(); }
					});
